import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface HardwareStats {
  gpuName: string;
  gpuTemp: number;
  gpuLoad: number;
  cpuName: string;
  cpuLoad: number;
  ramUsage: number;
}

export enum AppState {
  IDLE = 'IDLE',
  PREPARING = 'PREPARING',
  CHOPPING = 'CHOPPING',
  STOPPING = 'STOPPING'
}

export interface WorkloadInfo {
  id: string;
  type: 'Container' | 'Mining' | 'AI_Inference';
  description: string;
  rewardRate: number; // USD per hour
}

export interface ChatMessage {
  id: string;
  role: 'user' | 'model';
  text: string;
  timestamp: Date;
}

import { GoogleGenAI } from "@google/genai";

const getClient = () => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) {
    console.warn("API Key not found in environment");
    return null;
  }
  return new GoogleGenAI({ apiKey });
};

/**
 * Chat with the "Salad Chef" assistant using Gemini.
 * It acts as a support agent for the Salad platform.
 */
export const chatWithChef = async (userMessage: string, history: {role: 'user' | 'model', text: string}[]): Promise<string> => {
  const ai = getClient();
  if (!ai) return "I'm having trouble connecting to the intelligence network. Please check your API key.";

  try {
    const model = ai.models.getGenerativeModel({
      model: "gemini-2.5-flash",
      systemInstruction: "You are a helpful support assistant for Salad.com, a distributed cloud computing platform. You help users understand how to earn rewards by sharing their compute power. You are friendly, technical but accessible, and often refer to users as 'Chefs'. Keep responses concise and helpful."
    });

    // Convert internal history format to Gemini SDK format
    const chatHistory = history.map(h => ({
      role: h.role,
      parts: [{ text: h.text }]
    }));

    const chat = model.startChat({
      history: chatHistory
    });

    const result = await chat.sendMessage(userMessage);
    const response = result.response;
    return response.text();
  } catch (error) {
    console.error("Chat error:", error);
    return "I'm having trouble thinking right now. Try again later.";
  }
};

