import { SaladOrg, SaladBalance, SaladMachine } from '../types';

// Using the common Salad Cloud API gateway
// Note: Requests to this URL from a browser will likely be blocked by CORS 
// unless the user has a CORS unblocker extension installed.
const BASE_URL = 'https://api.salad.com/core/master';

export class SaladApi {
  private token: string;
  private orgId: string | null = null;

  constructor(token: string) {
    this.token = token;
  }

  private async request(endpoint: string, options: RequestInit = {}) {
    const headers = {
      'Authorization': `Bearer ${this.token}`,
      'Content-Type': 'application/json',
      ...options.headers,
    };

    try {
      const response = await fetch(`${BASE_URL}${endpoint}`, {
        ...options,
        headers,
      });

      if (!response.ok) {
        if (response.status === 401) throw new Error('Unauthorized: Invalid Token');
        if (response.status === 403) throw new Error('Forbidden: Access Denied');
        throw new Error(`API Error: ${response.statusText}`);
      }

      return await response.json();
    } catch (error: any) {
      if (error.name === 'TypeError' && error.message === 'Failed to fetch') {
        throw new Error('CORS Error: Browser blocked the request to Salad.com. Please enable a CORS Unblocker extension.');
      }
      throw error;
    }
  }

  // Get User's Organizations
  async getOrgs(): Promise<SaladOrg[]> {
    return this.request('/orgs');
  }

  // Get Balance (requires Org ID)
  async getBalance(orgId: string): Promise<SaladBalance> {
    // This is a hypothetical endpoint structure as Salad's public docs are for Container Engine
    // We try the standard pattern
    return this.request(`/orgs/${orgId}/balance`);
  }

  // Get Machines
  async getMachines(orgId: string): Promise<SaladMachine[]> {
    return this.request(`/orgs/${orgId}/machines`);
  }

  // Start a Machine
  async startMachine(orgId: string, machineId: string): Promise<void> {
    return this.request(`/orgs/${orgId}/machines/${machineId}/start`, {
      method: 'POST'
    });
  }

  // Stop a Machine
  async stopMachine(orgId: string, machineId: string): Promise<void> {
    return this.request(`/orgs/${orgId}/machines/${machineId}/stop`, {
      method: 'POST'
    });
  }
}

import { GoogleGenAI } from "@google/genai";
import { SaladBalance, SaladMachine } from '../types';

const getClient = () => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) {
    console.warn("API Key not found in environment");
    return null;
  }
  return new GoogleGenAI({ apiKey });
};

/**
 * Chat with the "Salad Chef" assistant using Gemini.
 * Now aware of real account context.
 */
export const chatWithChef = async (
  userMessage: string, 
  history: {role: 'user' | 'model', text: string}[],
  context: { balance?: SaladBalance | null, machines?: SaladMachine[] | null, error?: string | null }
): Promise<string> => {
  const ai = getClient();
  if (!ai) return "I'm having trouble connecting to the intelligence network. Please check your API key.";

  try {
    let contextPrompt = "";
    if (context.error) {
      contextPrompt = `Note: The user's connection to Salad API failed: ${context.error}. Guide them on how to fix CORS or get a valid token.`;
    } else if (context.balance) {
      contextPrompt = `Current Account Data: Balance: $${context.balance.currentBalance}, Lifetime: $${context.balance.lifetimeBalance}. Active Machines: ${context.machines?.length || 0}.`;
    } else {
      contextPrompt = "User is not connected to a Salad account yet.";
    }

    const model = ai.models.getGenerativeModel({
      model: "gemini-2.5-flash",
      systemInstruction: `You are the Salad Chef Assistant. You have access to the user's real Salad.com account data.

      ${contextPrompt}

      If the user is experiencing CORS errors, explain that browsers block requests to 'api.salad.com' from external sites for security, and they might need a browser extension to allow it for this specific tool.

      Be helpful, concise, and professional.`
    });

    const chatHistory = history.map(h => ({
      role: h.role,
      parts: [{ text: h.text }]
    }));

    const chat = model.startChat({
      history: chatHistory
    });

    const result = await chat.sendMessage(userMessage);
    const response = result.response;
    return response.text();
  } catch (error) {
    console.error("Chat error:", error);
    return "I'm having trouble processing that request right now.";
  }
};

