}

import { SaladOrg, SaladBalance, SaladMachine, SaladContainer, SaladCloudResponse } from '../types';

// Official Salad Cloud Public API
const BASE_URL = 'https://api.salad.com/api/public';

export class SaladApi {
  private apiKey: string;
  private isDemo: boolean;

  constructor(apiKey: string, isDemo: boolean = false) {
    this.apiKey = apiKey;
    this.isDemo = isDemo;
  }

  private async request(endpoint: string, options: RequestInit = {}) {
    if (this.isDemo) {
      await new Promise(resolve => setTimeout(resolve, 800));
      return null;
    }

    const headers = {
      'Salad-Api-Key': this.apiKey, // Authenticate using the official API Key header
      'Content-Type': 'application/json',
      'Accept': 'application/json',
      ...options.headers,
    };

    try {
      const response = await fetch(`${BASE_URL}${endpoint}`, {
        ...options,
        headers,
      });

      if (!response.ok) {
        if (response.status === 401) throw new Error('Unauthorized: Invalid API Key');
        if (response.status === 403) throw new Error('Forbidden: Check API Access');
        throw new Error(`API Error ${response.status}: ${response.statusText}`);
      }

      return await response.json();
    } catch (error: any) {
      if (error.name === 'TypeError' && error.message === 'Failed to fetch') {
        throw new Error('CORS Error: Browser blocked the request. Please use a CORS Unblocker extension.');
      }
      throw error;
    }
  }

  // Get Organizations
  async getOrgs(): Promise<SaladOrg[]> {
    if (this.isDemo) {
      return [{
        id: 'demo-org-123',
        name: 'chef-demo-org',
        display_name: 'Chef Demo Kitchen'
      }];
    }
    const data = await this.request('/organizations');
    return data.items || [];
  }

  // Get Context/Balance
  // Note: The Public API splits billing and organization details. 
  // We will fetch the Org details to get the context.
  async getBalance(orgName: string): Promise<SaladBalance> {
    if (this.isDemo) {
      return {
        currentBalance: 14.52,
        lifetimeBalance: 142.80
      };
    }

    // There isn't a direct "Wallet Balance" endpoint publicly documented for the Cloud API 
    // in the same way as the Chef app, but we can verify the connection by getting the specific Org.
    // For this clone, we will simulate the balance from the Org response if available, or placeholder.
    // In a real scenario, you might query specific billing endpoints if authorized.

    try {
        // Just verifying we can fetch specific org details
        await this.request(`/organizations/${orgName}`);

        // Return a placeholder or mapped value since API doesn't expose raw wallet balance easily
        return {
            currentBalance: 0.00, // Real balance hidden in public API
            lifetimeBalance: 0.00
        };
    } catch (e) {
        console.error("Failed to fetch org details", e);
        throw e;
    }
  }

  // Get Workloads (Mapped to Machines)
  // In Salad Cloud, "Machines" are Container Groups/Instances
  async getMachines(orgName: string): Promise<SaladMachine[]> {
    if (this.isDemo) {
      return [
        {
          id: 'mach-1',
          name: 'Gaming PC - RTX 4090',
          status: 'running',
          miningState: 'mining'
        },
        {
          id: 'mach-2',
          name: 'Laptop - i7',
          status: 'stopped',
          miningState: 'stopped'
        }
      ];
    }

    // Fetch Container Groups as a proxy for "Active Machines/Workloads"
    const data = await this.request(`/organizations/${orgName}/containers`);
    const containers: SaladContainer[] = data.items || [];

    // Map Cloud Containers to UI "Machines"
    return containers.map(c => ({
      id: c.id,
      name: c.name,
      status: c.status === 'running' ? 'running' : 'stopped',
      miningState: c.status
    }));
  }
}

