               Section not implemented in clone.
            </div>
          )}
        </main>
      </div>

      {/* Auth Modal */}
      {showAuthModal && (
        <div className="fixed inset-0 bg-black/80 backdrop-blur-sm z-50 flex items-center justify-center p-4">
          <div className="bg-salad-card border border-slate-700 rounded-2xl p-8 max-w-md w-full shadow-2xl">
            <h2 className="text-2xl font-bold text-white mb-4">Login to Salad Cloud</h2>
            <div className="space-y-6">
               <div className="text-sm text-slate-400">
                  <p className="mb-2">Connect to your Organization using your API Key.</p>
                  <div className="bg-slate-800 p-3 rounded border border-slate-600">
                    <strong className="text-slate-200 block mb-1 text-xs uppercase">How to find it:</strong>
                    <ol className="list-decimal pl-5 space-y-1 text-slate-400 text-xs">
                       <li>Log into <a href="https://portal.salad.com" target="_blank" className="text-salad-accent hover:underline">portal.salad.com</a>.</li>
                       <li>Click your Profile Icon {'>'} <strong>API Keys</strong>.</li>
                       <li>Copy your personal API Key.</li>
                    </ol>
                  </div>
               </div>

               <div>
                 <label className="block text-xs font-bold text-slate-500 mb-1 uppercase">API Key</label>
                 <textarea 
                    value={apiKey}
                    onChange={(e) => setApiKey(e.target.value)}
