);

// -- Main App --

export default function App() {
  // App State
  const [activeTab, setActiveTab] = useState('Dashboard');
  const [credential, setCredential] = useState<string>('');
  // New distinct state for explicit fields if needed, but we sync to credential
  const [tempToken, setTempToken] = useState(''); 

  const [authMode, setAuthMode] = useState<AuthMode>('CHEF');
  const [showAuthModal, setShowAuthModal] = useState(false);
  const [authStep, setAuthStep] = useState<'SELECT' | 'OAUTH_WAITING'>('SELECT');
  const [authMethod, setAuthMethod] = useState<'google' | 'passkey' | 'backup' | null>(null);
  const [isDemo, setIsDemo] = useState(false);
  const [showManualHelp, setShowManualHelp] = useState(false);

  // Real Data State
  const [api, setApi] = useState<SaladApi | null>(null);
  const [org, setOrg] = useState<SaladOrg | null>(null);
  const [balance, setBalance] = useState<SaladBalance | null>(null);
  const [machines, setMachines] = useState<SaladMachine[]>([]);
  const [apiError, setApiError] = useState<string | null>(null);
  const [isLoadingData, setIsLoadingData] = useState(false);

  // Chat State
  const [showChat, setShowChat] = useState(false);
  const [chatInput, setChatInput] = useState('');
  const [messages, setMessages] = useState<ChatMessage[]>([
    { role: 'model', text: 'Hello! I am your Salad Assistant. I can help analyze your earning or spending performance.' }
  ]);
  const [isChatLoading, setIsChatLoading] = useState(false);
  const chatEndRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    // Check local storage
    const storedCred = localStorage.getItem('salad_credential');
    const storedMode = localStorage.getItem('salad_auth_mode') as AuthMode;

    if (storedCred) {
      setCredential(storedCred);
      setTempToken(storedCred);
      const mode = storedMode || 'CHEF'; // Default to Chef if unknown
      setAuthMode(mode);
      initializeApi(storedCred, mode, false);
    } else {
      setShowAuthModal(true);
    }
  }, []);

  useEffect(() => {
    if (chatEndRef.current) {
      chatEndRef.current.scrollIntoView({ behavior: 'smooth' });
    }
  }, [messages]);

  // Auto-detect clipboard token when returning from popup
  useEffect(() => {
    const handleFocus = async () => {
      if (authStep === 'OAUTH_WAITING' && !credential) {
        try {
          // Attempt to read clipboard
          const text = await navigator.clipboard.readText();
          // Basic validation for JWT-like string
          if (text && text.trim().startsWith('ey') && text.length > 20) {
             setCredential(text.trim());
             setTempToken(text.trim());
          }
        } catch (e) {
          // Clipboard read might fail if permission denied, ignore silently
          console.debug("Clipboard auto-read blocked or failed");
        }
      }
    };

    window.addEventListener('focus', handleFocus);
    return () => window.removeEventListener('focus', handleFocus);
  }, [authStep, credential]);

  const initializeApi = async (cred: string, mode: AuthMode, demoMode: boolean) => {
    setApiError(null);
    setIsLoadingData(true);
    setIsDemo(demoMode);

    try {
      const saladApi = new SaladApi(cred, mode, demoMode);
      setApi(saladApi);

      // Fetch Org first
      const orgs = await saladApi.getOrgs();
      if (orgs && orgs.length > 0) {
        const primaryOrg = orgs[0];
        setOrg(primaryOrg);

        // Mode Specific Identifiers
        // Chef API uses ID for everything. Cloud API uses Name (slug) for context.
        const orgIdentifier = mode === 'CHEF' ? primaryOrg.id : (primaryOrg.name || primaryOrg.id);

        try {
          const [bal, machs] = await Promise.all([
            saladApi.getBalance(orgIdentifier),
            saladApi.getMachines(orgIdentifier)
          ]);
          setBalance(bal);
          setMachines(machs || []);

          if (demoMode) {
             setMessages(prev => [...prev, { role: 'model', text: 'Demo Mode Active. Simulating environment...' }]);
          }
        } catch (innerErr: any) {
           console.error("Failed to fetch detailed stats", innerErr);
           setApiError(innerErr.message || "Connected, but failed to load details. Check CORS.");
        }
      } else {
        setApiError("No Organizations found.");
      }
    } catch (err: any) {
      console.error(err);
      setApiError(err.message || "Failed to connect to Salad API");
      setApi(null); 
    } finally {
      setIsLoadingData(false);
    }
  };

  const detectAndLogin = (credOverride?: string) => {
    const credToUse = credOverride || tempToken || credential;
    if (!credToUse.trim()) return;

    // Auto-detect mode
    const isJwt = credToUse.trim().startsWith('ey');
    const detectedMode: AuthMode = isJwt ? 'CHEF' : 'CLOUD';

    setAuthMode(detectedMode);
    setCredential(credToUse);
    setTempToken(credToUse);

    localStorage.setItem('salad_credential', credToUse);
    localStorage.setItem('salad_auth_mode', detectedMode);

    setShowAuthModal(false);
    initializeApi(credToUse, detectedMode, false);
  };

  const handleLoginPopup = (method: 'google' | 'passkey' | 'backup') => {
    setAuthStep('OAUTH_WAITING');
    setAuthMethod(method);

    // Open Salad Login in a centered popup window
    const width = 500;
    const height = 600;
    const left = window.screen.width / 2 - width / 2;
    const top = window.screen.height / 2 - height / 2;

    window.open(
      'https://salad.com/login', 
      'SaladLogin', 
      `width=${width},height=${height},top=${top},left=${left},resizable=yes,scrollbars=yes`
    );
  };

  const handlePasteFromClipboard = async () => {
    try {
      const text = await navigator.clipboard.readText();
      if (text) {
        setTempToken(text);
        detectAndLogin(text);
      }
    } catch (err) {
      console.error('Failed to read clipboard', err);
    }
  };

  const handleDemoLogin = () => {
    setShowAuthModal(false);
    setAuthMode('CHEF');
    initializeApi('demo-token', 'CHEF', true);
  };

  const handleLogout = () => {
    localStorage.removeItem('salad_credential');
    localStorage.removeItem('salad_auth_mode');
    setCredential('');
    setTempToken('');
    setApi(null);
    setBalance(null);
    setMachines([]);
    setOrg(null);
    setApiError(null);
    setIsDemo(false);
    setShowAuthModal(true);
    setAuthStep('SELECT');
    setAuthMethod(null);
  };

  const handleRefresh = () => {
    if (credential || isDemo) initializeApi(credential || 'demo-token', authMode, isDemo);
  };

  const handleSendMessage = async () => {
    if (!chatInput.trim()) return;

    const userMsg = chatInput;
    setMessages(prev => [...prev, { role: 'user', text: userMsg }]);
    setChatInput('');
    setIsChatLoading(true);

    try {
      const responseText = await chatWithChef(
        userMsg, 
        messages, 
        {
          balance: balance,
          machines: machines,
          error: apiError
        },
        {
          onLogin: (token) => {
            console.log("AI Agent triggered login with token");
            setTempToken(token);
            detectAndLogin(token);
          }
        }
      );
      setMessages(prev => [...prev, { role: 'model', text: responseText }]);
    } catch (e) {
      setMessages(prev => [...prev, { role: 'model', text: "Connection error." }]);
    } finally {
      setIsChatLoading(false);
    }
  };

  // Determine App State based on Real Data
  const activeMachine = machines.find(m => m.status === 'running' || m.miningState === 'mining');
  const isRunning = !!activeMachine;

  const getMethodName = () => {
    if (authMethod === 'passkey') return 'Passkey';
    if (authMethod === 'backup') return 'Backup Code';
    return 'Google';
  }

  return (
    <div className="flex h-screen bg-salad-bg text-salad-text overflow-hidden font-sans">

      {/* Sidebar */}
      <div className="w-64 bg-salad-bg border-r border-slate-800 flex flex-col shrink-0">
        <div className="p-6 flex items-center gap-2">
          <div className="w-8 h-8 bg-salad-accent rounded-full flex items-center justify-center">
            <span className="text-black font-bold text-xl">S</span>
          </div>
          <div className="flex flex-col">
            <span className="text-xl font-bold tracking-tight leading-none">Salad</span>
            <span className="text-[10px] text-slate-500 uppercase tracking-wider">
              {api ? (authMode === 'CHEF' ? 'Chef Mode' : 'Cloud Mode') : 'Clone'}
            </span>
          </div>
        </div>

        <div className="flex-1 py-4">
          <SidebarItem icon={Zap} label="Dashboard" onClick={() => setActiveTab('Dashboard')} active={activeTab === 'Dashboard'} />
          <SidebarItem icon={ShoppingBag} label="Store" onClick={() => setActiveTab('Store')} active={activeTab === 'Store'} />
          <SidebarItem icon={Users} label="Community" onClick={() => setActiveTab('Community')} active={activeTab === 'Community'} />
        </div>

        <div className="p-4 border-t border-slate-800">
          <SidebarItem icon={Settings} label="Settings" />
          {api ? (
             <div className="mt-2 flex items-center gap-3 px-4 py-2 text-red-400 hover:text-red-300 cursor-pointer" onClick={handleLogout}>
                <LogOut size={20} />
                <span className="font-medium">Logout</span>
             </div>
          ) : (
            <button 
              onClick={() => setShowAuthModal(true)}
              className="mt-4 w-full py-2 bg-slate-700 hover:bg-slate-600 rounded text-sm font-semibold transition-colors"
            >
              Login
            </button>
          )}
        </div>
      </div>

      {/* Main Content */}
      <div className="flex-1 flex flex-col min-w-0">
        {/* Header */}
        <header className="h-16 border-b border-slate-800 flex items-center justify-between px-8 bg-salad-bg/50 backdrop-blur z-10">
          <div className="flex items-center gap-4">
            <h1 className="text-xl font-semibold text-white">{activeTab}</h1>
            {isDemo && (
              <span className="px-2 py-0.5 bg-blue-500/20 text-blue-400 text-xs rounded-full border border-blue-500/50 font-bold">
                DEMO MODE
              </span>
            )}
            {isRunning && (
              <span className="px-2 py-0.5 bg-salad-accent/20 text-salad-accent text-xs rounded-full border border-salad-accent/50 animate-pulse">
                {authMode === 'CHEF' ? 'CHOPPING' : 'RUNNING'}
              </span>
            )}
            {apiError && (
              <span className="flex items-center gap-1 text-red-400 text-xs px-2 py-1 bg-red-900/20 rounded border border-red-900">
                <AlertTriangle size={12} /> Connection Error
              </span>
            )}
          </div>

          <div className="flex items-center gap-6">
            <div className="flex flex-col items-end">
              <span className="text-xs text-slate-400">
                {authMode === 'CHEF' ? 'Current Balance' : 'Account Status'}
              </span>
              <span className="text-salad-accent font-mono font-bold text-lg">
                {balance ? (authMode === 'CHEF' ? `$${balance.currentBalance.toFixed(2)}` : 'Active') : '---'}
              </span>
            </div>
            <button onClick={handleRefresh} className="text-slate-500 hover:text-white" title="Refresh Data">
              <RefreshCw size={18} className={isLoadingData ? "animate-spin" : ""} />
            </button>
          </div>
        </header>

        {/* Dashboard Content */}
        <main className="flex-1 overflow-y-auto p-8 relative">

          {/* Auth Modal / Connect Prompt */}
          {!api && !isLoadingData ? (
             <div className="h-full flex flex-col items-center justify-center text-center">
               <div className="w-16 h-16 bg-salad-accent/10 rounded-full flex items-center justify-center mb-4">
                  <Key className="text-salad-accent" size={32} />
               </div>
               <h2 className="text-2xl font-bold text-white mb-2">Connect to Salad</h2>
               <p className="text-slate-400 max-w-md mb-6">
                 Connect as a <strong>Chef</strong> (Earner) or <strong>Developer</strong> (Cloud User).
               </p>
               <button 
                onClick={() => setShowAuthModal(true)}
                className="px-8 py-3 bg-salad-accent hover:bg-salad-hover text-black font-bold rounded-full transition-all shadow-[0_0_20px_rgba(163,230,53,0.3)] hover:shadow-[0_0_30px_rgba(163,230,53,0.5)]"
               >
                 Login / Enter Key
               </button>
             </div>
          ) : activeTab === 'Dashboard' ? (
            <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 max-w-6xl mx-auto">

              {/* API Error Banner */}
              {apiError && (
                <div className="lg:col-span-3 bg-red-900/20 border border-red-500/50 p-4 rounded-lg flex items-start gap-3">
                  <AlertTriangle className="text-red-500 shrink-0 mt-0.5" />
                  <div>
                    <h3 className="text-red-400 font-bold text-sm">Connection Failed</h3>
                    <p className="text-red-300 text-sm mt-1">{apiError}</p>
                    {apiError.includes("CORS") && (
                      <p className="text-slate-400 text-xs mt-2">
                        <strong>Important:</strong> Browser security (CORS) blocks direct requests to Salad's API from this clone. 
                        You must use a CORS extension or run this in a non-browser environment.
                      </p>
                    )}
                  </div>
                </div>
              )}

              {/* Main Status */}
              <div className="lg:col-span-2 space-y-6">
                <div className="bg-salad-card rounded-2xl p-8 border border-slate-700 relative overflow-hidden min-h-[300px] flex flex-col items-center justify-center">

                   {isLoadingData ? (
                      <div className="flex flex-col items-center">
                        <Loader2 className="animate-spin text-salad-accent mb-4" size={48} />
                        <p className="text-slate-400">Syncing with Salad...</p>
                      </div>
                   ) : (
                     <>
                        <div className={`absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-64 h-64 bg-salad-accent/5 rounded-full blur-3xl transition-opacity duration-1000 ${isRunning ? 'opacity-100' : 'opacity-0'}`}></div>
                        <div className="relative z-10 flex flex-col items-center justify-center text-center">
                            <div className="mb-6">
                              <h2 className="text-3xl font-bold text-white mb-2">{isRunning ? 'ACTIVE' : 'IDLE'}</h2>
                              <p className="text-slate-400">
                                {isRunning 
                                  ? `${authMode === 'CHEF' ? 'Machine' : 'Container'}: ${activeMachine?.name || 'Unknown'}`
                                  : (authMode === 'CHEF' ? 'No active miners found.' : 'No active container groups.')}
                              </p>
                            </div>

                            <div className={`
                                w-32 h-32 rounded-full flex items-center justify-center border-4 
                                ${isRunning 
                                  ? 'bg-salad-bg border-salad-accent text-salad-accent shadow-[0_0_30px_rgba(163,230,53,0.4)]' 
                                  : 'bg-salad-bg border-slate-600 text-slate-600'
                                }
                              `}>
                              {isRunning ? <Square size={32} fill="currentColor" /> : <Play size={32} fill="currentColor" className="ml-1" />}
                            </div>
                        </div>
                     </>
                   )}
                </div>

                {/* Info Area */}
                <div className="bg-salad-card rounded-xl p-6 border border-slate-700 h-80 flex flex-col">
                  <h3 className="text-lg font-semibold mb-4 text-slate-200">
                    {authMode === 'CHEF' ? 'Earning History' : 'Usage History'}
                  </h3>
                  <div className="flex-1 flex items-center justify-center text-slate-500 bg-slate-800/50 rounded border border-dashed border-slate-700">
                     {apiError ? 'Connection Error' : isDemo ? 'Graph unavailable in demo' : 'Historical data unavailable in this view'}
                  </div>
                </div>
              </div>

              {/* Right Column Stats */}
              <div className="space-y-6">
                 <div className="bg-salad-card rounded-xl p-6 border border-slate-700">
                    <h3 className="text-lg font-semibold mb-4 text-slate-200 flex items-center gap-2">
                       <Cpu size={18} /> Organization
                    </h3>
                    <div className="space-y-4">
                       <div>
                          <div className="text-xs text-slate-500 uppercase font-bold mb-1">Name</div>
                          <div className="text-white font-mono">{org?.display_name || org?.name || 'Loading...'}</div>
                       </div>
                       <div>
                          <div className="text-xs text-slate-500 uppercase font-bold mb-1">ID</div>
                          <div className="text-slate-400 font-mono text-xs break-all">
                            {org?.id || '---'}
                          </div>
                       </div>
                       <div>
                          <div className="text-xs text-slate-500 uppercase font-bold mb-1">Mode</div>
                          <span className="inline-block px-2 py-1 rounded bg-slate-800 text-slate-300 text-xs font-bold border border-slate-600">
                            {authMode}
                          </span>
                       </div>
                    </div>
                 </div>

                 <div className="bg-salad-card rounded-xl p-6 border border-slate-700">
                    <h3 className="text-lg font-semibold mb-4 text-slate-200">
                      {authMode === 'CHEF' ? 'My Machines' : 'Container Groups'}
                    </h3>
                    {machines.length > 0 ? (
                      <ul className="space-y-3">
                        {machines.map(m => (
                          <li key={m.id} className="flex items-center justify-between text-sm">
                             <span className="text-slate-300 truncate max-w-[120px]" title={m.name}>{m.name}</span>
                             <span className={`px-2 py-0.5 rounded text-xs ${m.status === 'running' ? 'bg-green-900 text-green-400' : 'bg-slate-700 text-slate-400'}`}>
                                {m.status.toUpperCase()}
                             </span>
                          </li>
                        ))}
                      </ul>
                    ) : (
                      <div className="text-slate-500 text-sm italic">
                         {authMode === 'CHEF' ? 'No machines found' : 'No workloads found'}
                      </div>
                    )}
                 </div>
              </div>

            </div>
          ) : (
             <div className="flex items-center justify-center h-full text-slate-500">
               Section not implemented in clone.
            </div>
          )}
        </main>
      </div>

      {/* Auth Modal */}
      {showAuthModal && (
        <div className="fixed inset-0 bg-black/80 backdrop-blur-sm z-50 flex items-center justify-center p-4">
          <div className="bg-salad-card border border-slate-700 rounded-2xl p-8 max-w-md w-full shadow-2xl relative overflow-hidden">
            <h2 className="text-2xl font-bold text-white mb-2">Connect to Salad</h2>

            {/* Step 1: Selection */}
            {authStep === 'SELECT' && (
              <div className="space-y-6 animate-in fade-in slide-in-from-right-4 duration-300">
                <p className="text-sm text-slate-400">
                  Select your login method to connect.
                </p>

                <div className="space-y-2">
                  {/* Google Login Button */}
                  <button 
                    onClick={() => handleLoginPopup('google')}
                    className="w-full py-3 bg-white text-slate-900 font-bold rounded-lg hover:bg-slate-200 transition-colors flex items-center justify-center shadow-lg transform active:scale-95 duration-100 group gap-2"
                  >
                    <GoogleIcon /> 
                    <span className="group-hover:text-black">Login with Google</span>
                  </button>

                  <div className="grid grid-cols-2 gap-2">
                    {/* Passkey Login Button */}
                    <button 
                      onClick={() => handleLoginPopup('passkey')}
                      className="w-full py-3 bg-slate-800 text-white font-semibold rounded-lg hover:bg-slate-700 border border-slate-600 transition-colors flex items-center justify-center gap-2"
                    >
                      <Fingerprint size={18} />
                      <span>Passkey</span>
                    </button>

                    {/* Backup Code Login Button */}
                    <button 
                      onClick={() => handleLoginPopup('backup')}
                      className="w-full py-3 bg-slate-800 text-white font-semibold rounded-lg hover:bg-slate-700 border border-slate-600 transition-colors flex items-center justify-center gap-2"
                    >
                      <ShieldCheck size={18} />
                      <span>Backup Code</span>
                    </button>
                  </div>
                </div>

                <div className="relative flex py-1 items-center">
                    <div className="flex-grow border-t border-slate-700"></div>
                    <span className="flex-shrink mx-4 text-slate-500 text-xs uppercase font-bold">Or enter key manually</span>
                    <div className="flex-grow border-t border-slate-700"></div>
                </div>

                {/* Manual Input Section */}
                <div className="space-y-4">
                  <div>
                    <label className="block text-xs font-bold text-slate-400 mb-1 flex items-center gap-2">
                       <Terminal size={12} /> Auth Token / Backup Code (Chef)
                    </label>
                    <input 
                       type="password"
                       value={tempToken.startsWith('ey') ? tempToken : ''}
                       onChange={(e) => setTempToken(e.target.value)}
                       placeholder="Paste JWT (ey...) or Backup Code"
                       className="w-full bg-slate-900 border border-slate-700 rounded px-3 py-2 text-white text-xs font-mono focus:outline-none focus:border-salad-accent"
                    />
                  </div>

                  <div className="text-center text-[10px] text-slate-600 font-bold">- OR -</div>

                  <div>
                    <label className="block text-xs font-bold text-slate-400 mb-1 flex items-center gap-2">
                       <Key size={12} /> API Key (Cloud)
                    </label>
                    <input 
                       type="password"
                       value={!tempToken.startsWith('ey') ? tempToken : ''}
                       onChange={(e) => setTempToken(e.target.value)}
                       placeholder="Paste API Key..."
                       className="w-full bg-slate-900 border border-slate-700 rounded px-3 py-2 text-white text-xs font-mono focus:outline-none focus:border-salad-accent"
                    />
                  </div>
                </div>

                <div className="space-y-3 pt-2">
                  <button 
                    onClick={() => detectAndLogin(tempToken)}
                    disabled={!tempToken}
                    className="w-full py-3 bg-salad-accent hover:bg-salad-hover text-black font-bold rounded-lg transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
                  >
                    Connect
                  </button>

                  <button 
                    onClick={handleDemoLogin}
                    className="w-full py-2 bg-slate-800 hover:bg-slate-700 text-slate-300 font-medium rounded-lg transition-colors flex items-center justify-center gap-2"
                  >
                    <Eye size={16} />
                    View Demo Mode
                  </button>
                </div>
              </div>
            )}

            {/* Step 2: Google OAuth Simulation (Token Extraction) */}
            {authStep === 'OAUTH_WAITING' && (
              <div className="space-y-6 animate-in fade-in slide-in-from-right-4 duration-300">
                <div className="flex items-start gap-4 bg-blue-900/20 border border-blue-500/30 p-4 rounded-lg">
                   <div className="mt-1">
                     <Loader2 className="animate-spin text-blue-400" size={20} />
                   </div>
                   <div>
                      <h3 className="text-white font-semibold text-sm">Authentication in progress...</h3>
                      <p className="text-xs text-slate-400 mt-1">
                        Please complete the <strong>{getMethodName()}</strong> Login in the popup window.
                        <br/>
                        When finished, copy your token or <strong>return to this tab</strong> to auto-detect it.
                      </p>
                   </div>
                </div>

                <div className="bg-slate-800/50 p-4 rounded-lg border border-slate-700">
                    <h4 className="text-xs font-bold text-slate-300 uppercase mb-3 flex items-center gap-2">
                      <Lock size={14} className="text-salad-accent" />
                      Security Check
                    </h4>

                    <button 
                      onClick={() => setShowManualHelp(!showManualHelp)}
                      className="text-xs text-blue-400 hover:text-blue-300 mb-2 flex items-center gap-1"
                    >
                       <HelpCircle size={12} /> How to get my token securely?
                    </button>

                    {showManualHelp && (
                       <div className="bg-slate-900 p-3 rounded mb-4 border border-slate-700">
                         <ol className="list-decimal pl-5 space-y-2 text-xs text-slate-400">
                           <li>In the popup window, login with Google.</li>
                           <li>Right-click anywhere &gt; <strong>Inspect</strong>.</li>
                           <li>Go to <strong>Application</strong> tab &gt; <strong>Local Storage</strong>.</li>
                           <li>Copy the value of <code>salad_auth_token</code> (starts with ey...).</li>
                         </ol>
                       </div>
                    )}

                    <div className="space-y-2">
                       <label className="text-xs text-slate-400 font-bold">Detected Token</label>
                       <div className="flex gap-2">
                         <input 
                            type="text" 
                            placeholder="Paste token starting with ey..." 
                            value={credential}
                            onChange={(e) => {
                              setCredential(e.target.value);
                              setTempToken(e.target.value);
                            }}
                            className="flex-1 bg-slate-900 border border-slate-600 rounded px-3 py-2 text-xs text-white focus:outline-none focus:border-salad-accent"
                         />
                         <button 
                            onClick={handlePasteFromClipboard}
                            className="bg-slate-700 hover:bg-slate-600 text-white px-3 py-2 rounded flex items-center gap-2 text-xs font-medium transition-colors"
                         >
                            <Clipboard size={14} /> Paste
                         </button>
                       </div>
                    </div>
                </div>

                <div className="space-y-3">
                   <button 
                      onClick={() => detectAndLogin()}
                      disabled={!credential}
                      className="w-full py-3 bg-salad-accent hover:bg-salad-hover text-black font-bold rounded-lg transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
                   >
                      Verify & Connect
                   </button>
                   <button 
                      onClick={() => setAuthStep('SELECT')}
                      className="w-full py-2 text-slate-500 hover:text-slate-300 text-xs"
                   >
                      Cancel
                   </button>
                </div>
              </div>
            )}
          </div>
        </div>
      )}

      {/* Chat Button */}
      <div className="fixed bottom-6 right-6">
        <button 
          onClick={() => setShowChat(!showChat)}
          className="w-14 h-14 bg-salad-accent hover:bg-salad-hover rounded-full flex items-center justify-center shadow-lg text-black transition-transform hover:scale-105"
        >
          <MessageSquare size={24} fill="currentColor" />
        </button>
      </div>

      {/* Chat Interface */}
      {showChat && (
        <div className="fixed bottom-24 right-6 w-96 h-[500px] bg-salad-card border border-slate-700 rounded-2xl shadow-2xl flex flex-col overflow-hidden z-50">
           <div className="p-4 bg-slate-800 border-b border-slate-700 flex justify-between items-center">
              <div className="flex items-center gap-2">
                 <div className={`w-2 h-2 rounded-full ${apiError ? 'bg-red-500' : api ? 'bg-green-500' : 'bg-gray-500'}`}></div>
                 <span className="font-semibold text-white">Salad Assistant</span>
              </div>
              <button onClick={() => setShowChat(false)} className="text-slate-400 hover:text-white">✕</button>
           </div>

           <div className="flex-1 overflow-y-auto p-4 space-y-4">
              {messages.map((msg, idx) => (
                <div key={idx} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                   <div className={`max-w-[80%] p-3 rounded-lg text-sm ${msg.role === 'user' ? 'bg-salad-accent text-black rounded-tr-none' : 'bg-slate-700 text-white rounded-tl-none'}`}>
                      {msg.text}
                   </div>
                </div>
              ))}
              {isChatLoading && (
                 <div className="flex justify-start">
                    <div className="bg-slate-700 p-3 rounded-lg rounded-tl-none flex gap-1">
                       <span className="w-2 h-2 bg-slate-400 rounded-full animate-bounce"></span>
                       <span className="w-2 h-2 bg-slate-400 rounded-full animate-bounce delay-75"></span>
                       <span className="w-2 h-2 bg-slate-400 rounded-full animate-bounce delay-150"></span>
                    </div>
                 </div>
              )}
              <div ref={chatEndRef}></div>
           </div>

           <div className="p-4 bg-slate-800 border-t border-slate-700">
              <div className="flex gap-2">
                 <input 
                   type="text" 
                   value={chatInput}
                   onChange={(e) => setChatInput(e.target.value)}
                   onKeyDown={(e) => e.key === 'Enter' && handleSendMessage()}
                   placeholder="Ask about status or paste token..." 
                   className="flex-1 bg-slate-900 border border-slate-700 rounded-lg px-3 py-2 text-sm text-white focus:outline-none focus:border-salad-accent"
                 />
                 <button 
                   onClick={handleSendMessage}
                   disabled={isChatLoading}
                   className="p-2 bg-salad-accent hover:bg-salad-hover rounded-lg text-black disabled:opacity-50"
                 >
                    <ChevronRight size={20} />
                 </button>
              </div>
           </div>
        </div>
      )}
    </div>
  );
}

import React, { useState, useEffect, useRef } from 'react';
import { 
  Play, 
  Square, 
  Cpu, 
  ShoppingBag, 
  Users, 
  Settings, 
  MessageSquare,
  Zap,
  ChevronRight,
  Monitor,
  LogOut,
  Key,
  AlertTriangle,
  RefreshCw,
  Loader2,
  Eye,
  Server,
  ArrowRight,
  Clipboard,
  CheckCircle2,
  HelpCircle,
  X,
  Lock,
  Terminal,
  Fingerprint,
  ShieldCheck
} from 'lucide-react';
import { LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';
import { chatWithChef } from './services/geminiService';
import { SaladApi, AuthMode } from './services/saladApi';
import { SaladBalance, SaladMachine, SaladOrg, ChatMessage, ChartDataPoint } from './types';

// -- Components --

const SidebarItem = ({ icon: Icon, label, active = false, onClick }: { icon: any, label: string, active?: boolean, onClick?: () => void }) => (
  <div 
    onClick={onClick}
    className={`flex items-center gap-3 px-4 py-3 cursor-pointer transition-colors ${active ? 'text-salad-accent border-r-2 border-salad-accent bg-salad-bg' : 'text-slate-400 hover:text-slate-200 hover:bg-slate-800'}`}
  >
    <Icon size={20} />
    <span className="font-medium">{label}</span>
  </div>
);

const GoogleIcon = () => (
  <svg className="w-5 h-5" viewBox="0 0 24 24">
    <path
      fill="currentColor"
      d="M22.56 12.25c0-.78-.07-1.53-.2-2.25H12v4.26h5.92c-.26 1.37-1.04 2.53-2.21 3.31v2.77h3.57c2.08-1.92 3.28-4.74 3.28-8.09z"
    />
    <path
      fill="currentColor"
      d="M12 23c2.97 0 5.46-.98 7.28-2.66l-3.57-2.77c-.98.66-2.23 1.06-3.71 1.06-2.86 0-5.29-1.93-6.16-4.53H2.18v2.84C3.99 20.53 7.7 23 12 23z"
    />
    <path
      fill="currentColor"
      d="M5.84 14.09c-.22-.66-.35-1.36-.35-2.09s.13-1.43.35-2.09V7.07H2.18C1.43 8.55 1 10.22 1 12s.43 3.45 1.18 4.93l2.85-2.22.81-.62z"
    />
    <path
      fill="currentColor"
      d="M12 5.38c1.62 0 3.06.56 4.21 1.64l3.15-3.15C17.45 2.09 14.97 1 12 1 7.7 1 3.99 3.47 2.18 7.07l3.66 2.84c.87-2.6 3.3-4.53 6.16-4.53z"
    />
  </svg>
);

// -- Main App --

export default function App() {
  // App State
  const [activeTab, setActiveTab] = useState('Dashboard');
  const [credential, setCredential] = useState<string>('');

  // Distinct state for explicit fields to avoid UI jumping
  const [chefInput, setChefInput] = useState('');
  const [cloudInput, setCloudInput] = useState('');

  const [authMode, setAuthMode] = useState<AuthMode>('CHEF');
  const [showAuthModal, setShowAuthModal] = useState(false);
  const [authStep, setAuthStep] = useState<'SELECT' | 'OAUTH_WAITING'>('SELECT');
  const [authMethod, setAuthMethod] = useState<'google' | 'passkey' | 'backup' | null>(null);
  const [isDemo, setIsDemo] = useState(false);
  const [showManualHelp, setShowManualHelp] = useState(false);

  // Real Data State
  const [api, setApi] = useState<SaladApi | null>(null);
  const [org, setOrg] = useState<SaladOrg | null>(null);
  const [balance, setBalance] = useState<SaladBalance | null>(null);
  const [machines, setMachines] = useState<SaladMachine[]>([]);
  const [apiError, setApiError] = useState<string | null>(null);
  const [isLoadingData, setIsLoadingData] = useState(false);

  // Chat State
  const [showChat, setShowChat] = useState(false);
  const [chatInput, setChatInput] = useState('');
  const [messages, setMessages] = useState<ChatMessage[]>([
    { role: 'model', text: 'Hello! I am your Salad Assistant. I can help analyze your earning or spending performance.' }
  ]);
  const [isChatLoading, setIsChatLoading] = useState(false);
  const chatEndRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    // Check local storage
    const storedCred = localStorage.getItem('salad_credential');
    const storedMode = localStorage.getItem('salad_auth_mode') as AuthMode;

    if (storedCred) {
      setCredential(storedCred);
      // Pre-fill the correct input bucket based on stored mode
      if (storedMode === 'CHEF') {
        setChefInput(storedCred);
      } else {
        setCloudInput(storedCred);
      }

      const mode = storedMode || 'CHEF'; // Default to Chef if unknown
      setAuthMode(mode);
      initializeApi(storedCred, mode, false);
    } else {
      setShowAuthModal(true);
    }
  }, []);

  useEffect(() => {
    if (chatEndRef.current) {
      chatEndRef.current.scrollIntoView({ behavior: 'smooth' });
    }
  }, [messages]);

  // Auto-detect clipboard token when returning from popup
  useEffect(() => {
    const handleFocus = async () => {
      if (authStep === 'OAUTH_WAITING' && !credential) {
        try {
          // Attempt to read clipboard
          const text = await navigator.clipboard.readText();
          // Basic validation for JWT-like string
          if (text && text.trim().startsWith('ey') && text.length > 20) {
             setCredential(text.trim());
          }
        } catch (e) {
          // Clipboard read might fail if permission denied, ignore silently
          console.debug("Clipboard auto-read blocked or failed");
        }
      }
    };

    window.addEventListener('focus', handleFocus);
    return () => window.removeEventListener('focus', handleFocus);
  }, [authStep, credential]);

  const initializeApi = async (cred: string, mode: AuthMode, demoMode: boolean) => {
    setApiError(null);
    setIsLoadingData(true);
    setIsDemo(demoMode);

    try {
      const saladApi = new SaladApi(cred, mode, demoMode);
      setApi(saladApi);

      // Fetch Org first
      const orgs = await saladApi.getOrgs();
      if (orgs && orgs.length > 0) {
        const primaryOrg = orgs[0];
        setOrg(primaryOrg);

        // Mode Specific Identifiers
        // Chef API uses ID for everything. Cloud API uses Name (slug) for context.
        const orgIdentifier = mode === 'CHEF' ? primaryOrg.id : (primaryOrg.name || primaryOrg.id);

        try {
          const [bal, machs] = await Promise.all([
            saladApi.getBalance(orgIdentifier),
            saladApi.getMachines(orgIdentifier)
          ]);
          setBalance(bal);
          setMachines(machs || []);

          if (demoMode) {
             setMessages(prev => [...prev, { role: 'model', text: 'Demo Mode Active. Simulating environment...' }]);
          }
        } catch (innerErr: any) {
           console.error("Failed to fetch detailed stats", innerErr);
           setApiError(innerErr.message || "Connected, but failed to load details. Check CORS.");
        }
      } else {
        setApiError("No Organizations found.");
      }
    } catch (err: any) {
      console.error(err);
      setApiError(err.message || "Failed to connect to Salad API");
      setApi(null); 
    } finally {
      setIsLoadingData(false);
    }
  };

  const detectAndLogin = (credOverride?: string, modeOverride?: AuthMode) => {
    // 1. Determine which credential to use
    let credToUse = credOverride;
    let modeToUse = modeOverride;

    // If no override, look at state
    if (!credToUse) {
        if (credential) {
            // Priority 1: Generic Credential (from paste/clipboard in waiting screen)
            credToUse = credential;
            // If mode not specified, try to auto-detect
            if (!modeToUse) {
                const isJwt = credential.trim().startsWith('ey');
                modeToUse = isJwt ? 'CHEF' : 'CLOUD';
            }
        } else if (chefInput) {
            // Priority 2: Chef Input Field
            credToUse = chefInput;
            modeToUse = 'CHEF';
        } else if (cloudInput) {
            // Priority 3: Cloud Input Field
            credToUse = cloudInput;
            modeToUse = 'CLOUD';
        }
    }

    if (!credToUse || !credToUse.trim()) return;

    // Final fallback for mode if still undefined
    if (!modeToUse) {
        const isJwt = credToUse.trim().startsWith('ey');
        modeToUse = isJwt ? 'CHEF' : 'CLOUD';
    }

    setAuthMode(modeToUse);
    setCredential(credToUse);

    // Sync inputs for consistency
    if (modeToUse === 'CHEF') {
        setChefInput(credToUse);
        setCloudInput('');
    } else {
        setCloudInput(credToUse);
        setChefInput('');
    }

    localStorage.setItem('salad_credential', credToUse);
    localStorage.setItem('salad_auth_mode', modeToUse);

    setShowAuthModal(false);
    initializeApi(credToUse, modeToUse, false);
  };

  const handleLoginPopup = (method: 'google' | 'passkey' | 'backup') => {
    setAuthStep('OAUTH_WAITING');
    setAuthMethod(method);

    // Open Salad Login in a centered popup window
    const width = 500;
    const height = 600;
    const left = window.screen.width / 2 - width / 2;
    const top = window.screen.height / 2 - height / 2;

    window.open(
      'https://salad.com/login', 
      'SaladLogin', 
      `width=${width},height=${height},top=${top},left=${left},resizable=yes,scrollbars=yes`
    );
  };

  const handlePasteFromClipboard = async () => {
    try {
      const text = await navigator.clipboard.readText();
      if (text) {
        setCredential(text);
        detectAndLogin(text);
      }
    } catch (err) {
      console.error('Failed to read clipboard', err);
    }
  };

  const handleDemoLogin = () => {
    setShowAuthModal(false);
    setAuthMode('CHEF');
    initializeApi('demo-token', 'CHEF', true);
  };

  const handleLogout = () => {
    localStorage.removeItem('salad_credential');
    localStorage.removeItem('salad_auth_mode');
    setCredential('');
    setChefInput('');
    setCloudInput('');
    setApi(null);
    setBalance(null);
    setMachines([]);
    setOrg(null);
    setApiError(null);
    setIsDemo(false);
    setShowAuthModal(true);
    setAuthStep('SELECT');
    setAuthMethod(null);
  };

  const handleRefresh = () => {
    if (credential || isDemo) initializeApi(credential || 'demo-token', authMode, isDemo);
  };

  const handleSendMessage = async () => {
    if (!chatInput.trim()) return;

    const userMsg = chatInput;
    setMessages(prev => [...prev, { role: 'user', text: userMsg }]);
    setChatInput('');
    setIsChatLoading(true);

    try {
      const responseText = await chatWithChef(
        userMsg, 
        messages, 
        {
          balance: balance,
          machines: machines,
          error: apiError
        },
        {
          onLogin: (token) => {
            console.log("AI Agent triggered login with token");
            // Assume AI detected a Chef token
            detectAndLogin(token, 'CHEF');
          }
        }
      );
      setMessages(prev => [...prev, { role: 'model', text: responseText }]);
    } catch (e) {
      setMessages(prev => [...prev, { role: 'model', text: "Connection error." }]);
    } finally {
      setIsChatLoading(false);
    }
  };

  // Determine App State based on Real Data
  const activeMachine = machines.find(m => m.status === 'running' || m.miningState === 'mining');
  const isRunning = !!activeMachine;

  const getMethodName = () => {
    if (authMethod === 'passkey') return 'Passkey';
    if (authMethod === 'backup') return 'Backup Code';
    return 'Google';
  }

  return (
    <div className="flex h-screen bg-salad-bg text-salad-text overflow-hidden font-sans">

      {/* Sidebar */}
      <div className="w-64 bg-salad-bg border-r border-slate-800 flex flex-col shrink-0">
        <div className="p-6 flex items-center gap-2">
          <div className="w-8 h-8 bg-salad-accent rounded-full flex items-center justify-center">
            <span className="text-black font-bold text-xl">S</span>
          </div>
          <div className="flex flex-col">
            <span className="text-xl font-bold tracking-tight leading-none">Salad</span>
            <span className="text-[10px] text-slate-500 uppercase tracking-wider">
              {api ? (authMode === 'CHEF' ? 'Chef Mode' : 'Cloud Mode') : 'Clone'}
            </span>
          </div>
        </div>

        <div className="flex-1 py-4">
          <SidebarItem icon={Zap} label="Dashboard" onClick={() => setActiveTab('Dashboard')} active={activeTab === 'Dashboard'} />
          <SidebarItem icon={ShoppingBag} label="Store" onClick={() => setActiveTab('Store')} active={activeTab === 'Store'} />
          <SidebarItem icon={Users} label="Community" onClick={() => setActiveTab('Community')} active={activeTab === 'Community'} />
        </div>

        <div className="p-4 border-t border-slate-800">
          <SidebarItem icon={Settings} label="Settings" />
          {api ? (
             <div className="mt-2 flex items-center gap-3 px-4 py-2 text-red-400 hover:text-red-300 cursor-pointer" onClick={handleLogout}>
                <LogOut size={20} />
                <span className="font-medium">Logout</span>
             </div>
          ) : (
            <button 
              onClick={() => setShowAuthModal(true)}
              className="mt-4 w-full py-2 bg-slate-700 hover:bg-slate-600 rounded text-sm font-semibold transition-colors"
            >
              Login
            </button>
          )}
        </div>
      </div>

      {/* Main Content */}
      <div className="flex-1 flex flex-col min-w-0">
        {/* Header */}
        <header className="h-16 border-b border-slate-800 flex items-center justify-between px-8 bg-salad-bg/50 backdrop-blur z-10">
          <div className="flex items-center gap-4">
            <h1 className="text-xl font-semibold text-white">{activeTab}</h1>
            {isDemo && (
              <span className="px-2 py-0.5 bg-blue-500/20 text-blue-400 text-xs rounded-full border border-blue-500/50 font-bold">
                DEMO MODE
              </span>
            )}
            {isRunning && (
              <span className="px-2 py-0.5 bg-salad-accent/20 text-salad-accent text-xs rounded-full border border-salad-accent/50 animate-pulse">
                {authMode === 'CHEF' ? 'CHOPPING' : 'RUNNING'}
              </span>
            )}
            {apiError && (
              <span className="flex items-center gap-1 text-red-400 text-xs px-2 py-1 bg-red-900/20 rounded border border-red-900">
                <AlertTriangle size={12} /> Connection Error
              </span>
            )}
          </div>

          <div className="flex items-center gap-6">
            <div className="flex flex-col items-end">
              <span className="text-xs text-slate-400">
                {authMode === 'CHEF' ? 'Current Balance' : 'Account Status'}
              </span>
              <span className="text-salad-accent font-mono font-bold text-lg">
                {balance ? (authMode === 'CHEF' ? `$${balance.currentBalance.toFixed(2)}` : 'Active') : '---'}
              </span>
            </div>
            <button onClick={handleRefresh} className="text-slate-500 hover:text-white" title="Refresh Data">
              <RefreshCw size={18} className={isLoadingData ? "animate-spin" : ""} />
            </button>
          </div>
        </header>

        {/* Dashboard Content */}
        <main className="flex-1 overflow-y-auto p-8 relative">

          {/* Auth Modal / Connect Prompt */}
          {!api && !isLoadingData ? (
             <div className="h-full flex flex-col items-center justify-center text-center">
               <div className="w-16 h-16 bg-salad-accent/10 rounded-full flex items-center justify-center mb-4">
                  <Key className="text-salad-accent" size={32} />
               </div>
               <h2 className="text-2xl font-bold text-white mb-2">Connect to Salad</h2>
               <p className="text-slate-400 max-w-md mb-6">
                 Connect as a <strong>Chef</strong> (Earner) or <strong>Developer</strong> (Cloud User).
               </p>
               <button 
                onClick={() => setShowAuthModal(true)}
                className="px-8 py-3 bg-salad-accent hover:bg-salad-hover text-black font-bold rounded-full transition-all shadow-[0_0_20px_rgba(163,230,53,0.3)] hover:shadow-[0_0_30px_rgba(163,230,53,0.5)]"
               >
                 Login / Enter Key
               </button>
             </div>
          ) : activeTab === 'Dashboard' ? (
            <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 max-w-6xl mx-auto">

              {/* API Error Banner */}
              {apiError && (
                <div className="lg:col-span-3 bg-red-900/20 border border-red-500/50 p-4 rounded-lg flex items-start gap-3">
                  <AlertTriangle className="text-red-500 shrink-0 mt-0.5" />
                  <div>
                    <h3 className="text-red-400 font-bold text-sm">Connection Failed</h3>
                    <p className="text-red-300 text-sm mt-1">{apiError}</p>
                    {apiError.includes("CORS") && (
                      <p className="text-slate-400 text-xs mt-2">
                        <strong>Important:</strong> Browser security (CORS) blocks direct requests to Salad's API from this clone. 
                        You must use a CORS extension or run this in a non-browser environment.
                      </p>
                    )}
                  </div>
                </div>
              )}

              {/* Main Status */}
              <div className="lg:col-span-2 space-y-6">
                <div className="bg-salad-card rounded-2xl p-8 border border-slate-700 relative overflow-hidden min-h-[300px] flex flex-col items-center justify-center">

                   {isLoadingData ? (
                      <div className="flex flex-col items-center">
                        <Loader2 className="animate-spin text-salad-accent mb-4" size={48} />
                        <p className="text-slate-400">Syncing with Salad...</p>
                      </div>
                   ) : (
                     <>
                        <div className={`absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-64 h-64 bg-salad-accent/5 rounded-full blur-3xl transition-opacity duration-1000 ${isRunning ? 'opacity-100' : 'opacity-0'}`}></div>
                        <div className="relative z-10 flex flex-col items-center justify-center text-center">
                            <div className="mb-6">
                              <h2 className="text-3xl font-bold text-white mb-2">{isRunning ? 'ACTIVE' : 'IDLE'}</h2>
                              <p className="text-slate-400">
                                {isRunning 
                                  ? `${authMode === 'CHEF' ? 'Machine' : 'Container'}: ${activeMachine?.name || 'Unknown'}`
                                  : (authMode === 'CHEF' ? 'No active miners found.' : 'No active container groups.')}
                              </p>
                            </div>

                            <div className={`
