import { SaladOrg, SaladBalance, SaladMachine, SaladContainer, SaladCloudResponse } from '../types';

const CHEF_BASE_URL = 'https://api.salad.com/core/master';
const CLOUD_BASE_URL = 'https://api.salad.com/api/public';
// Use a CORS proxy to bypass browser security restrictions for this frontend-only demo
const CORS_PROXY = 'https://corsproxy.io/?';

export type AuthMode = 'CHEF' | 'CLOUD';

export class SaladApi {
  private credential: string;
  private mode: AuthMode;
  private isDemo: boolean;

  constructor(credential: string, mode: AuthMode, isDemo: boolean = false) {
    this.credential = credential;
    this.mode = mode;
    this.isDemo = isDemo;
  }

  private async request(endpoint: string, options: RequestInit = {}) {
    if (this.isDemo) {
      await new Promise(resolve => setTimeout(resolve, 800));
      return null; // Methods handle demo data return
    }

    const isChef = this.mode === 'CHEF';
    const baseUrl = isChef ? CHEF_BASE_URL : CLOUD_BASE_URL;
    const targetUrl = `${baseUrl}${endpoint}`;

    // Wrap the URL with the proxy
    const finalUrl = `${CORS_PROXY}${encodeURIComponent(targetUrl)}`;

    const headers: Record<string, string> = {
      'Content-Type': 'application/json',
      'Accept': 'application/json',
      ...options.headers as Record<string, string>,
    };

    // Apply specific auth header based on mode
    if (isChef) {
      headers['Authorization'] = `Bearer ${this.credential}`;
    } else {
      headers['Salad-Api-Key'] = this.credential;
    }

    try {
      const response = await fetch(finalUrl, {
        ...options,
        headers,
      });

      if (!response.ok) {
        if (response.status === 401) throw new Error(`Unauthorized: Invalid ${isChef ? 'Token' : 'API Key'}`);
        if (response.status === 403) throw new Error('Forbidden: Access Denied');
        throw new Error(`API Error ${response.status}: ${response.statusText}`);
      }

      return await response.json();
    } catch (error: any) {
      console.error("API Request Failed:", error);
      if (error.name === 'TypeError' && error.message === 'Failed to fetch') {
        throw new Error('Connection Failed: Unable to reach Salad API via Proxy. The proxy might be down or blocked.');
      }
      throw error;
    }
  }

  // Get Organizations
  async getOrgs(): Promise<SaladOrg[]> {
    if (this.isDemo) {
      return [{
        id: 'demo-org-123',
        name: 'chef-demo-org',
        display_name: 'Chef Demo Kitchen'
      }];
    }

    if (this.mode === 'CHEF') {
      // Chef API returns the array directly
      return this.request('/orgs');
    } else {
      // Cloud API returns { items: [] }
      const data = await this.request('/organizations');
      return data.items || [];
    }
  }

  // Get Context/Balance
  async getBalance(orgIdentifier: string): Promise<SaladBalance> {
    if (this.isDemo) {
      return { currentBalance: 14.52, lifetimeBalance: 142.80 };
    }

    if (this.mode === 'CHEF') {
      // orgIdentifier is ID for Chef API
      return this.request(`/orgs/${orgIdentifier}/balance`);
    } else {
      // orgIdentifier is Name/Slug for Cloud API
      // Cloud Public API doesn't easily expose wallet balance. 
      // We verify the org exists and return 0s to prevent UI errors.
      await this.request(`/organizations/${orgIdentifier}`);
      return { currentBalance: 0, lifetimeBalance: 0 };
    }
  }

  // Get Machines/Workloads
  async getMachines(orgIdentifier: string): Promise<SaladMachine[]> {
    if (this.isDemo) {
      return [
        { id: 'm1', name: 'RTX 4090 Machine', status: 'running', miningState: 'mining' },
        { id: 'm2', name: 'Inactive Worker', status: 'stopped', miningState: 'stopped' }
      ];
    }

    if (this.mode === 'CHEF') {
      // orgIdentifier is ID. Returns actual machines list.
      const machines = await this.request(`/orgs/${orgIdentifier}/machines`);
      return machines || [];
    } else {
      // orgIdentifier is Name. Returns Container Groups.
      const data = await this.request(`/organizations/${orgIdentifier}/containers`);
      const containers: SaladContainer[] = data.items || [];

      // Map containers to "Machine" interface for unified UI
      return containers.map(c => ({
        id: c.id,
        name: c.name,
        status: c.status === 'running' ? 'running' : 'stopped',
        miningState: c.status
      }));
    }
  }
}

import { SaladOrg, SaladBalance, SaladMachine, SaladContainer, SaladCloudResponse } from '../types';

const CHEF_BASE_URL = 'https://api.salad.com/core/master';
const CLOUD_BASE_URL = 'https://api.salad.com/api/public';

// Switching to thingproxy as it handles headers reliably for this API
const CORS_PROXY = 'https://thingproxy.freeboard.io/fetch/';

export type AuthMode = 'CHEF' | 'CLOUD';

export class SaladApi {
  private credential: string;
  private mode: AuthMode;
  private isDemo: boolean;

  constructor(credential: string, mode: AuthMode, isDemo: boolean = false) {
    this.credential = credential;
    this.mode = mode;
    this.isDemo = isDemo;
  }

  private async request(endpoint: string, options: RequestInit = {}) {
    if (this.isDemo) {
      await new Promise(resolve => setTimeout(resolve, 800));
      return null;
    }

    const isChef = this.mode === 'CHEF';
    const baseUrl = isChef ? CHEF_BASE_URL : CLOUD_BASE_URL;
    const targetUrl = `${baseUrl}${endpoint}`;

    // thingproxy expects the URL appended directly
    const finalUrl = `${CORS_PROXY}${targetUrl}`;

    const headers: Record<string, string> = {
      'Content-Type': 'application/json',
      'Accept': 'application/json',
      ...options.headers as Record<string, string>,
    };

    if (isChef) {
      headers['Authorization'] = `Bearer ${this.credential}`;
    } else {
      headers['Salad-Api-Key'] = this.credential;
    }

    try {
      const response = await fetch(finalUrl, {
        ...options,
        headers,
      });

      if (!response.ok) {
        if (response.status === 401) throw new Error(`Unauthorized: Invalid ${isChef ? 'Token' : 'API Key'}`);
        if (response.status === 403) throw new Error('Forbidden: Access Denied');
        if (response.status === 404) throw new Error('Not Found');
        throw new Error(`API Error ${response.status}: ${response.statusText}`);
      }

      return await response.json();
    } catch (error: any) {
      console.error("API Request Failed:", error);
      if (error.message === 'Not Found') throw error; // Propagate 404 to be handled by caller
      if (error.name === 'TypeError' && error.message === 'Failed to fetch') {
        throw new Error('Connection Failed: CORS Proxy blocked or API unreachable.');
      }
      throw error;
    }
  }

  async getOrgs(): Promise<SaladOrg[]> {
    if (this.isDemo) {
      return [{
        id: 'demo-org-123',
        name: 'chef-demo-org',
        display_name: 'Chef Demo Kitchen'
      }];
    }

    try {
      if (this.mode === 'CHEF') {
        return await this.request('/orgs');
      } else {
        const data = await this.request('/organizations');
        return data.items || [];
      }
    } catch (error) {
      console.warn("getOrgs failed", error);
      // If getOrgs fails, we can't do much. Rethrow.
      throw error;
    }
  }

  async getBalance(orgIdentifier: string): Promise<SaladBalance> {
    if (this.isDemo) {
      return { currentBalance: 14.52, lifetimeBalance: 142.80 };
    }

    try {
      if (this.mode === 'CHEF') {
        // Handle potential 404 on balance endpoint for new orgs
        return await this.request(`/orgs/${orgIdentifier}/balance`);
      } else {
        // Just verify org exists for cloud
        await this.request(`/organizations/${orgIdentifier}`);
        return { currentBalance: 0, lifetimeBalance: 0 };
      }
    } catch (error: any) {
      if (error.message === 'Not Found') {
        return { currentBalance: 0, lifetimeBalance: 0 };
      }
      throw error;
    }
  }

  async getMachines(orgIdentifier: string): Promise<SaladMachine[]> {
    if (this.isDemo) {
      return [
        { id: 'm1', name: 'RTX 4090 Machine', status: 'running', miningState: 'mining' },
        { id: 'm2', name: 'Inactive Worker', status: 'stopped', miningState: 'stopped' }
      ];
    }

    try {
      if (this.mode === 'CHEF') {
        const machines = await this.request(`/orgs/${orgIdentifier}/machines`);
        return machines || [];
      } else {
        const data = await this.request(`/organizations/${orgIdentifier}/containers`);
        const containers: SaladContainer[] = data.items || [];
        return containers.map(c => ({
          id: c.id,
          name: c.name,
          status: c.status === 'running' ? 'running' : 'stopped',
          miningState: c.status
        }));
      }
    } catch (error: any) {
       if (error.message === 'Not Found') {
        return [];
      }
      throw error;
    }
  }
}

