        if (proxy.isDirect) {
          finalUrl = targetUrl;
        } else {
          const urlToFetch = proxy.encode ? encodeURIComponent(targetUrl) : targetUrl;
          finalUrl = `${proxy.baseUrl}${urlToFetch}`;
        }

        // Add a timeout signal to prevent hanging on bad proxies
        const controller = new AbortController();
        const timeoutId = setTimeout(() => controller.abort(), 8000); // 8s timeout

        const response = await fetch(finalUrl, {
          ...options,
          headers,
          signal: controller.signal
        });

        clearTimeout(timeoutId);

        if (!response.ok) {
           // 401/403: Stop immediately (Auth Error)
           if (response.status === 401) throw new Error(`Unauthorized: Invalid ${isChef ? 'Token' : 'API Key'}`);
           if (response.status === 403) throw new Error('Forbidden: Access Denied');

           // 404: If direct, it's real. If proxy, might be proxy issue.
           if (response.status === 404) {
             if (proxy.isDirect) throw new Error('Not Found');
             throw new Error('Proxy 404');
           }

           if (response.status === 429) throw new Error('Rate Limited');

           // Treat 5xx as proxy errors and continue
           throw new Error(`API Error ${response.status}`);
        }

        const data = await response.json();
        success = true;
        return data;

      } catch (error: any) {
        lastError = error;

        // Don't retry on definitive auth/logic errors
        if (
             error.message.startsWith('Unauthorized') || 
             error.message.startsWith('Forbidden') ||
             error.message === 'Not Found' ||
             error.message === 'Rate Limited'
           ) {
            throw error;
        }

        // Debug log
        const proxyName = (proxy as any).isDirect ? 'Direct' : proxy.baseUrl;
        console.warn(`Proxy ${proxyName} failed: ${error.message}`);
      }
    }

    if (!success) {
      console.error("All proxies failed.", lastError);

      // Customize message based on last error
      if (lastError?.name === 'TypeError' && lastError.message === 'Failed to fetch') {
          throw new Error('Network Error: Unable to connect to Salad API via proxies. A CORS extension is likely required.');
      }

      throw lastError || new Error('Unknown Connection Error');
    }
  }

  async getOrgs(): Promise<SaladOrg[]> {
    if (this.isDemo) {
      return [{
        id: 'demo-org-123',
        name: 'chef-demo-org',
        display_name: 'Chef Demo Kitchen'
      }];
    }

    try {
      if (this.mode === 'CHEF') {
        return await this.request('/orgs');
      } else {
        const data = await this.request('/organizations');
        return data.items || [];
      }
    } catch (error) {
      // Pass through specific errors
      throw error;
    }
  }

  async getBalance(orgIdentifier: string): Promise<SaladBalance> {
    if (this.isDemo) {
      return { currentBalance: 14.52, lifetimeBalance: 142.80 };
    }

    try {
      if (this.mode === 'CHEF') {
        return await this.request(`/orgs/${orgIdentifier}/balance`);
      } else {
        // Cloud API check
        await this.request(`/organizations/${orgIdentifier}`);
        return { currentBalance: 0, lifetimeBalance: 0 };
      }
    } catch (error: any) {
      console.warn("Failed to fetch balance", error);
      return { currentBalance: 0, lifetimeBalance: 0 };
    }
  }

  async getMachines(orgIdentifier: string): Promise<SaladMachine[]> {
    if (this.isDemo) {
      return [
        { id: 'm1', name: 'RTX 4090 Machine', status: 'running', miningState: 'mining' },
        { id: 'm2', name: 'Inactive Worker', status: 'stopped', miningState: 'stopped' }
      ];
    }

    try {
      if (this.mode === 'CHEF') {
        const machines = await this.request(`/orgs/${orgIdentifier}/machines`);
        return machines || [];
      } else {
        const data = await this.request(`/organizations/${orgIdentifier}/containers`);
        const containers: SaladContainer[] = data.items || [];
        return containers.map(c => ({
          id: c.id,
          name: c.name,
          status: c.status === 'running' ? 'running' : 'stopped',
          miningState: c.status
        }));
      }
    } catch (error: any) {
       console.warn("Failed to fetch machines", error);
       return [];
    }
  }
}

