import { SaladOrg, SaladBalance, SaladMachine, SaladContainer, SaladCloudResponse } from '../types';

const CHEF_BASE_URL = 'https://api.salad.com/core/master';
const CLOUD_BASE_URL = 'https://api.salad.com/api/public';

// Robust list of proxies to try in order.
// We mix different providers and encoding strategies to avoid single-point failures.
const PROXIES = [
  // CORS Proxy IO (Standard): Usually the fastest and most reliable for mobile.
  { baseUrl: 'https://corsproxy.io/?', encode: false },

  // AllOrigins: Reliable fallback
  { baseUrl: 'https://api.allorigins.win/raw?url=', encode: true },

  // CodeTabs: Very reliable for forwarding Authorization headers.
  { baseUrl: 'https://api.codetabs.com/v1/proxy?quest=', encode: true },

  // ThingProxy: Good backup.
  { baseUrl: 'https://thingproxy.freeboard.io/fetch/', encode: false },

  // CORS Anywhere: Classic fallback (may require user to visit site to unlock).
  { baseUrl: 'https://cors-anywhere.herokuapp.com/', encode: false },

  // Direct: Final fallback for users with extensions or non-browser environments.
  { baseUrl: '', encode: false, isDirect: true },
];

export type AuthMode = 'CHEF' | 'CLOUD';

export class SaladApi {
  private credential: string;
  private mode: AuthMode;
  private isDemo: boolean;

  constructor(credential: string, mode: AuthMode, isDemo: boolean = false) {
    this.credential = credential;
    this.mode = mode;
    this.isDemo = isDemo;
  }

  private async request(endpoint: string, options: RequestInit = {}) {
    if (this.isDemo) {
      await new Promise(resolve => setTimeout(resolve, 800));
      return null;
    }

    const isChef = this.mode === 'CHEF';
    const baseUrl = isChef ? CHEF_BASE_URL : CLOUD_BASE_URL;
    const targetUrl = `${baseUrl}${endpoint}`;

    const headers: Record<string, string> = {
      'Content-Type': 'application/json',
      'Accept': 'application/json',
      ...options.headers as Record<string, string>,
    };

    if (isChef) {
      headers['Authorization'] = `Bearer ${this.credential}`;
    } else {
      headers['Salad-Api-Key'] = this.credential;
    }

    let lastError: Error | null = null;
    let success = false;

    // Try proxies sequentially
    for (const proxy of PROXIES) {
      if (success) break;

      try {
        let finalUrl = '';
        if (proxy.isDirect) {
          finalUrl = targetUrl;
        } else {
          const urlToFetch = proxy.encode ? encodeURIComponent(targetUrl) : targetUrl;
          finalUrl = `${proxy.baseUrl}${urlToFetch}`;
        }

        // Increased timeout to 25s to allow slower mobile networks
        const controller = new AbortController();
        const timeoutId = setTimeout(() => controller.abort(), 25000); 

        const response = await fetch(finalUrl, {
          ...options,
          headers,
          signal: controller.signal
        });

        clearTimeout(timeoutId);

        if (!response.ok) {
           // 401: Stop immediately (Auth Error) - Credentials are wrong regardless of proxy
           // Note: We do NOT stop on 403 anymore, as proxies or WAFs often throw 403s spuriously.
           if (response.status === 401) throw new Error(`Unauthorized: Invalid ${isChef ? 'Token' : 'API Key'}`);

           if (response.status === 403) {
             // If we are Direct, a 403 is definitive.
             if (proxy.isDirect) throw new Error('Forbidden: Access Denied by Salad API');
             throw new Error('Proxy or WAF Forbidden (403)');
           }

           // 404 handling
           if (response.status === 404) {
             if (proxy.isDirect) throw new Error('Not Found');
             // If proxy returns 404, it might be the proxy service failing
             throw new Error('Proxy 404');
           }

           if (response.status === 429) throw new Error('Rate Limited');

           throw new Error(`API Error ${response.status}`);
        }

        const data = await response.json();
        success = true;
        return data;

      } catch (error: any) {
        lastError = error;

        // Don't retry on definitive auth/logic errors
        if (
             error.message.startsWith('Unauthorized') || 
             error.message === 'Not Found' ||
             error.message === 'Rate Limited'
           ) {
            throw error;
        }

        const proxyName = (proxy as any).isDirect ? 'Direct' : proxy.baseUrl;
        console.warn(`Proxy ${proxyName} failed: ${error.message}`);
      }
    }

    if (!success) {
      console.error("All proxies failed.", lastError);

      if (lastError?.name === 'TypeError' && lastError.message === 'Failed to fetch') {
          throw new Error('Network Error: Unable to connect. Mobile browsers often block these connections. Please try the suggestions below.');
      }

      throw lastError || new Error('Unknown Connection Error');
    }
  }

  async getOrgs(): Promise<SaladOrg[]> {
    if (this.isDemo) {
      return [{
        id: 'demo-org-123',
        name: 'chef-demo-org',
        display_name: 'Chef Demo Kitchen'
      }];
    }

    try {
      if (this.mode === 'CHEF') {
        return await this.request('/orgs');
      } else {
        const data = await this.request('/organizations');
        return data.items || [];
      }
    } catch (error) {
      throw error;
    }
  }

  async getBalance(orgIdentifier: string): Promise<SaladBalance> {
    if (this.isDemo) {
      return { currentBalance: 14.52, lifetimeBalance: 142.80 };
    }

    try {
      if (this.mode === 'CHEF') {
        return await this.request(`/orgs/${orgIdentifier}/balance`);
      } else {
        // Cloud API check
        await this.request(`/organizations/${orgIdentifier}`);
        return { currentBalance: 0, lifetimeBalance: 0 };
      }
    } catch (error: any) {
      console.warn("Failed to fetch balance", error);
      return { currentBalance: 0, lifetimeBalance: 0 };
    }
  }

  async getMachines(orgIdentifier: string): Promise<SaladMachine[]> {
    if (this.isDemo) {
      return [
        { id: 'm1', name: 'RTX 4090 Machine', status: 'running', miningState: 'mining' },
        { id: 'm2', name: 'Inactive Worker', status: 'stopped', miningState: 'stopped' }
      ];
    }

    try {
      if (this.mode === 'CHEF') {
        const machines = await this.request(`/orgs/${orgIdentifier}/machines`);
        return machines || [];
      } else {
        const data = await this.request(`/organizations/${orgIdentifier}/containers`);
        const containers: SaladContainer[] = data.items || [];
        return containers.map(c => ({
          id: c.id,
          name: c.name,
          status: c.status === 'running' ? 'running' : 'stopped',
          miningState: c.status
        }));
      }
    } catch (error: any) {
       console.warn("Failed to fetch machines", error);
       return [];
    }
  }
}

import { SaladOrg, SaladBalance, SaladMachine, SaladContainer, SaladCloudResponse } from '../types';

const CHEF_BASE_URL = 'https://api.salad.com/core/master';
const CLOUD_BASE_URL = 'https://api.salad.com/api/public';

// Robust list of proxies to try in order.
// CRITICAL: We only use proxies that are known to forward the 'Authorization' and 'Salad-Api-Key' headers.
// Proxies like 'allorigins' or 'thingproxy' often strip these, causing false 401 Unauthorized errors.
const PROXIES = [
  // CORS Proxy IO: Supports headers, generally reliable.
  { baseUrl: 'https://corsproxy.io/?', encode: true },

  // CodeTabs: Good header support.
  { baseUrl: 'https://api.codetabs.com/v1/proxy?quest=', encode: true },

  // CORS Anywhere: Classic fallback.
  { baseUrl: 'https://cors-anywhere.herokuapp.com/', encode: false },

  // Direct: Final fallback for users with extensions or non-browser environments.
  { baseUrl: '', encode: false, isDirect: true },
];

export type AuthMode = 'CHEF' | 'CLOUD';

export class SaladApi {
  private credential: string;
  private mode: AuthMode;
  private isDemo: boolean;

  constructor(credential: string, mode: AuthMode, isDemo: boolean = false) {
    this.credential = credential;
    this.mode = mode;
    this.isDemo = isDemo;
  }

  private async request(endpoint: string, options: RequestInit = {}) {
    if (this.isDemo) {
      await new Promise(resolve => setTimeout(resolve, 800));
      return null;
    }

    const isChef = this.mode === 'CHEF';
    const baseUrl = isChef ? CHEF_BASE_URL : CLOUD_BASE_URL;
    const targetUrl = `${baseUrl}${endpoint}`;

    const headers: Record<string, string> = {
      'Content-Type': 'application/json',
      'Accept': 'application/json',
      ...options.headers as Record<string, string>,
    };

    if (isChef) {
      headers['Authorization'] = `Bearer ${this.credential}`;
    } else {
      headers['Salad-Api-Key'] = this.credential;
    }

    let lastError: Error | null = null;
    let authFailureFound = false;
    let success = false;

    // Try proxies sequentially
    for (const proxy of PROXIES) {
      if (success) break;

      try {
        let finalUrl = '';
        if (proxy.isDirect) {
          finalUrl = targetUrl;
        } else {
          // Some proxies handle encoded URLs better
          const urlToFetch = proxy.encode ? encodeURIComponent(targetUrl) : targetUrl;
          finalUrl = `${proxy.baseUrl}${urlToFetch}`;
        }

        // Timeout controller
        const controller = new AbortController();
        const timeoutId = setTimeout(() => controller.abort(), 20000); 

        const response = await fetch(finalUrl, {
          ...options,
          headers,
          signal: controller.signal
        });

        clearTimeout(timeoutId);

        if (!response.ok) {
           // 401: Could be real, OR could be the proxy stripping headers.
           // We do NOT stop immediately. We record it and try other proxies.
           if (response.status === 401) {
             console.warn(`Proxy ${proxy.baseUrl} returned 401. Possible header stripping.`);
             authFailureFound = true;
             continue; // Try next proxy
           }

           if (response.status === 403) {
             // 403 is often WAF blocking the proxy IP. Retry with next.
             if (proxy.isDirect) {
                 // If direct fails with 403, it might be real, or missing CORS headers making browser reject.
                 throw new Error('Forbidden (Direct Access)');
             }
             console.warn(`Proxy ${proxy.baseUrl} returned 403 (WAF Block).`);
             continue;
           }

           if (response.status === 429) {
             console.warn(`Proxy ${proxy.baseUrl} rate limited.`);
             continue;
           }

           // Other errors
           throw new Error(`API Error ${response.status}`);
        }

        const data = await response.json();
        success = true;
        return data;

      } catch (error: any) {
        lastError = error;
        const proxyName = (proxy as any).isDirect ? 'Direct' : proxy.baseUrl;
        console.warn(`Proxy ${proxyName} failed: ${error.message}`);

        // If it's a network error (failed to fetch), just continue to next proxy.
      }
    }

    if (!success) {
      // If we saw at least one 401, it's highly likely the credentials are invalid 
      // (or ALL proxies strip headers, which is unlikely with this list).
      if (authFailureFound) {
        throw new Error(`Unauthorized: Invalid ${isChef ? 'Token' : 'API Key'}. Please check your credentials.`);
      }

      console.error("All proxies failed.", lastError);

      if (lastError?.message.includes('Forbidden')) {
          throw new Error('Access Denied: The API blocked the request. Try using Demo Mode.');
      }

      throw new Error('Network Error: Unable to connect via any proxy. This usually means a firewall or browser extension is blocking the connection, or Salad APIs are unreachable.');
    }
  }

  async getOrgs(): Promise<SaladOrg[]> {
    if (this.isDemo) {
      return [{
        id: 'demo-org-123',
        name: 'chef-demo-org',
        display_name: 'Chef Demo Kitchen'
      }];
    }

    return this.mode === 'CHEF' 
      ? await this.request('/orgs') 
      : (await this.request('/organizations')).items || [];
  }

  async getBalance(orgIdentifier: string): Promise<SaladBalance> {
    if (this.isDemo) {
      return { currentBalance: 14.52, lifetimeBalance: 142.80 };
    }

    try {
      if (this.mode === 'CHEF') {
        return await this.request(`/orgs/${orgIdentifier}/balance`);
      } else {
        // Cloud API check just to validate access, returns 0 for now as Cloud API balance format differs
        await this.request(`/organizations/${orgIdentifier}`);
        return { currentBalance: 0, lifetimeBalance: 0 };
      }
    } catch (error: any) {
      console.warn("Failed to fetch balance", error);
      // Don't throw here, partial data is better than crash
      return { currentBalance: 0, lifetimeBalance: 0 };
    }
  }

  async getMachines(orgIdentifier: string): Promise<SaladMachine[]> {
    if (this.isDemo) {
      return [
        { id: 'm1', name: 'RTX 4090 Machine', status: 'running', miningState: 'mining' },
        { id: 'm2', name: 'Inactive Worker', status: 'stopped', miningState: 'stopped' }
      ];
    }

    try {
      if (this.mode === 'CHEF') {
        const machines = await this.request(`/orgs/${orgIdentifier}/machines`);
        return machines || [];
      } else {
        const data = await this.request(`/organizations/${orgIdentifier}/containers`);
        const containers: SaladContainer[] = data.items || [];
        return containers.map(c => ({
          id: c.id,
          name: c.name,
          status: c.status === 'running' ? 'running' : 'stopped',
          miningState: c.status
        }));
      }
    } catch (error: any) {
       console.warn("Failed to fetch machines", error);
       return [];
    }
  }
}

