// -- Components --

const SidebarItem = ({ icon: Icon, label, active = false, onClick }: { icon: any, label: string, active?: boolean, onClick?: () => void }) => (
  <div 
    onClick={onClick}
    className={`flex items-center gap-3 px-4 py-3 cursor-pointer transition-colors ${active ? 'text-salad-accent border-r-2 border-salad-accent bg-salad-bg' : 'text-slate-400 hover:text-slate-200 hover:bg-slate-800'}`}
  >
    <Icon size={20} />
    <span className="font-medium">{label}</span>
  </div>
);

const PipelineStage = ({ 
  icon: Icon, 
  label, 
  status, 
  delay 
}: { 
  icon: any, 
  label: string, 
  status: 'idle' | 'active' | 'completed',
  delay: number 
}) => (
  <div className="flex flex-col items-center gap-2 relative z-10 group min-w-[60px]">
    <div 
      className={`
        w-10 h-10 md:w-12 md:h-12 rounded-full flex items-center justify-center border-2 transition-all duration-500
        ${status === 'active' 
          ? 'bg-salad-bg border-salad-accent text-salad-accent shadow-[0_0_15px_rgba(163,230,53,0.5)] scale-110' 
          : status === 'completed' 
            ? 'bg-salad-accent/20 border-salad-accent text-salad-accent' 
            : 'bg-slate-800 border-slate-600 text-slate-500'}
      `}
      style={{ animationDelay: `${delay}ms` }}
    >
      <Icon size={20} className={status === 'active' ? 'animate-pulse' : ''} />
    </div>
    <span className={`text-[9px] md:text-[10px] font-bold uppercase tracking-wider text-center whitespace-nowrap transition-colors ${status === 'idle' ? 'text-slate-600' : 'text-slate-300'}`}>
      {label}
    </span>
    {status === 'active' && (
      <div className="absolute -top-1 -right-1 w-2.5 h-2.5 bg-blue-500 rounded-full animate-ping"></div>
    )}
  </div>
);

const PipelineConnector = ({ active, delay }: { active: boolean, delay: number }) => (
  <div className="flex-1 h-0.5 bg-slate-700 mx-1 md:mx-2 relative overflow-hidden self-start mt-5 md:mt-6">
    {active && (
      <div 
        className="absolute inset-0 bg-gradient-to-r from-transparent via-salad-accent to-transparent w-1/2 animate-[shimmer_1.5s_infinite_linear]"
        style={{ animationDelay: `${delay}ms` }}
      ></div>
    )}
  </div>
);

