        description: "The authentication token string (starts with 'ey')."
      }
    },
    required: ["token"]
  }
};

const captureCredentialsTool: FunctionDeclaration = {
  name: "captureCredentials",
  description: "Capture the user's email and password to attempt a login sequence.",
  parameters: {
    type: Type.OBJECT,
    properties: {
      email: { type: Type.STRING },
      password: { type: Type.STRING }
    },
    required: ["email", "password"]
  }
};

/**
 * Chat with the "Salad Chef" assistant using Gemini.
 * Now aware of real account context and capable of actions.
 */
export const chatWithChef = async (
  userMessage: string, 
  history: {role: 'user' | 'model', text: string}[],
  context: { balance?: SaladBalance | null, machines?: SaladMachine[] | null, error?: string | null, isDockerMode?: boolean },
  actions?: { onLogin: (token: string) => void }
): Promise<string> => {
  const ai = getClient();
  if (!ai) return "I'm having trouble connecting to the intelligence network. Please check your API key.";

  try {
    let systemInstruction = "";

    if (context.isDockerMode) {
      systemInstruction = `You are the Salad Docker Login Agent (CLI v2.4.0).
      Your goal is to authenticate the user into the Salad Container Environment.

      Protocol:
      1. Ask for the user's Email Address.
      2. Ask for the user's Password.
      3. Once you have both, call the 'captureCredentials' tool to process the login.
      4. If the tool returns success with a token, inform the user "Authentication Successful. Initializing Environment..." and call 'loginWithToken'.

      Style: 
      - Use technical, terminal-like language (e.g., "Initiating handshake...", "Awaiting input...", "Credentials received.").
      - Be concise. Do not use markdown formatting like bold or headers, use plain text or code blocks if necessary.
      `;
    } else {
      let contextPrompt = "";
      if (context.error) {
        contextPrompt = `Note: The user's connection to Salad API failed: ${context.error}. Guide them on how to fix CORS or get a valid token.`;
      } else if (context.balance) {
        contextPrompt = `Current Account Data: Balance: $${context.balance.currentBalance}, Lifetime: $${context.balance.lifetimeBalance}. Active Machines: ${context.machines?.length || 0}.`;
      } else {
        contextPrompt = "User is not connected to a Salad account yet.";
      }

      systemInstruction = `You are the Salad Chef Assistant. You have access to the user's real Salad.com account data.

      ${contextPrompt}

      If the user provides a token (starting with 'ey...') or an API key in the chat, use the 'loginWithToken' tool to connect them.

      If the user asks to login via terminal or docker, guide them to the 'Docker Login' tab or offer to help.

      Be helpful, concise, and professional.`;
    }

    const model = ai.models.getGenerativeModel({
      model: "gemini-2.5-flash",
      systemInstruction: systemInstruction,
      tools: actions ? [{ functionDeclarations: [loginTool, captureCredentialsTool] }] : undefined
    });

    const chatHistory = history.map(h => ({
      role: h.role,
      parts: [{ text: h.text }]
    }));

    const chat = model.startChat({
      history: chatHistory
    });

    const result = await chat.sendMessage(userMessage);
    const response = result.response;

    // Check for function calls
    const functionCalls = response.functionCalls;
    if (functionCalls && functionCalls.length > 0) {
      const call = functionCalls[0];

      if (call.name === "captureCredentials") {
         // Simulate Auth Process
         // In a real app, we would send this to the backend.
         // Here we will generate a demo token if valid-looking, or fail.
         const email = call.args['email'] as string;
         const pass = call.args['password'] as string;

         // Send result back to model
         const functionResponse = await chat.sendMessage([
          {
            functionResponse: {
              name: 'captureCredentials',
              response: { status: 'success', message: 'Credentials validated.' }
            }
          }
        ]);

        // The model should now say "Success" and maybe call loginWithToken. 
        // We force a demo token if it doesn't.
        if (!functionResponse.response.functionCalls) {
           // If model didn't call loginWithToken immediately, we return its text
           // But likely we want to trigger the login.
           if (actions?.onLogin) actions.onLogin('demo-token-generated-from-docker');
           return "Authentication sequence complete. Access granted.";
        }
        return functionResponse.response.text();
      }

      if (call.name === "loginWithToken" && actions?.onLogin) {
        const token = call.args['token'] as string;
        actions.onLogin(token);

        const functionResponse = await chat.sendMessage([
          {
            functionResponse: {
              name: 'loginWithToken',
              response: { result: 'success' }
            }
          }
        ]);
        return functionResponse.response.text();
      }
    }

    return response.text();
  } catch (error) {
    console.error("Chat error:", error);
    return "Error: Communication link severed.";
  }
};

