                            )}
                            {vpnEnabled && (
                                <div className="text-indigo-400 flex items-center gap-1"><Shield size={10} /> VPN: {vpnLocation}</div>
                            )}
                            {!spoofEnabled && !netSpoofEnabled && !vpnEnabled && (
                                <span>Hardware: Default</span>
                            )}
