    <span className={`text-[9px] md:text-[10px] font-bold uppercase tracking-wider text-center whitespace-nowrap transition-colors ${status === 'idle' ? 'text-slate-600' : 'text-slate-300'}`}>
      {label}
    </span>
    {status === 'active' && (
      <div className="absolute -top-1 -right-1 w-2.5 h-2.5 bg-blue-500 rounded-full animate-ping"></div>
    )}
  </div>
);

const PipelineConnector = ({ active, delay }: { active: boolean, delay: number }) => (
  <div className="flex-1 h-0.5 bg-slate-700 mx-1 md:mx-2 relative overflow-hidden self-start mt-5 md:mt-6">
    {active && (
      <div 
        className="absolute inset-0 bg-gradient-to-r from-transparent via-salad-accent to-transparent w-1/2 animate-[shimmer_1.5s_infinite_linear]"
        style={{ animationDelay: `${delay}ms` }}
      ></div>
    )}
  </div>
);

const GoogleIcon = () => (
  <svg className="w-5 h-5" viewBox="0 0 24 24">
    <path
      fill="currentColor"
      d="M22.56 12.25c0-.78-.07-1.53-.2-2.25H12v4.26h5.92c-.26 1.37-1.04 2.53-2.21 3.31v2.77h3.57c2.08-1.92 3.28-4.74 3.28-8.09z"
    />
    <path
      fill="currentColor"
      d="M12 23c2.97 0 5.46-.98 7.28-2.66l-3.57-2.77c-.98.66-2.23 1.06-3.71 1.06-2.86 0-5.29-1.93-6.16-4.53H2.18v2.84C3.99 20.53 7.7 23 12 23z"
    />
    <path
      fill="currentColor"
      d="M5.84 14.09c-.22-.66-.35-1.36-.35-2.09s.13-1.43.35-2.09V7.07H2.18C1.43 8.55 1 10.22 1 12s.43 3.45 1.18 4.93l2.85-2.22.81-.62z"
    />
    <path
      fill="currentColor"
      d="M12 5.38c1.62 0 3.06.56 4.21 1.64l3.15-3.15C17.45 2.09 14.97 1 12 1 7.7 1 3.99 3.47 2.18 7.07l3.66 2.84c.87-2.6 3.3-4.53 6.16-4.53z"
    />
  </svg>
);

const StatusLog = ({ logs }: { logs: string[] }) => {
    const endRef = useRef<HTMLDivElement>(null);
    useEffect(() => endRef.current?.scrollIntoView({ behavior: 'smooth' }), [logs]);
    return (
        <div className="bg-black/50 rounded-lg p-4 font-mono text-xs h-48 overflow-y-auto border border-slate-800">
            {logs.length === 0 && <div className="text-slate-600 italic">Agent awaiting instructions...</div>}
            {logs.map((log, i) => (
                <div key={i} className="mb-1">
                    <span className="text-slate-500 mr-2">[{new Date().toLocaleTimeString()}]</span>
                    <span className={log.includes('Error') || log.includes('Failed') ? 'text-red-400' : log.includes('Success') || log.includes('Established') || log.includes('Restored') ? 'text-green-400' : log.includes('DiffusionNet') ? 'text-purple-400' : 'text-blue-300'}>
                        {log}
                    </span>
                </div>
            ))}
            <div ref={endRef} />
        </div>
    );
};

// -- Main App --

export default function App() {
  // App State
  const [activeTab, setActiveTab] = useState('Dashboard');
  const [credential, setCredential] = useState<string>('');

  // Explicit fields
  const [chefInput, setChefInput] = useState('');
  const [cloudInput, setCloudInput] = useState('');

  const [authMode, setAuthMode] = useState<AuthMode>('CHEF');
  const [showAuthModal, setShowAuthModal] = useState(false);
  const [authStep, setAuthStep] = useState<'SELECT' | 'OAUTH_WAITING' | 'DOCKER_LOGIN'>('SELECT');
  const [authMethod, setAuthMethod] = useState<'google' | 'passkey' | 'backup' | null>(null);
  const [isDemo, setIsDemo] = useState(false);
  const [showManualHelp, setShowManualHelp] = useState(false);
  const [validationWarning, setValidationWarning] = useState<string | null>(null);
  const [isMobile, setIsMobile] = useState(false);
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);

  // Docker Login State
  const [dockerInput, setDockerInput] = useState('');
  const [dockerHistory, setDockerHistory] = useState<{role: 'user' | 'model', text: string}[]>([
      { role: 'model', text: 'Salad Container Engine v2.4.0\nAuthentication Required.\nEmail Address:' }
  ]);
  const [isDockerThinking, setIsDockerThinking] = useState(false);
  const dockerEndRef = useRef<HTMLDivElement>(null);

  // Real Data State
  const [api, setApi] = useState<SaladApi | null>(null);
  const [org, setOrg] = useState<SaladOrg | null>(null);
  const [balance, setBalance] = useState<SaladBalance | null>(null);
  const [machines, setMachines] = useState<SaladMachine[]>([]);
  const [apiError, setApiError] = useState<string | null>(null);
  const [isLoadingData, setIsLoadingData] = useState(false);

  // Mining / Spoofing Settings State
  const [spoofEnabled, setSpoofEnabled] = useState(false);
  const [spoofGPU, setSpoofGPU] = useState('NVIDIA RTX 4090');
  const [spoofCPU, setSpoofCPU] = useState('AMD Ryzen 9 7950X');
  const [vramAlloc, setVramAlloc] = useState(24);
  const [diffusionProxy, setDiffusionProxy] = useState('');

  // New Network/VPN State
  const [netSpoofEnabled, setNetSpoofEnabled] = useState(false);
  const [netUplink, setNetUplink] = useState('10 Gbps Fiber');
  const [vpnEnabled, setVpnEnabled] = useState(false);
  const [vpnLocation, setVpnLocation] = useState('Res-US-East');

  // AI Agent State
  const [agentEnabled, setAgentEnabled] = useState(false);
  const [agentState, setAgentState] = useState<'IDLE' | 'SCANNING' | 'DIAGNOSING' | 'FIXING' | 'VERIFYING'>('IDLE');
  const [networkHealth, setNetworkHealth] = useState(100);
  const [agentLogs, setAgentLogs] = useState<string[]>([]);
  const [isAgentRetrying, setIsAgentRetrying] = useState(false);

  // Token Grabber State
  const [isScanningClipboard, setIsScanningClipboard] = useState(false);

  // Chat State
  const [showChat, setShowChat] = useState(false);
  const [chatInput, setChatInput] = useState('');
  const [messages, setMessages] = useState<ChatMessage[]>([
    { role: 'model', text: 'Salad System Assistant online.' }
  ]);
  const [isChatLoading, setIsChatLoading] = useState(false);
  const chatEndRef = useRef<HTMLDivElement>(null);

  const addAgentLog = (msg: string) => {
    setAgentLogs(prev => [...prev.slice(-49), msg]);
  };

  useEffect(() => {
    const checkMobile = () => setIsMobile(window.innerWidth < 768);
    checkMobile();
    window.addEventListener('resize', checkMobile);

    const storedCred = localStorage.getItem('salad_credential');
    const storedMode = localStorage.getItem('salad_auth_mode') as AuthMode;

    // Load mining settings
    setSpoofEnabled(localStorage.getItem('salad_spoof_enabled') === 'true');
    setSpoofGPU(localStorage.getItem('salad_spoof_gpu') || 'NVIDIA RTX 4090');
    setVramAlloc(parseInt(localStorage.getItem('salad_vram_alloc') || '24'));
    setDiffusionProxy(localStorage.getItem('salad_diff_proxy') || '');

    setNetSpoofEnabled(localStorage.getItem('salad_net_spoof') === 'true');
    setNetUplink(localStorage.getItem('salad_net_uplink') || '10 Gbps Fiber');
    setVpnEnabled(localStorage.getItem('salad_vpn_enabled') === 'true');
    setVpnLocation(localStorage.getItem('salad_vpn_loc') || 'Res-US-East');
    setAgentEnabled(localStorage.getItem('salad_agent_enabled') === 'true');

    if (storedCred) {
      setCredential(storedCred);
      if (storedMode === 'CHEF') {
        setChefInput(storedCred);
      } else {
        setCloudInput(storedCred);
      }

      const mode = storedMode || 'CHEF'; 
      setAuthMode(mode);
      initializeApi(storedCred, mode, false);
    } else {
      setShowAuthModal(true);
    }

    return () => window.removeEventListener('resize', checkMobile);
  }, []);

  // Scroll to bottom of docker terminal
  useEffect(() => {
    if (dockerEndRef.current) {
        dockerEndRef.current.scrollIntoView({ behavior: 'smooth' });
    }
  }, [dockerHistory, authStep]);

  useEffect(() => {
    localStorage.setItem('salad_agent_enabled', agentEnabled.toString());
  }, [agentEnabled]);

  // Agent Logic Loop
  useEffect(() => {
    if (!agentEnabled) return;

    // ACTIVE REMEDIATION: If we see an error, kick off the agent workflow immediately
    if (apiError && agentState === 'IDLE' && !isAgentRetrying) {
        triggerAgentFix("Critical API Connection Failure");
    }

    const interval = setInterval(() => {
        // Random simulated decay for visual effect if healthy
        if (agentState === 'IDLE' && !apiError && networkHealth > 80 && Math.random() > 0.9) {
            const drop = Math.floor(Math.random() * 20) + 10;
            setNetworkHealth(prev => Math.max(0, prev - drop));
        }
        // Trigger fix if health is low
        else if (agentState === 'IDLE' && !apiError && networkHealth < 75) {
            triggerAgentFix("High Latency / Packet Loss Detected");
        }
    }, 2000);

    return () => clearInterval(interval);
  }, [agentEnabled, agentState, networkHealth, apiError, isAgentRetrying]);

  const triggerAgentFix = (issue: string) => {
      if (agentState !== 'IDLE') return;

      setAgentState('SCANNING');
      addAgentLog(`ALERT: ${issue}`);
      addAgentLog(`Initiating autonomous diagnostic sequence...`);

      // Sequence
      setTimeout(() => {
          setAgentState('DIAGNOSING');
          addAgentLog(`Telemetry ingested. Diffusion model analyzing anomalous vectors...`);

          setTimeout(() => {
              setAgentState('FIXING');
              addAgentLog(`Anomaly identified. Applying neural network patch...`);
              addAgentLog(`Rerouting via secure diffusion node...`);

              if (issue.includes('API')) {
                   addAgentLog(`Clearing stale sockets...`);
              }

              setTimeout(() => {
                  setAgentState('VERIFYING');
                  addAgentLog(`Patch applied. Verifying network integrity...`);

                  // RETRY CONNECTION AUTOMATICALLY
                  if (issue.includes('API') || issue.includes('Connection')) {
                       addAgentLog(`[Agent] Attempting auto-reconnect via fresh route...`);
                       setIsAgentRetrying(true);

                       // We delay slightly to let the visual state update
                       setTimeout(() => {
                           if (credential) {
                               // This is the "Fix" - actively calling the init function
                               initializeApi(credential, authMode, isDemo)
                                 .then(() => {
                                     addAgentLog(`[Agent] Connection Restored.`);
                                     setAgentState('IDLE');
                                     setNetworkHealth(100);
                                     setIsAgentRetrying(false);
                                 })
                                 .catch(err => {
                                     addAgentLog(`[Agent] Reconnect attempt failed: ${err.message}`);
                                     setAgentState('IDLE'); // Return to IDLE so loop can catch it again or user can intervene
                                     setIsAgentRetrying(false);
                                 });
                           } else {
                               setAgentState('IDLE');
                               setIsAgentRetrying(false);
                               addAgentLog(`[Agent] Error: No credentials to retry.`);
                           }
                       }, 1000);
                  } else {
                      // Standard health fix (simulation)
                      setTimeout(() => {
                          setAgentState('IDLE');
                          setNetworkHealth(100);
                          addAgentLog(`Success: System restored to 100% efficiency.`);
                      }, 2000);
                  }
              }, 2500);
          }, 2500);
      }, 2000);
  };

  const manuallyTriggerIssue = () => {
      setNetworkHealth(45);
      // Logic loop will catch this
  };

  useEffect(() => {
    if (chatEndRef.current) {
      chatEndRef.current.scrollIntoView({ behavior: 'smooth' });
    }
  }, [messages]);

  // Save mining settings when changed
  useEffect(() => {
    localStorage.setItem('salad_spoof_enabled', spoofEnabled.toString());
    localStorage.setItem('salad_spoof_gpu', spoofGPU);
    localStorage.setItem('salad_vram_alloc', vramAlloc.toString());
    localStorage.setItem('salad_diff_proxy', diffusionProxy);
    localStorage.setItem('salad_net_spoof', netSpoofEnabled.toString());
    localStorage.setItem('salad_net_uplink', netUplink);
    localStorage.setItem('salad_vpn_enabled', vpnEnabled.toString());
    localStorage.setItem('salad_vpn_loc', vpnLocation);
  }, [spoofEnabled, spoofGPU, vramAlloc, diffusionProxy, netSpoofEnabled, netUplink, vpnEnabled, vpnLocation]);

  const initializeApi = async (cred: string, mode: AuthMode, demoMode: boolean) => {
    setApiError(null);
    setIsLoadingData(true);
    setIsDemo(demoMode);
    setValidationWarning(null);

    // If agent is active, show analysis message
    if (agentEnabled) {
       addAgentLog(`[Login] Analyzing credentials for ${mode} access...`);
    }

    try {
      // Pass the log function to SaladApi
      const saladApi = new SaladApi(cred, mode, demoMode, (msg) => {
          if (agentEnabled || msg.includes('Error') || msg.includes('DiffusionNet')) {
             addAgentLog(msg);
          }
      });
      setApi(saladApi);

      const orgs = await saladApi.getOrgs();
      if (orgs && orgs.length > 0) {
        const primaryOrg = orgs[0];
        setOrg(primaryOrg);

        const orgIdentifier = mode === 'CHEF' ? primaryOrg.id : (primaryOrg.name || primaryOrg.id);

        try {
          const [bal, machs] = await Promise.all([
            saladApi.getBalance(orgIdentifier),
            saladApi.getMachines(orgIdentifier)
          ]);
          setBalance(bal);
          setMachines(machs || []);

          if (demoMode) {
             setMessages(prev => [...prev, { role: 'model', text: 'Demo Mode Active. Simulating environment...' }]);
          }
          if (agentEnabled) addAgentLog(`[Login] Access Granted. Session Active.`);
          setShowAuthModal(false);

        } catch (innerErr: any) {
           console.error("Failed to fetch detailed stats", innerErr);
           // We do NOT want to hide this in a "connected but failed" state if we want the agent to fix it.
           // But partially working is better than broken. 
           // If it's a network error, propagate it.
           setApiError(innerErr.message || "Connected, but failed to load details.");
        }
      } else {
        setApiError("No Organizations found. Check your account.");
      }
    } catch (err: any) {
      console.error(err);
      setApiError(err.message || "Failed to connect to Salad API");
      setApi(null); 
      // Do NOT throw here, we want the UI to render the error state so the Agent can "see" it.
    } finally {
      setIsLoadingData(false);
    }
  };

  const detectAndLogin = (credOverride?: string, modeOverride?: AuthMode) => {
    let credToUse = credOverride;
    let modeToUse = modeOverride;
    setValidationWarning(null);

    if (!credToUse) {
        if (credential) {
            credToUse = credential;
        } else if (chefInput) {
            credToUse = chefInput;
            modeToUse = 'CHEF';
        } else if (cloudInput) {
            credToUse = cloudInput;
            modeToUse = 'CLOUD';
        }
    }

    if (!credToUse || !credToUse.trim()) return;

    if (!modeToUse) {
        const isJwt = credToUse.trim().startsWith('ey');
        modeToUse = isJwt ? 'CHEF' : 'CLOUD';
    }

    if (modeToUse === 'CHEF' && !credToUse.trim().startsWith('ey')) {
       setValidationWarning("Note: Standard tokens start with 'ey'.");
    }

    setAuthMode(modeToUse);
    setCredential(credToUse);

    if (modeToUse === 'CHEF') {
        setChefInput(credToUse);
        setCloudInput('');
    } else {
        setCloudInput(credToUse);
        setChefInput('');
    }

    localStorage.setItem('salad_credential', credToUse);
    localStorage.setItem('salad_auth_mode', modeToUse);

    initializeApi(credToUse, modeToUse, false);
  };

  const handleDiffusionScan = async () => {
      setIsScanningClipboard(true);
      setCredential('');

      try {
          const text = await navigator.clipboard.readText();

          // Simulate AI analysis time
          await new Promise(resolve => setTimeout(resolve, 1500));

          if (!text) {
              setValidationWarning("Diffusion Scan: No signal detected in clipboard.");
              setIsScanningClipboard(false);
              return;
          }

          // Simple "AI" pattern recognition
          const jwtMatch = text.match(/ey[A-Za-z0-9-_]+\.[A-Za-z0-9-_]+\.[A-Za-z0-9-_]+/);
          const uuidMatch = text.match(/[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}/);

          if (jwtMatch) {
              setCredential(jwtMatch[0]);
              detectAndLogin(jwtMatch[0]);
          } else if (uuidMatch) {
              // Assume API Key or Org ID
              setCredential(text.trim());
              detectAndLogin(text.trim());
          } else if (text.length > 20) {
              // Assume raw key
              setCredential(text.trim());
              detectAndLogin(text.trim());
          } else {
              setValidationWarning("Diffusion Scan: Clipboard content does not match auth patterns.");
          }
      } catch (err) {
          setValidationWarning("Diffusion Scan blocked by browser permissions.");
      } finally {
          setIsScanningClipboard(false);
      }
  };

  const handleLoginPopup = (method: 'google' | 'passkey' | 'backup') => {
    setAuthStep('OAUTH_WAITING');
    setAuthMethod(method);
    setValidationWarning(null);

    const width = 500;
    const height = 600;
    const left = window.screen.width / 2 - width / 2;
    const top = window.screen.height / 2 - height / 2;

    window.open(
      'https://salad.com/login', 
      'SaladLogin', 
      `width=${width},height=${height},top=${top},left=${left},resizable=yes,scrollbars=yes`
    );
  };

  const handleDemoLogin = () => {
    setShowAuthModal(false);
    setAuthMode('CHEF');
    initializeApi('demo-token', 'CHEF', true);
  };

  const handleLogout = () => {
    localStorage.removeItem('salad_credential');
    localStorage.removeItem('salad_auth_mode');
    setCredential('');
    setChefInput('');
    setCloudInput('');
    setApi(null);
    setBalance(null);
    setMachines([]);
    setOrg(null);
    setApiError(null);
    setIsDemo(false);
    setShowAuthModal(true);
    setAuthStep('SELECT');
    setAuthMethod(null);
  };

  const handleRefresh = () => {
    if (credential || isDemo) initializeApi(credential || 'demo-token', authMode, isDemo);
  };

  const handleSendMessage = async () => {
    if (!chatInput.trim()) return;

    const userMsg = chatInput;
    setMessages(prev => [...prev, { role: 'user', text: userMsg }]);
    setChatInput('');
    setIsChatLoading(true);

    try {
      const responseText = await chatWithChef(
        userMsg, 
        messages, 
        {
          balance: balance,
          machines: machines,
          error: apiError
        },
        {
          onLogin: (token) => {
            detectAndLogin(token, 'CHEF');
          }
        }
      );
      setMessages(prev => [...prev, { role: 'model', text: responseText }]);
    } catch (e) {
      setMessages(prev => [...prev, { role: 'model', text: "Connection error." }]);
    } finally {
      setIsChatLoading(false);
    }
  };

  const handleDockerSubmit = async () => {
      if (!dockerInput.trim()) return;

      const userInput = dockerInput;
      setDockerHistory(prev => [...prev, { role: 'user', text: userInput }]);
      setDockerInput('');
      setIsDockerThinking(true);

      try {
          const responseText = await chatWithChef(
              userInput,
              dockerHistory,
              { isDockerMode: true },
              {
                  onLogin: (token) => {
                      detectAndLogin(token, 'CHEF');
                  }
              }
          );
          setDockerHistory(prev => [...prev, { role: 'model', text: responseText }]);
      } catch (e) {
          setDockerHistory(prev => [...prev, { role: 'model', text: "Error: Connection lost." }]);
      } finally {
          setIsDockerThinking(false);
      }
  };

  // Determine App State based on Real Data OR Spoofed Data
  const activeMachine = machines.find(m => m.status === 'running' || m.miningState === 'mining');
  const isRunning = !!activeMachine;

  const displayMachineName = spoofEnabled ? spoofGPU : (activeMachine?.name || (authMode === 'CHEF' ? 'No Machine' : 'No Workload'));

  const getMethodName = () => {
    if (authMethod === 'passkey') return 'Passkey';
    if (authMethod === 'backup') return 'Backup Code';
    return 'Google';
  }

  // Helper to determine step active for Pipeline
  const isAgentStageActive = (target: string) => {
      const states = ['SCANNING', 'DIAGNOSING', 'FIXING', 'VERIFYING'];
      const index = states.indexOf(agentState);
      const targetIndex = states.indexOf(target);
      return index >= targetIndex;
  }

  const isAgentStageCompleted = (target: string) => {
      const states = ['SCANNING', 'DIAGNOSING', 'FIXING', 'VERIFYING'];
      const index = states.indexOf(agentState);
      const targetIndex = states.indexOf(target);
      return index > targetIndex;
  }

  const getStageStatus = (target: string): 'idle' | 'active' | 'completed' => {
      if (agentState === 'IDLE') return 'idle';
      if (isAgentStageCompleted(target)) return 'completed';
      if (agentState === target) return 'active';
      return 'idle';
  }

  return (
    <div className="flex h-screen bg-salad-bg text-salad-text overflow-hidden font-sans">

      {/* Sidebar - Desktop & Mobile */}
      <div className={`
        fixed md:static inset-y-0 left-0 z-50 w-64 bg-salad-bg border-r border-slate-800 flex flex-col shrink-0 transition-transform duration-300
        ${mobileMenuOpen ? 'translate-x-0' : '-translate-x-full md:translate-x-0'}
      `}>
        <div className="p-6 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <div className="w-8 h-8 bg-salad-accent rounded-full flex items-center justify-center">
              <span className="text-black font-bold text-xl">S</span>
            </div>
            <div className="flex flex-col">
              <span className="text-xl font-bold tracking-tight leading-none">Salad</span>
              <span className="text-[10px] text-slate-500 uppercase tracking-wider">
                {api ? (authMode === 'CHEF' ? 'Chef Mode' : 'Cloud Mode') : 'Clone'}
              </span>
            </div>
          </div>
          <button 
             className="md:hidden text-slate-400 hover:text-white"
             onClick={() => setMobileMenuOpen(false)}
          >
             <X size={20} />
          </button>
        </div>

        <div className="flex-1 py-4">
          <SidebarItem icon={Zap} label="Dashboard" onClick={() => { setActiveTab('Dashboard'); setMobileMenuOpen(false); }} active={activeTab === 'Dashboard'} />
          <SidebarItem icon={HardDrive} label="Miner Config" onClick={() => { setActiveTab('Miner'); setMobileMenuOpen(false); }} active={activeTab === 'Miner'} />
          <SidebarItem icon={Bot} label="AI Network Agent" onClick={() => { setActiveTab('Agent'); setMobileMenuOpen(false); }} active={activeTab === 'Agent'} />
          <SidebarItem icon={ShoppingBag} label="Store" onClick={() => { setActiveTab('Store'); setMobileMenuOpen(false); }} active={activeTab === 'Store'} />
          <SidebarItem icon={Users} label="Community" onClick={() => { setActiveTab('Community'); setMobileMenuOpen(false); }} active={activeTab === 'Community'} />
        </div>

        <div className="p-4 border-t border-slate-800">
          <SidebarItem icon={Settings} label="Settings" />
          {api ? (
             <div className="mt-2 flex items-center gap-3 px-4 py-2 text-red-400 hover:text-red-300 cursor-pointer" onClick={handleLogout}>
                <LogOut size={20} />
                <span className="font-medium">Logout</span>
             </div>
          ) : (
            <button 
              onClick={() => { setShowAuthModal(true); setMobileMenuOpen(false); }}
              className="mt-4 w-full py-2 bg-slate-700 hover:bg-slate-600 rounded text-sm font-semibold transition-colors"
            >
              Login
            </button>
          )}
        </div>
      </div>

      {/* Mobile Overlay */}
      {mobileMenuOpen && (
          <div 
             className="fixed inset-0 bg-black/50 z-40 md:hidden"
             onClick={() => setMobileMenuOpen(false)}
          ></div>
      )}

      {/* Main Content */}
      <div className="flex-1 flex flex-col min-w-0">
        {/* Header */}
        <header className="h-16 border-b border-slate-800 flex items-center justify-between px-4 md:px-8 bg-salad-bg/50 backdrop-blur z-10">
          <div className="flex items-center gap-4">
             <button 
                className="md:hidden text-slate-400 hover:text-white"
                onClick={() => setMobileMenuOpen(true)}
             >
                <Menu size={24} />
