import { SaladOrg, SaladBalance, SaladMachine, SaladContainer, SaladCloudResponse } from '../types';

const CHEF_BASE_URL = 'https://api.salad.com/core/master';
const CLOUD_BASE_URL = 'https://api.salad.com/api/public';

// Robust list of proxies.
// We prioritize proxies that are known to FORWARD the 'Authorization' and 'Salad-Api-Key' headers.
const PROXIES = [
  // Tier 1: High reliability, usually keeps headers
  { baseUrl: 'https://corsproxy.io/?', encode: true, name: 'CORS.io (Global)' },
  { baseUrl: 'https://thingproxy.freeboard.io/fetch/', encode: false, name: 'ThingProxy (EU)' },

  // Tier 2: Community instances (may be slower or rate limited)
  { baseUrl: 'https://cors.eu.org/', encode: false, name: 'CORS.eu.org' },
  { baseUrl: 'https://api.codetabs.com/v1/proxy?quest=', encode: true, name: 'CodeTabs (Cluster)' },

  // Tier 3: Fallbacks (might strip headers or have issues, but worth a try)
  { baseUrl: 'https://cors-anywhere.herokuapp.com/', encode: false, name: 'Heroku (Demo)' },
  { baseUrl: 'https://api.allorigins.win/raw?url=', encode: true, name: 'AllOrigins (US)' },

  // Tier 4: Direct (Last resort)
  { baseUrl: '', encode: false, isDirect: true, name: 'Direct Uplink' },
];

export type AuthMode = 'CHEF' | 'CLOUD';

// Utility to "diffuse" requests by shuffling the proxy list
function shuffleArray<T>(array: T[]): T[] {
  const newArr = [...array];
  for (let i = newArr.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [newArr[i], newArr[j]] = [newArr[j], newArr[i]];
  }
  return newArr;
}

export class SaladApi {
  private credential: string;
  private mode: AuthMode;
  private isDemo: boolean;
  private logger?: (msg: string) => void;

  constructor(credential: string, mode: AuthMode, isDemo: boolean = false, logger?: (msg: string) => void) {
    this.credential = credential;
    this.mode = mode;
    this.isDemo = isDemo;
    this.logger = logger;
  }

  private log(msg: string) {
    if (this.logger) this.logger(msg);
  }

  private async request(endpoint: string, options: RequestInit = {}) {
    if (this.isDemo) {
      await new Promise(resolve => setTimeout(resolve, 800));
      return null;
    }

    const isChef = this.mode === 'CHEF';
    const baseUrl = isChef ? CHEF_BASE_URL : CLOUD_BASE_URL;
    const targetUrl = `${baseUrl}${endpoint}`;

    const headers: Record<string, string> = {
      'Accept': 'application/json',
      ...options.headers as Record<string, string>,
    };

    if (options.body) {
      headers['Content-Type'] = 'application/json';
    }

    if (isChef) {
      headers['Authorization'] = `Bearer ${this.credential}`;
    } else {
      headers['Salad-Api-Key'] = this.credential;
    }

    let authFailureFound = false;
    let success = false;

    // Strategy: 
    // 1. Always try the Tier 1 proxies first.
    // 2. Then shuffle the rest (Tier 2/3) to distribute load.
    // 3. Try Direct last.
    const tier1 = PROXIES.slice(0, 2);
    const others = shuffleArray(PROXIES.slice(2, PROXIES.length - 1));
    const direct = PROXIES[PROXIES.length - 1];

    const runList = [...tier1, ...others, direct];

    this.log(`[DiffusionNet] Initiating request to ${endpoint}...`);

    for (const proxy of runList) {
      if (success) break;

      try {
        let finalUrl = '';
        if (proxy.isDirect) {
          finalUrl = targetUrl;
        } else {
          const urlToFetch = proxy.encode ? encodeURIComponent(targetUrl) : targetUrl;
          finalUrl = `${proxy.baseUrl}${urlToFetch}`;
        }

        this.log(`[DiffusionNet] Routing via ${proxy.name}...`);

        // Timeout 8s for proxies
        const controller = new AbortController();
        const timeoutId = setTimeout(() => controller.abort(), 8000); 

        const response = await fetch(finalUrl, {
          ...options,
          headers, 
          credentials: 'omit', // Important for CORS
          cache: 'no-store',
          signal: controller.signal
        });

        clearTimeout(timeoutId);

        if (!response.ok) {
           if (response.status === 401) {
             authFailureFound = true;
             this.log(`[DiffusionNet] Auth Failure (401) via ${proxy.name}.`);
             throw new Error("Unauthorized");
           }
           if (response.status === 403 || response.status === 429 || response.status >= 500) {
             this.log(`[DiffusionNet] Route congested (${response.status}). Rotating...`);
             continue; // Try next proxy
           }
           // Other errors (404, 400) might be real API errors, but could also be proxy stripping path
           // We'll try to parse JSON to see if it's a Salad error
        }

        const text = await response.text();
        let data;
        try {
            data = JSON.parse(text);
        } catch (e) {
            // HTML response usually means proxy landing page or error or Cloudflare challenge
            this.log(`[DiffusionNet] Invalid packet (HTML/Text) from ${proxy.name}. Rotating...`);
            continue;
        }

        if (!response.ok) {
           // If we have JSON error from salad, throw it as a real error
           const errMsg = data.message || `API Error ${response.status}`;
           this.log(`[DiffusionNet] Endpoint Error: ${errMsg}`);
           throw new Error(errMsg);
        }

        success = true;
        this.log(`[DiffusionNet] Connection Established via ${proxy.name}.`);
        return data;

      } catch (error: any) {
        if (error.message === "Unauthorized") break;
        if (error.name === 'AbortError') {
             this.log(`[DiffusionNet] Timeout via ${proxy.name}.`);
        }
        // Continue loop
      }
    }

    if (!success) {
      if (authFailureFound) {
        throw new Error(`Unauthorized: Invalid ${isChef ? 'Token' : 'API Key'}.`);
      }

      this.log('[DiffusionNet] CRITICAL FAILURE. All routes exhausted.');
      throw new Error("Network Error: Unable to reach Salad API via any Diffusion Layer.");
    }
  }

  async getOrgs(): Promise<SaladOrg[]> {
    if (this.isDemo) {
      return [{
        id: 'demo-org-123',
        name: 'chef-demo-org',
        display_name: 'Chef Demo Kitchen'
      }];
    }
    const result = this.mode === 'CHEF' 
      ? await this.request('/orgs') 
      : (await this.request('/organizations'));

    // Handle list vs single
    if (Array.isArray(result)) return result;
    if (result && result.items) return result.items;
    return result ? [result] : [];
  }

  async getBalance(orgIdentifier: string): Promise<SaladBalance> {
    if (this.isDemo) {
      return { currentBalance: 14.52, lifetimeBalance: 142.80 };
    }
    try {
      if (this.mode === 'CHEF') {
        const res = await this.request(`/orgs/${orgIdentifier}/balance`);
        return res || { currentBalance: 0, lifetimeBalance: 0 };
      } else {
        await this.request(`/organizations/${orgIdentifier}`);
        // Cloud API doesn't expose balance easily, mock 0
        return { currentBalance: 0, lifetimeBalance: 0 };
      }
    } catch (error: any) {
      console.warn("Failed to fetch balance", error);
      throw error;
    }
  }

  async getMachines(orgIdentifier: string): Promise<SaladMachine[]> {
    if (this.isDemo) {
      return [
        { id: 'm1', name: 'RTX 4090 Machine', status: 'running', miningState: 'mining' },
        { id: 'm2', name: 'Inactive Worker', status: 'stopped', miningState: 'stopped' }
      ];
    }
    try {
      if (this.mode === 'CHEF') {
        const machines = await this.request(`/orgs/${orgIdentifier}/machines`);
        return machines || [];
      } else {
        const data = await this.request(`/organizations/${orgIdentifier}/containers`);
        const containers: SaladContainer[] = data?.items || [];
        return containers.map(c => ({
          id: c.id,
          name: c.name,
          status: c.status === 'running' ? 'running' : 'stopped',
          miningState: c.status
        }));
      }
    } catch (error: any) {
       console.warn("Failed to fetch machines", error);
       throw error;
    }
  }
}

