];

export type AuthMode = 'CHEF' | 'CLOUD';

// Utility to "diffuse" requests by shuffling the proxy list
function shuffleArray<T>(array: T[]): T[] {
  const newArr = [...array];
  for (let i = newArr.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [newArr[i], newArr[j]] = [newArr[j], newArr[i]];
  }
  return newArr;
}

export class SaladApi {
  private credential: string;
  private mode: AuthMode;
  private isDemo: boolean;
  private logger?: (msg: string) => void;

  constructor(credential: string, mode: AuthMode, isDemo: boolean = false, logger?: (msg: string) => void) {
    this.credential = credential;
    this.mode = mode;
    this.isDemo = isDemo;
    this.logger = logger;
  }

  private log(msg: string) {
    if (this.logger) this.logger(msg);
  }

  private async request(endpoint: string, options: RequestInit = {}) {
    if (this.isDemo) {
      await new Promise(resolve => setTimeout(resolve, 800));
      return null;
    }

    const isChef = this.mode === 'CHEF';
    const baseUrl = isChef ? CHEF_BASE_URL : CLOUD_BASE_URL;
    // Add Qubit spoof param to bypass caches
    const spoofParam = endpoint.includes('?') ? '&' : '?';
    const targetUrl = `${baseUrl}${endpoint}${spoofParam}_diffusion_qubit=${Math.random().toString(36).substring(7)}`;

    const headers: Record<string, string> = {
      'Accept': 'application/json',
      ...options.headers as Record<string, string>,
    };

    if (options.body) {
      headers['Content-Type'] = 'application/json';
    }

    if (isChef) {
      headers['Authorization'] = `Bearer ${this.credential}`;
    } else {
      headers['Salad-Api-Key'] = this.credential;
    }

    // Brute Force State
    let success = false;
    let attempts = 0;
    const MAX_RETRIES = 3; // "Brute force" depth

    this.log(`[DiffusionNet] Calculating Qubit Prediction for ${endpoint}...`);

    while (!success && attempts < MAX_RETRIES) {
        attempts++;
        // Spoof a random User-Agent for this wave
        const spoofAgent = SPOOF_AGENTS[Math.floor(Math.random() * SPOOF_AGENTS.length)];
        // headers['User-Agent'] = spoofAgent; // Note: Browser might override this, but we try.

        // Shuffle nodes for "Diffusion" effect, but keep Direct last
        const nodes = shuffleArray(DIFFUSION_NODES.filter(n => !n.isDirect));
        nodes.push(DIFFUSION_NODES.find(n => n.isDirect)!);

        if (attempts > 1) {
            this.log(`[Brute Force] Wave ${attempts}/${MAX_RETRIES}: Rotating Diffusion Access Points...`);
        }

        for (const node of nodes) {
            if (success) break;

            try {
                let finalUrl = '';
                if (node.isDirect) {
                    finalUrl = targetUrl;
                } else {
                    const urlToFetch = node.encode ? encodeURIComponent(targetUrl) : targetUrl;
                    finalUrl = `${node.baseUrl}${urlToFetch}`;
                }

                this.log(`[DiffusionNet] Spoofing Endpoint via ${node.name}...`);

                const controller = new AbortController();
                const timeoutId = setTimeout(() => controller.abort(), 8000); 

                const response = await fetch(finalUrl, {
                    ...options,
                    headers: {
                        ...headers,
                        'X-Diffusion-Source': 'Qubit-Net-v4' // Flavor header
                    }, 
                    credentials: 'omit',
                    cache: 'no-store',
                    signal: controller.signal
                });

                clearTimeout(timeoutId);

                if (response.ok) {
                    const text = await response.text();
                    try {
                        const data = JSON.parse(text);
                        success = true;
                        this.log(`[Success] Access Granted via ${node.name}.`);
                        return data;
                    } catch (e) {
                        this.log(`[DiffusionNet] Packet corruption from ${node.name}. Retrying...`);
                    }
                } else {
                    if (response.status === 401) {
                        this.log(`[Auth] Credentials rejected by ${node.name}.`);
                        // If 401, it's likely a real auth error, but we continue just in case it's a proxy issue
                        if (attempts === MAX_RETRIES) throw new Error("Unauthorized: Invalid Token");
                    } else {
                        this.log(`[DiffusionNet] Node Congestion (${response.status}) at ${node.name}.`);
                    }
                }
            } catch (error: any) {
                if (error.name === 'AbortError') {
                    this.log(`[DiffusionNet] Latency timeout at ${node.name}.`);
                }
                // Continue to next node
            }
        }

        // Brief pause between brute force waves
        if (!success && attempts < MAX_RETRIES) {
             await new Promise(resolve => setTimeout(resolve, 1500));
        }
    }

    this.log('[Failure] All Diffusion Access Points Exhausted.');
    throw new Error("Network Error: Unable to reach Salad API via any Diffusion Layer.");
  }

  async getOrgs(): Promise<SaladOrg[]> {
    if (this.isDemo) {
      return [{
        id: 'demo-org-123',
        name: 'chef-demo-org',
        display_name: 'Chef Demo Kitchen'
      }];
    }
    const result = this.mode === 'CHEF' 
      ? await this.request('/orgs') 
      : (await this.request('/organizations'));

    if (Array.isArray(result)) return result;
    if (result && result.items) return result.items;
    return result ? [result] : [];
  }

  async getBalance(orgIdentifier: string): Promise<SaladBalance> {
    if (this.isDemo) {
      return { currentBalance: 14.52, lifetimeBalance: 142.80 };
    }
    try {
      if (this.mode === 'CHEF') {
        const res = await this.request(`/orgs/${orgIdentifier}/balance`);
        return res || { currentBalance: 0, lifetimeBalance: 0 };
      } else {
        await this.request(`/organizations/${orgIdentifier}`);
        return { currentBalance: 0, lifetimeBalance: 0 };
      }
    } catch (error: any) {
      console.warn("Failed to fetch balance", error);
      throw error;
    }
  }

  async getMachines(orgIdentifier: string): Promise<SaladMachine[]> {
    if (this.isDemo) {
      return [
        { id: 'm1', name: 'RTX 4090 Machine', status: 'running', miningState: 'mining' },
        { id: 'm2', name: 'Inactive Worker', status: 'stopped', miningState: 'stopped' }
      ];
    }
    try {
      if (this.mode === 'CHEF') {
        const machines = await this.request(`/orgs/${orgIdentifier}/machines`);
        return machines || [];
      } else {
        const data = await this.request(`/organizations/${orgIdentifier}/containers`);
        const containers: SaladContainer[] = data?.items || [];
        return containers.map(c => ({
          id: c.id,
          name: c.name,
          status: c.status === 'running' ? 'running' : 'stopped',
          miningState: c.status
        }));
      }
    } catch (error: any) {
       console.warn("Failed to fetch machines", error);
       throw error;
    }
  }
}

