const StatusLog = ({ logs }: { logs: string[] }) => {
    const endRef = useRef<HTMLDivElement>(null);
    useEffect(() => endRef.current?.scrollIntoView({ behavior: 'smooth' }), [logs]);
    return (
        <div className="bg-black/50 rounded-lg p-4 font-mono text-xs h-48 overflow-y-auto border border-slate-800">
            {logs.length === 0 && <div className="text-slate-600 italic">Agent awaiting instructions...</div>}
            {logs.map((log, i) => (
                <div key={i} className="mb-1">
                    <span className="text-slate-500 mr-2">[{new Date().toLocaleTimeString()}]</span>
                    <span className={log.includes('Error') || log.includes('Failed') ? 'text-red-400' : log.includes('Success') || log.includes('Granted') || log.includes('Restored') ? 'text-green-400' : log.includes('DiffusionNet') || log.includes('Qubit') ? 'text-purple-400' : 'text-blue-300'}>
                        {log}
                    </span>
                </div>
            ))}
            <div ref={endRef} />
        </div>
    );
};

// Helper to safely parse JWT for display purposes
const parseJwt = (token: string) => {
    try {
        const base64Url = token.split('.')[1];
        const base64 = base64Url.replace(/-/g, '+').replace(/_/g, '/');
        const jsonPayload = decodeURIComponent(window.atob(base64).split('').map(function(c) {
            return '%' + ('00' + c.charCodeAt(0).toString(16)).slice(-2);
        }).join(''));
        return JSON.parse(jsonPayload);
    } catch (e) {
        return null;
    }
};

