  const detectAndLogin = (credOverride?: string, modeOverride?: AuthMode) => {
    let credToUse = credOverride;
    let modeToUse = modeOverride;
    setValidationWarning(null);

    if (!credToUse) {
        if (credential) {
            credToUse = credential;
        } else if (chefInput) {
            credToUse = chefInput;
            modeToUse = 'CHEF';
        } else if (cloudInput) {
            credToUse = cloudInput;
            modeToUse = 'CLOUD';
        }
    }

    if (!credToUse || !credToUse.trim()) return;

    if (!modeToUse) {
        const isJwt = credToUse.trim().startsWith('ey');
        modeToUse = isJwt ? 'CHEF' : 'CLOUD';
    }

    if (modeToUse === 'CHEF' && !credToUse.trim().startsWith('ey')) {
       setValidationWarning("Note: Standard tokens start with 'ey'.");
    }

    setAuthMode(modeToUse);
    setCredential(credToUse);

    if (modeToUse === 'CHEF') {
        setChefInput(credToUse);
        setCloudInput('');
    } else {
        setCloudInput(credToUse);
        setChefInput('');
    }

    localStorage.setItem('salad_credential', credToUse);
    localStorage.setItem('salad_auth_mode', modeToUse);

    initializeApi(credToUse, modeToUse, false);
  };

  const handleDiffusionScan = async () => {
      setIsScanningClipboard(true);
      setCredential('');
      setScanOverlayText('Initializing Scanner...');

      try {
          let text = '';
          try {
             if (navigator.clipboard && navigator.clipboard.readText) {
                text = await navigator.clipboard.readText();
             } else {
                throw new Error("Clipboard API not available");
             }
          } catch (permErr) {
             throw new Error("Clipboard access denied");
          }

          if (!text) {
              setValidationWarning("Diffusion Scan: No signal detected in clipboard.");
              setIsScanningClipboard(false);
              return;
          }

          // Visual Effect Sequence
          const steps = ['Reading Memory Dump...', 'Analyzing Patterns...', 'Decrypting Strings...', 'Verifying Checksum...'];
          for (const step of steps) {
             setScanOverlayText(step);
             // Random duration for realism
             await new Promise(resolve => setTimeout(resolve, 300 + Math.random() * 300));
          }

          // Robust "AI" pattern recognition
          // 1. JWT (starts with ey)
          const jwtMatch = text.match(/ey[A-Za-z0-9-_]+\.[A-Za-z0-9-_]+\.[A-Za-z0-9-_]+/);
          // 2. UUID (common for API keys or Org IDs)
          const uuidMatch = text.match(/[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}/);
          // 3. Hex Strings (ApiKey sometimes)
          const hexMatch = text.match(/[0-9a-fA-F]{32,}/);

          let found = '';
          let type = '';

          if (jwtMatch) {
              found = jwtMatch[0];
              type = 'JWT Token';
          } else if (uuidMatch) {
              found = uuidMatch[0];
              type = 'API Key (UUID)';
          } else if (hexMatch) {
              found = hexMatch[0];
              type = 'API Key (Hex)';
          } else if (text.length > 20 && !text.includes(' ')) {
              // Assume raw key if it looks like garbage text without spaces
              found = text.trim();
              type = 'Unknown Key Format';
          }

          if (found) {
              setScanOverlayText(`Match Found: ${type}`);
              await new Promise(resolve => setTimeout(resolve, 600));

              // ENHANCEMENT: Decode JWT for extra "Agent" feel
              if (type === 'JWT Token') {
                  const decoded = parseJwt(found);
                  if (decoded && (decoded.sub || decoded.email)) {
                       setScanOverlayText(`Identity Confirmed: ${decoded.email || 'Chef ' + decoded.sub.substring(0,8)}...`);
                       await new Promise(resolve => setTimeout(resolve, 800));
                  }
              }

              setCredential(found);
              detectAndLogin(found);
          } else {
              setValidationWarning("Diffusion Scan: Clipboard content does not match known auth patterns.");
          }
      } catch (err) {
          setScanOverlayText("Scan Blocked");
          await new Promise(resolve => setTimeout(resolve, 800));
          setValidationWarning("Diffusion Scan blocked: Browser denied clipboard access. Please paste manually.");
          // Focus manual input
          setTimeout(() => {
              inputRef.current?.focus();
          }, 100);
      } finally {
          setIsScanningClipboard(false);
          setScanOverlayText('');
      }
  };

