                                     addAgentLog(`[Agent] Brute Force failed: ${err.message}`);
                                     // We stay in IDLE to prevent infinite loops if it's truly broken,
                                     // but we could try a 2nd time logic here if needed.
                                     setAgentState('IDLE'); 
                                     setIsAgentRetrying(false);
                                 });
                           } else {
                               setAgentState('IDLE');
                               setIsAgentRetrying(false);
                               addAgentLog(`[Agent] Error: No credentials to retry.`);
