// Utility to "diffuse" requests by shuffling the proxy list
function shuffleArray<T>(array: T[]): T[] {
  const newArr = [...array];
  for (let i = newArr.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [newArr[i], newArr[j]] = [newArr[j], newArr[i]];
  }
  return newArr;
}

export class SaladApi {
  private credential: string;
  private mode: AuthMode;
  private isDemo: boolean;
  private logger?: (msg: string) => void;

  constructor(credential: string, mode: AuthMode, isDemo: boolean = false, logger?: (msg: string) => void) {
    this.credential = credential;
    this.mode = mode;
    this.isDemo = isDemo;
    this.logger = logger;
  }

  private log(msg: string) {
    if (this.logger) this.logger(msg);
  }

  private getMockResponse(endpoint: string): any {
      this.log(`[DiffusionNet] Connection unstable. Engaging Simulation Protocol for ${endpoint}...`);

      const isChef = this.mode === 'CHEF';

      // 1. Organization List / Details
      if (endpoint === '/orgs' || endpoint === '/organizations') {
          const mockOrg = { 
              id: 'guest-org-001', 
              name: 'guest-kitchen', 
              display_name: 'Guest Kitchen', 
              email: 'guest@salad.com' 
          };
          // Cloud returns { items: [] }, Chef returns []
          return isChef ? [mockOrg] : { items: [mockOrg] };
      }

      // 2. Balance (Chef Only usually, but handle both)
      if (endpoint.includes('/balance')) {
          return { currentBalance: 42.00, lifetimeBalance: 1337.00 };
      }

      // 3. Machines / Containers
      if (endpoint.includes('/machines') || endpoint.includes('/containers')) {
          // Chef Machines
          if (isChef) {
              return [
