    let headers: Record<string, string> = {
      'Accept': 'application/json',
      'Cache-Control': 'no-cache, no-store, must-revalidate',
      'Pragma': 'no-cache',
      'Expires': '0',
      ...options.headers as Record<string, string>,
    };

    if (options.body) {
      headers['Content-Type'] = 'application/json';
    }

    if (isChef) {
      headers['Authorization'] = `Bearer ${this.credential}`;
    } else {
      headers['Salad-Api-Key'] = this.credential;
    }

    // Brute Force State
    let success = false;
    let attempts = 0;
    const MAX_RETRIES = 4; // Increased depth for layer catching
    let lastError: any = null;

    this.log(`[DiffusionNet] Calculating Qubit Prediction for ${endpoint}...`);

    while (!success && attempts < MAX_RETRIES) {
        attempts++;

        // --- SPOOFING LAYERS ---
        // 1. Rotate User Agent to look like different clients
        const spoofAgent = SPOOF_AGENTS[Math.floor(Math.random() * SPOOF_AGENTS.length)];

        // 2. Rotate "Layer Catcher" headers (Platform simulation)
        const layerHeaders = LAYER_CATCHERS[attempts % LAYER_CATCHERS.length];

        // Merge headers for this wave
        const attemptHeaders = {
            ...headers,
            ...layerHeaders,
            'X-Request-ID': `req-${Math.random().toString(36).substr(2, 9)}`,
            'X-Diffusion-Layer': `Layer-${attempts}`,
        };

        // Shuffle nodes for "Diffusion" effect, but keep Direct last
        const nodes = shuffleArray(DIFFUSION_NODES.filter(n => !n.isDirect));
        nodes.push(DIFFUSION_NODES.find(n => n.isDirect)!);

        if (attempts > 1) {
            this.log(`[Brute Force] Wave ${attempts}/${MAX_RETRIES}: Catching Network Layers...`);
        }

        for (const node of nodes) {
            if (success) break;

            try {
                let finalUrl = '';
                if (node.isDirect) {
                    finalUrl = targetUrl;
                } else {
                    const urlToFetch = node.encode ? encodeURIComponent(targetUrl) : targetUrl;
                    finalUrl = `${node.baseUrl}${urlToFetch}`;
                }

                this.log(`[DiffusionNet] Spoofing Endpoint via ${node.name} [Layer ${attempts}]...`);

                const controller = new AbortController();
                const timeoutId = setTimeout(() => controller.abort(), 8000); 

                const response = await fetch(finalUrl, {
                    ...options,
                    headers: attemptHeaders, 
                    credentials: 'omit',
                    cache: 'no-store',
                    signal: controller.signal
                });

                clearTimeout(timeoutId);

                if (response.ok) {
                    const text = await response.text();
                    try {
                        const data = JSON.parse(text);
                        success = true;
                        this.log(`[Success] Access Granted via ${node.name} on Layer ${attempts}.`);
                        return data;
                    } catch (e) {
                        this.log(`[DiffusionNet] Packet corruption from ${node.name}. Retrying...`);
                        lastError = e;
                    }
                } else {
                    if (response.status === 401) {
                        this.log(`[Auth] Credentials rejected by ${node.name}.`);
                        // Don't throw immediately, try other nodes/waves
                        lastError = new Error("Unauthorized");
                    } else if (response.status === 403) {
                         this.log(`[DiffusionNet] WAF Layer Caught at ${node.name}. Rotating Headers...`);
                         lastError = new Error("Forbidden");
                    } else {
                        this.log(`[DiffusionNet] Node Congestion (${response.status}) at ${node.name}.`);
