            } catch (error: any) {
                if (error.name === 'AbortError') {
                    this.log(`[DiffusionNet] Latency timeout at ${node.name}.`);
                }
                lastError = error;
                // Continue to next node
            }
        }

        // Brief pause between brute force waves
        if (!success && attempts < MAX_RETRIES) {
             await new Promise(resolve => setTimeout(resolve, 1500));
        }
    }

    // FAILURE HANDLER
    this.log('[Failure] All Diffusion Access Points Exhausted.');

    // Check if we should fallback to simulation (Guest Mode or Demo Mode)
    // This allows the user to "exit the connection screen" even if the network fails
    if (this.credential.includes('guest') || this.credential.includes('demo') || this.credential.includes('diffusion')) {
         this.log('[System] Network Critical. Activating Offline Neural Simulation...');
         return this.getMockResponse(endpoint);
    }

    // If not guest, we throw the error so the Agent can try to fix it
