     setChefInput(guestToken);
     setCloudInput('');
     setAuthMode('CHEF');
     initializeApi(guestToken, 'CHEF', false);
  };

  const handleDiffusionScan = async () => {
      setIsScanningClipboard(true);
      setChefInput('');
      setCloudInput('');
      setScanOverlayText('Initializing Scanner...');

      try {
          const text = await navigator.clipboard.readText();

          if (!text) {
              setValidationWarning("Diffusion Scan: No signal detected in clipboard.");
              setIsScanningClipboard(false);
              return;
          }

          // Visual Effect Sequence
          const steps = ['Reading Memory Dump...', 'Analyzing Patterns...', 'Decrypting Strings...', 'Verifying Checksum...'];
          for (const step of steps) {
             setScanOverlayText(step);
             await new Promise(resolve => setTimeout(resolve, 300 + Math.random() * 300));
          }

          const jwtMatch = text.match(/ey[A-Za-z0-9-_]+\.[A-Za-z0-9-_]+\.[A-Za-z0-9-_]+/);
          const uuidMatch = text.match(/[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}/);
          let found = '';
          let type: AuthMode = 'CHEF';

          if (jwtMatch) {
              found = jwtMatch[0];
              type = 'CHEF';
              setScanOverlayText('Chef Token Detected');
          } else if (uuidMatch) {
              found = uuidMatch[0];
              type = 'CLOUD';
              setScanOverlayText('Cloud API Key Detected');
          } else if (text.length > 20 && !text.includes(' ')) {
              found = text.trim();
              type = text.startsWith('ey') ? 'CHEF' : 'CLOUD';
              setScanOverlayText('Unknown Key Format Detected');
          }

          if (found) {
              await new Promise(resolve => setTimeout(resolve, 800));
              setAuthMode(type);
              setCredential(found);
              if (type === 'CHEF') {
                setChefInput(found);
              } else {
                setCloudInput(found);
              }
              initializeApi(found, type, false);
          } else {
              setValidationWarning("Diffusion Scan: No known auth patterns found.");
          }
      } catch (err) {
          setScanOverlayText("Scan Blocked");
          await new Promise(resolve => setTimeout(resolve, 800));
          setValidationWarning("Diffusion Scan blocked. Please paste manually.");
      } finally {
          setIsScanningClipboard(false);
          setScanOverlayText('');
      }
