  const isRunning = !!activeMachine;

  const displayMachineName = spoofEnabled ? spoofGPU : (activeMachine?.name || (authMode === 'CHEF' ? 'No Machine' : 'No Workload'));

  const isAgentStageActive = (target: string) => {
      const states = ['SCANNING', 'DIAGNOSING', 'FIXING', 'VERIFYING'];
      const index = states.indexOf(agentState);
      const targetIndex = states.indexOf(target);
      return index >= targetIndex;
  }

  const isAgentStageCompleted = (target: string) => {
      const states = ['SCANNING', 'DIAGNOSING', 'FIXING', 'VERIFYING'];
      const index = states.indexOf(agentState);
      const targetIndex = states.indexOf(target);
      return index > targetIndex;
