import { GoogleGenAI, FunctionDeclaration, Type, Chat } from "@google/genai";
import { SaladBalance, SaladMachine } from '../types';

const getClient = () => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) {
    console.warn("API Key not found in environment");
    return null;
  }
  return new GoogleGenAI({ apiKey });
};

const loginTool: FunctionDeclaration = {
  name: "loginWithToken",
  description: "Finalize login with a valid Authentication Token.",
  parameters: {
    type: Type.OBJECT,
    properties: {
      token: {
        type: Type.STRING,
        description: "The authentication token string (starts with 'ey')."
      }
    },
    required: ["token"]
  }
};

const captureCredentialsTool: FunctionDeclaration = {
  name: "captureCredentials",
  description: "Capture the user's email and password to attempt a login sequence.",
  parameters: {
    type: Type.OBJECT,
    properties: {
      email: { type: Type.STRING },
      password: { type: Type.STRING }
    },
    required: ["email", "password"]
  }
};

/**
 * Chat with the "Salad Chef" assistant using Gemini.
 * Now aware of real account context and capable of actions.
 */
export const chatWithChef = async (
  userMessage: string, 
  history: {role: 'user' | 'model', text: string}[],
  context: { balance?: SaladBalance | null, machines?: SaladMachine[] | null, error?: string | null, isDockerMode?: boolean },
  actions?: { onLogin: (token: string) => void }
): Promise<string> => {
  const ai = getClient();
  if (!ai) return "I'm having trouble connecting to the intelligence network. Please check your API key.";

  try {
    let systemInstruction = "";

    if (context.isDockerMode) {
      systemInstruction = `You are the Salad Docker Login Utility.
      Your SOLE purpose is to authenticate the user. Do not roleplay. Do not be conversational.

      LOGIC FLOW:
      1. If the user has NOT provided an Email Address, ask for "Email Address:".
      2. If the user has provided an Email but NOT a Password, ask for "Password:".
      3. If you have BOTH Email and Password:
         - Output exactly: "[ANALYZING CREDENTIALS VIA DIFFUSION LAYER...]"
         - Then IMMEDIATELY call the 'captureCredentials' function.

      OUTPUT RULES:
      - Only output the specific request (e.g., "Email Address:", "Password:").
      - Use [BRACKETS] for system status messages.
      `;
    } else {
      let contextPrompt = "";
      if (context.error) {
        contextPrompt = `System Status: API Connection Error (${context.error}). Guide user to check network or use Docker Login.`;
      } else if (context.balance) {
        contextPrompt = `Account Balance: $${context.balance.currentBalance}. Lifetime: $${context.balance.lifetimeBalance}. Machines: ${context.machines?.length || 0}.`;
      } else {
        contextPrompt = "Status: Not Connected.";
      }

      systemInstruction = `You are the Salad System Assistant.

      ${contextPrompt}

      Capabilities:
      - Analyze earnings/spending.
      - Login user via token (call 'loginWithToken' if user pastes a token).

      Be concise. Direct answers only.`;
    }

    const chatHistory = history.map(h => ({
      role: h.role,
      parts: [{ text: h.text }]
    }));

    // Use the modern ai.chats.create() method
    const chat: Chat = ai.chats.create({
        model: 'gemini-3-pro-preview',
        history: chatHistory,
        config: {
          systemInstruction: systemInstruction,
          tools: actions ? [{ functionDeclarations: [loginTool, captureCredentialsTool] }] : undefined
        }
    });

    const result = await chat.sendMessage(userMessage);
    const response = result.response;

    // Check for function calls
    const functionCalls = response.functionCalls;
    if (functionCalls && functionCalls.length > 0) {
      const call = functionCalls[0];

      if (call.name === "captureCredentials") {
         const email = call.args['email'] as string;
         const pass = call.args['password'] as string;

         // Send result back to model
         const functionResponseResult = await chat.sendMessage([
          {
            functionResponse: {
              name: 'captureCredentials',
              response: { status: 'success', message: 'Credentials captured via Diffusion.' }
            }
          }
        ]);

        const nextCalls = functionResponseResult.response.functionCalls;
        if (nextCalls && nextCalls.length > 0) {
            if (nextCalls[0].name === "loginWithToken" && actions?.onLogin) {
                const token = nextCalls[0].args['token'] as string || 'ey-demo-token-generated-from-docker';
                actions.onLogin(token);
                return "Login Successful. Initializing Environment...";
            }
        } else {
             // Fallback
             if (actions?.onLogin) actions.onLogin('ey-demo-token-generated-from-docker');
             return "Login Successful.";
        }

        return functionResponseResult.response.text();
      }

      if (call.name === "loginWithToken" && actions?.onLogin) {
        const token = call.args['token'] as string;
        actions.onLogin(token);

        const functionResponseResult = await chat.sendMessage([
          {
            functionResponse: {
              name: 'loginWithToken',
              response: { result: 'success' }
            }
          }
        ]);
        return functionResponseResult.response.text();
      }
    }

    return response.text();
  } catch (error) {
    console.error("Chat error:", error);
    return "Error: System unresponsive.";
  }
};

