];

const LAYER_CATCHERS = [
    { 'X-Salad-Platform': 'web', 'Sec-Fetch-Site': 'same-origin', 'X-Client-Version': '2.4.0' },
    { 'X-Salad-Platform': 'electron', 'Sec-Fetch-Site': 'none', 'X-Client-Version': '1.0.0-alpha' },
