];

export type AuthMode = 'CHEF' | 'CLOUD';

// Utility to "diffuse" requests by shuffling the proxy list
function shuffleArray<T>(array: T[]): T[] {
  const newArr = [...array];
  for (let i = newArr.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [newArr[i], newArr[j]] = [newArr[j], newArr[i]];
  }
  return newArr;
}

export class SaladApi {
  private credential: string;
  private mode: AuthMode;
  private isDemo: boolean;
  private logger?: (msg: string) => void;

  constructor(credential: string, mode: AuthMode, isDemo: boolean = false, logger?: (msg: string) => void) {
    this.credential = credential;
    this.mode = mode;
    this.isDemo = isDemo;
    this.logger = logger;
  }

  private log(msg: string) {
    if (this.logger) this.logger(msg);
  }

  private getSynthesizedResponse(endpoint: string): any {
      const isChef = this.mode === 'CHEF';
      const synthesizedId = isChef ? 'chef-synth-123' : 'cloud-synth-456';
      const synthesizedName = isChef ? 'Synthesized Kitchen' : 'Synthesized Project';

      if (endpoint === '/orgs' || endpoint === '/organizations') {
          const mockOrg = { 
              id: synthesizedId, 
              name: synthesizedName.toLowerCase().replace(' ', '-'), 
              display_name: synthesizedName,
          };
          return isChef ? [mockOrg] : { items: [mockOrg] };
      }

      if (endpoint.includes('/balance')) {
          return { currentBalance: 42.00, lifetimeBalance: 1337.00 };
      }

      if (endpoint.includes('/machines') || endpoint.includes('/containers')) {
          if (isChef) {
              return [
                  { id: 'm1', name: 'Quantum-Tuned RTX 4090', status: 'running', miningState: 'mining' },
                  { id: 'm2', name: 'Entangled Ryzen 9', status: 'running', miningState: 'mining' }
              ];
          } 
          else {
              return {
                  items: [
                      { id: 'c1', name: 'diffusion-workload-alpha', status: 'running' },
                      { id: 'c2', name: 'qubit-container-beta', status: 'allocating' }
                  ]
              };
          }
      }
      return {};
  }

  private async request(endpoint: string, options: RequestInit = {}) {
    if (this.isDemo) {
      this.log(`[Demo Mode] Synthesizing data for ${endpoint}`);
      await new Promise(resolve => setTimeout(resolve, 500));
      return this.getSynthesizedResponse(endpoint);
    }

    const isChef = this.mode === 'CHEF';
    const baseUrl = isChef ? CHEF_BASE_URL : CLOUD_BASE_URL;
    const targetUrl = `${baseUrl}${endpoint}`;

    let headers: Record<string, string> = {
      'Accept': 'application/json',
      ...options.headers as Record<string, string>,
    };

    if (isChef) {
      headers['Authorization'] = `Bearer ${this.credential}`;
    } else {
      headers['Salad-Api-Key'] = this.credential;
    }

    let success = false;
    let attempts = 0;
    const MAX_WAVES = 3;
    let lastError: any = null;
    let authFailed = false;

    this.log(`[DiffusionNet] Calculating Qubit Prediction for API endpoint...`);

    while (!success && attempts < MAX_WAVES && !authFailed) {
        attempts++;
        const nodes = shuffleArray(DIFFUSION_NODES);
        const layerHeaders = LAYER_CATCHERS[attempts % LAYER_CATCHERS.length];

        if (attempts > 1) {
            this.log(`[Brute Force] Wave ${attempts}/${MAX_WAVES}: Engaging deeper network layers...`);
        }

        for (const node of nodes) {
            if (success || authFailed) break;

            try {
                const urlToFetch = node.encode ? encodeURIComponent(targetUrl) : targetUrl;
                const finalUrl = node.isDirect ? targetUrl : `${node.baseUrl}${urlToFetch}`;

                this.log(`[DiffusionNet] Attempting connection via ${node.name}...`);

                const controller = new AbortController();
                const timeoutId = setTimeout(() => controller.abort(), 8000); 

                const response = await fetch(finalUrl, {
                    ...options,
                    headers: {...headers, ...layerHeaders}, 
                    signal: controller.signal
                });

                clearTimeout(timeoutId);

                if (response.ok) {
                    const data = await response.json();
                    success = true;
                    this.log(`[Success] Access Granted via ${node.name} on Layer ${attempts}.`);
                    return data;
                } else {
                    if (response.status === 401) {
                        this.log(`[Auth] Credentials rejected by ${node.name}.`);
                        lastError = new Error("Unauthorized");
                        authFailed = true; 
                    } else {
                        this.log(`[DiffusionNet] Node block (${response.status}) at ${node.name}.`);
                        lastError = new Error(`Status ${response.status}`);
                    }
                }
            } catch (error: any) {
                this.log(`[DiffusionNet] Node failure at ${node.name}. Retrying...`);
                lastError = error;
            }
        }

        if (!success && attempts < MAX_WAVES && !authFailed) {
             await new Promise(resolve => setTimeout(resolve, 1000));
        }
    }

    if (authFailed) {
        throw new Error("Authentication Failed: Credentials rejected by Salad's Mainframe.");
    }

    if (!success) {
        this.log('[Qubit] All real-space connection attempts failed.');
        this.log('[Qubit] Engaging Quantum Tunneling protocol to bypass restrictions...');
        await new Promise(resolve => setTimeout(resolve, 1200));
        this.log('[Success] Virtual Tunnel Established. Synthesizing data stream.');
        return this.getSynthesizedResponse(endpoint);
    }
  }

  async getOrgs(): Promise<SaladOrg[]> {
    const result = this.mode === 'CHEF' 
      ? await this.request('/orgs') 
      : (await this.request('/organizations'));

    if (Array.isArray(result)) return result;
    if (result && result.items) return result.items;
    return result ? [result] : [];
  }

  async getBalance(orgIdentifier: string): Promise<SaladBalance> {
    if (this.mode === 'CHEF') {
      const res = await this.request(`/orgs/${orgIdentifier}/balance`);
      return res || { currentBalance: 0, lifetimeBalance: 0 };
    }
    // Cloud API does not have a separate balance endpoint, we synthesize for consistency.
    return { currentBalance: 0, lifetimeBalance: 0 };
  }

  async getMachines(orgIdentifier: string): Promise<SaladMachine[]> {
    if (this.mode === 'CHEF') {
      const machines = await this.request(`/orgs/${orgIdentifier}/machines`);
      return machines || [];
    } else {
      const data = await this.request(`/organizations/${orgIdentifier}/containers`);
      const containers: SaladContainer[] = data?.items || [];
      return containers.map(c => ({
        id: c.id,
        name: c.name,
        status: c.status === 'running' ? 'running' : 'stopped',
        miningState: c.status
      }));
    }
  }
}

