             if (!Array.isArray(json.benchmarks.logs)) json.benchmarks.logs = [];
             if (!Array.isArray(json.benchmarks.capabilities)) json.benchmarks.capabilities = [];
             if (!Array.isArray(json.benchmarks.computeEfficiency)) json.benchmarks.computeEfficiency = [];

             // Enforce targets
             json.benchmarks.agiMetrics.balancedSNR = 32.00;
             if (interactionMode === InteractionMode.NANO_GRID) {
                 json.benchmarks.agiMetrics.diffusionTokenConsumption = 12; // Ultra efficient
             }
        }

        return {
            ...json,
            trendData: json.trendData || [],
            trendLabelX: json.trendLabelX || 'Epoch',
            trendLabelY: json.trendLabelY || 'Value',
            trendTitle: json.trendTitle || 'Metric Evolution',
            distributionData: json.distributionData || [],
            distributionLabel: json.distributionLabel || 'State Space',
            distributionColor: json.distributionColor || '#10b981',
            configUsed: { topic, duration: 'Cloud', variable: 'SNR', architecture: ModelArchitecture.MODULAR, paradigm, core },
            type: interactionMode,
            category: 'SYSTEM_LOG'
        };

    } catch (error) {
        console.warn("Cloud fallback", error);
        return runOfflineSimulation(topic, interactionMode, paradigm, core);
    }
};

export const runSimulation = async (topic: string, mode: SimulationMode, architecture: ModelArchitecture, interactionMode: InteractionMode, paradigm: ModelParadigm, isTraining: boolean, trainedModel: TrainedModel | null = null, core: ModelCore = ModelCore.GENESIS_PRO, history: ChatMessage[] | null = null): Promise<ResearchResult> => {
    if (interactionMode === InteractionMode.AGI_CHAT) {
        return runChatInteraction(topic, mode, core, history || []);
    }

    if (mode === SimulationMode.OFFLINE) {
        return new Promise((resolve) => {
            setTimeout(() => {
                resolve(runOfflineSimulation(topic, interactionMode, paradigm, core));
            }, 800); 
        });
    } else {
        return runCloudSimulation(topic, interactionMode, paradigm, core);
    }
};

import React, { useState, useEffect, useRef } from 'react';
import { Microscope, Play, Beaker, Dna, Atom, Wifi, Leaf, Cpu, Brain, Sparkles, MessageSquare, Database, Trophy, Sprout, Layers, FileText, Rocket, CheckCircle, Server, BarChart2, Terminal, WifiOff, Bitcoin, Grid } from 'lucide-react';
import { CodeViewer } from './components/CodeViewer';
import { PaperRenderer } from './components/PaperRenderer';
import { LiveSimulation } from './components/LiveSimulation';
import { ChatInterface } from './components/ChatInterface';
import { BtcMiner } from './components/BtcMiner';
import { runSimulation, resetChat } from './services/geminiService';
import { AppState, ResearchResult, SimulationMode, ModelArchitecture, InteractionMode, ModelParadigm, TrainedModel, ModelCore, ChatMessage } from './types';

export default function App() {
  const [prompt, setPrompt] = useState('');
  const [state, setState] = useState<AppState>(AppState.IDLE);
  const [mode, setMode] = useState<SimulationMode>(SimulationMode.CLOUD);
  const [interactionMode, setInteractionMode] = useState<InteractionMode>(InteractionMode.CLI);
  const [paradigm, setParadigm] = useState<ModelParadigm>(ModelParadigm.SYMBOLIC);
  const [core, setCore] = useState<ModelCore>(ModelCore.GENESIS_PRO);

  const [result, setResult] = useState<ResearchResult | null>(null);
  const [chatHistory, setChatHistory] = useState<ChatMessage[]>([]);
  const [errorMsg, setErrorMsg] = useState('');

  // Sync mode and core
  useEffect(() => {
    if (mode === SimulationMode.OFFLINE && core !== ModelCore.OLLAMA) {
      setCore(ModelCore.OLLAMA);
    } else if (mode === SimulationMode.CLOUD && core === ModelCore.OLLAMA) {
      setCore(ModelCore.GENESIS_PRO);
    }
  }, [mode]);

  useEffect(() => {
    if (core === ModelCore.OLLAMA && mode !== SimulationMode.OFFLINE) {
      setMode(SimulationMode.OFFLINE);
    } else if (core !== ModelCore.OLLAMA && mode === SimulationMode.OFFLINE) {
      setMode(SimulationMode.CLOUD);
    }
  }, [core]);

  // Reset states when interaction mode changes
  useEffect(() => {
      setChatHistory([]);
      setResult(null);
      setState(AppState.IDLE);
      if (interactionMode !== InteractionMode.AGI_CHAT) {
          resetChat();
      }
  }, [interactionMode]);


  const handleSimulate = async () => {
    if (!prompt.trim() || interactionMode === InteractionMode.BTC_MINER) return;

    setErrorMsg('');

    if (interactionMode === InteractionMode.AGI_CHAT) {
        const userMessage: ChatMessage = { role: 'user', content: prompt };
        const newHistory = [...chatHistory, userMessage];
        setChatHistory(newHistory);
        const currentPrompt = prompt;
        setPrompt('');
        setState(AppState.SIMULATING);

        try {
            const data = await runSimulation(
                currentPrompt, 
                mode, 
                ModelArchitecture.MODULAR, 
                interactionMode, 
                paradigm, 
                false,
                null,
                core,
                newHistory
            );
            const modelMessage: ChatMessage = { role: 'model', content: data.abstract };
            setChatHistory([...newHistory, modelMessage]);
        } catch (e: any) {
            console.error(e);
            const errorMessage: ChatMessage = { role: 'model', content: "Sorry, an error occurred. Please try again." };
            setChatHistory([...newHistory, errorMessage]);
        } finally {
            setState(AppState.IDLE);
        }
    } else {
        setState(AppState.SIMULATING);
        try {
          const data = await runSimulation(
              prompt, 
              mode, 
              ModelArchitecture.MODULAR, 
              interactionMode, 
              paradigm, 
              false,
              null,
              core
          );

          setTimeout(() => {
            setResult(data);
            setState(AppState.COMPLETE);
          }, 1000);

        } catch (e: any) {
          console.error(e);
          setErrorMsg("System Error");
          setState(AppState.ERROR);
        }
    }
  };

  const MainContent = () => {
    if (interactionMode === InteractionMode.BTC_MINER) {
      return <BtcMiner />;
    }
    if (interactionMode === InteractionMode.AGI_CHAT) {
      return <ChatInterface history={chatHistory} isLoading={state === AppState.SIMULATING} />;
    }
    if (state === AppState.COMPLETE && result) {
      return <PaperRenderer data={result} />;
    }
    return (
      <div className={`hidden lg:flex flex-col items-center justify-center text-slate-600 border-2 border-dashed border-slate-800 rounded-xl m-4 bg-[#0d1117] w-full`}>
         <div className="p-6 bg-[#161b22] rounded-full mb-6 shadow-sm border border-slate-800">
            {interactionMode === InteractionMode.NANO_GRID ? (
               <Grid size={48} className="text-blue-500 animate-pulse" />
            ) : (
               <Terminal size={48} className="text-emerald-900" />
            )}
         </div>
         <p className="text-slate-400 font-bold text-lg font-mono">
             {interactionMode === InteractionMode.NANO_GRID ? 'NANO-BOT FORGE READY' : 'AGENT.SYS READY'}
         </p>
         <p className="text-sm text-slate-600 max-w-xs text-center mt-2 font-mono">
            {interactionMode === InteractionMode.NANO_GRID ? 'Define Logic Parameters...' : 'Awaiting Task Input...'}
         </p>
      </div>
    );
  };


  return (
    <div className="min-h-screen bg-slate-900 text-slate-200 flex flex-col font-mono print:bg-white print:text-black">

      {/* Navigation Bar */}
      <nav className="bg-[#0d1117] border-b border-slate-800 sticky top-0 z-50 print:hidden">
        <div className="max-w-7xl mx-auto px-4 h-16 flex items-center justify-between">
          <div className="flex items-center space-x-2 text-emerald-500">
            <Terminal size={20} />
            <span className="font-bold text-lg tracking-tight text-slate-200">AGENT<span className="text-emerald-500">.SYS</span></span>
          </div>
          <div className="flex space-x-6 text-xs font-bold text-slate-500 uppercase tracking-widest">
            <span className="hover:text-emerald-400 cursor-pointer transition-colors flex items-center gap-1">System Status: ONLINE</span>
          </div>
        </div>
      </nav>

      <main className="flex-1 flex flex-col lg:flex-row max-w-7xl mx-auto w-full p-4 md:p-8 gap-6 print:p-0 print:block">

        {/* Left Panel */}
        <div className={`flex flex-col gap-6 transition-all duration-500 ease-in-out print:hidden w-full ${interactionMode === InteractionMode.AGI_CHAT || interactionMode === InteractionMode.BTC_MINER || (state === AppState.COMPLETE && result) ? 'lg:w-1/3' : 'lg:w-1/2 lg:mx-auto'}`}>

          <div className="bg-[#161b22] p-4 md:p-6 rounded-xl border border-slate-800 shadow-xl relative overflow-hidden">

             {/* Simulation Mode Toggle */}
             <div className="mb-4">
                 <label className="text-[10px] uppercase font-bold text-slate-500 tracking-wider mb-2 block flex items-center gap-1">
                    <Server size={10} /> Runtime Environment
                 </label>
                 <div className="grid grid-cols-2 gap-2 text-center text-xs font-bold">
                    <button onClick={() => setMode(SimulationMode.CLOUD)} className={`flex items-center justify-center gap-2 p-2 rounded-lg border transition-all ${mode === SimulationMode.CLOUD ? 'bg-emerald-900/30 text-emerald-300 border-emerald-500/50' : 'bg-slate-900 text-slate-500 border-slate-800'}`}>
                        <Wifi size={12} /> CLOUD
                    </button>
                    <button onClick={() => setMode(SimulationMode.OFFLINE)} className={`flex items-center justify-center gap-2 p-2 rounded-lg border transition-all ${mode === SimulationMode.OFFLINE ? 'bg-rose-900/30 text-rose-300 border-rose-500/50' : 'bg-slate-900 text-slate-500 border-slate-800'}`}>
                        <WifiOff size={12} /> OFFLINE
                    </button>
                 </div>
             </div>

            {/* Model Core Selector */}
             <div className="mb-4">
                 <label className="text-[10px] uppercase font-bold text-slate-500 tracking-wider mb-2 block flex items-center gap-1">
                    <Cpu size={10} /> Model Core
                 </label>
                 <div className="grid grid-cols-2 lg:grid-cols-4 gap-2">
                     <button onClick={() => setCore(ModelCore.GENESIS_PRO)} className={`p-2 rounded border text-left transition-all ${core === ModelCore.GENESIS_PRO ? 'bg-indigo-900/30 text-indigo-300 border-indigo-500/50' : 'bg-slate-900 text-slate-500 border-slate-800'}`}>
                         <div className="text-xs font-bold">Genesis Pro</div>
                     </button>
                     <button onClick={() => setCore(ModelCore.LLAMA_3)} className={`p-2 rounded border text-left transition-all ${core === ModelCore.LLAMA_3 ? 'bg-orange-900/30 text-orange-300 border-orange-500/50' : 'bg-slate-900 text-slate-500 border-slate-800'}`}>
                         <div className="text-xs font-bold">Llama 3</div>
                     </button>
                     <button onClick={() => setCore(ModelCore.MISTRAL)} className={`p-2 rounded border text-left transition-all ${core === ModelCore.MISTRAL ? 'bg-teal-900/30 text-teal-300 border-teal-500/50' : 'bg-slate-900 text-slate-500 border-slate-800'}`}>
                         <div className="text-xs font-bold">Mistral</div>
                     </button>
                      <button onClick={() => setCore(ModelCore.OLLAMA)} className={`p-2 rounded border text-left transition-all ${core === ModelCore.OLLAMA ? 'bg-rose-900/30 text-rose-300 border-rose-500/50' : 'bg-slate-900 text-slate-500 border-slate-800'}`}>
                         <div className="text-xs font-bold">Ollama</div>
                     </button>
                 </div>
             </div>

            {/* Interaction Mode */}
            <div className="grid grid-cols-2 gap-2 mb-4">
                 <button onClick={() => setInteractionMode(InteractionMode.CLI)} className={`flex items-center justify-center p-2 rounded-lg border text-[10px] font-bold ${interactionMode === InteractionMode.CLI ? 'bg-slate-800 text-white border-slate-600' : 'bg-slate-900 text-slate-500 border-slate-800'}`}>
                   <Terminal size={12} className="mr-1.5" /> CLI RUNNER
                 </button>
                 <button onClick={() => setInteractionMode(InteractionMode.AGI_CHAT)} className={`flex items-center justify-center p-2 rounded-lg border text-[10px] font-bold ${interactionMode === InteractionMode.AGI_CHAT ? 'bg-blue-900/30 text-blue-400 border-blue-500/50' : 'bg-slate-900 text-slate-500 border-slate-800'}`}>
                   <MessageSquare size={12} className="mr-1.5" /> AGI CHAT
                 </button>
                 <button onClick={() => setInteractionMode(InteractionMode.EVAL_HARNESS)} className={`flex items-center justify-center p-2 rounded-lg border text-[10px] font-bold ${interactionMode === InteractionMode.EVAL_HARNESS ? 'bg-emerald-900/30 text-emerald-400 border-emerald-500/50' : 'bg-slate-900 text-slate-500 border-slate-800'}`}>
                   <BarChart2 size={12} className="mr-1.5" /> EVAL SUITE
                 </button>
                 <button onClick={() => setInteractionMode(InteractionMode.BTC_MINER)} className={`flex items-center justify-center p-2 rounded-lg border text-[10px] font-bold ${interactionMode === InteractionMode.BTC_MINER ? 'bg-yellow-900/30 text-yellow-400 border-yellow-500/50' : 'bg-slate-900 text-slate-500 border-slate-800'}`}>
                   <Bitcoin size={12} className="mr-1.5" /> BTC MINER
                 </button>
                 <button onClick={() => setInteractionMode(InteractionMode.NANO_GRID)} className={`col-span-2 flex items-center justify-center p-2 rounded-lg border text-[10px] font-bold ${interactionMode === InteractionMode.NANO_GRID ? 'bg-blue-600 text-white border-blue-400' : 'bg-slate-900 text-slate-500 border-slate-800'}`}>
                   <Grid size={12} className="mr-1.5" /> NANO GRID (TRAIN)
                 </button>
            </div>

            <div className={`${interactionMode === InteractionMode.BTC_MINER ? 'hidden' : 'space-y-4'}`}>
              <div>
                <label className="block text-xs font-bold text-slate-500 uppercase tracking-wider mb-2">
                  {interactionMode === InteractionMode.EVAL_HARNESS ? "Evaluation Dataset" : interactionMode === InteractionMode.AGI_CHAT ? "Send Message to AGI" : interactionMode === InteractionMode.NANO_GRID ? "Define Nano-Bot Parameters" : "Input Task"}
                </label>
                <textarea 
                  value={prompt}
                  onChange={(e) => setPrompt(e.target.value)}
                  onKeyDown={(e) => {
                      if (e.key === 'Enter' && !e.shiftKey && interactionMode === InteractionMode.AGI_CHAT) {
                          e.preventDefault();
                          handleSimulate();
                      }
                  }}
                  placeholder={
                      interactionMode === InteractionMode.EVAL_HARNESS ? "Loading GSM8K / HumanEval..." :
                      interactionMode === InteractionMode.AGI_CHAT ? "Ask the AGI a question..." :
                      interactionMode === InteractionMode.NANO_GRID ? "e.g. 'Train a physics-aware Nano-LLM for local deployment'..." :
                      "Describe a task for the agent (e.g. 'Solve this math problem and save to file')..."
                  }
                  className="w-full h-24 p-4 bg-[#010409] border border-slate-800 rounded-lg focus:ring-1 focus:ring-emerald-500 focus:border-emerald-500 outline-none resize-none font-mono text-xs text-emerald-400 placeholder-slate-700"
                  disabled={state === AppState.SIMULATING}
                />
              </div>

              <button
                onClick={handleSimulate}
                disabled={state === AppState.SIMULATING || !prompt}
                className={`w-full py-3 px-4 rounded-lg font-bold text-white flex items-center justify-center space-x-2 transition-all shadow-md ${
                  state === AppState.SIMULATING 
                    ? 'bg-slate-800 cursor-not-allowed' 
                    : interactionMode === InteractionMode.NANO_GRID ? 'bg-blue-600 hover:bg-blue-700' : 'bg-emerald-600 hover:bg-emerald-700'
                }`}
              >
                {state === AppState.SIMULATING ? (
                  <>
                    <div className="animate-spin rounded-full h-4 w-4 border-2 border-white border-t-transparent mr-2"></div>
                    <span>EXECUTING...</span>
                  </>
                ) : (
                  <>
                    <Play size={16} fill="currentColor" />
                    <span>{interactionMode === InteractionMode.AGI_CHAT ? 'SEND' : interactionMode === InteractionMode.NANO_GRID ? 'INITIALIZE TRAINING' : 'EXECUTE AGENT'}</span>
                  </>
                )}
              </button>
            </div>
          </div>

          {/* Visualizer */}
          {state === AppState.SIMULATING && interactionMode !== InteractionMode.AGI_CHAT && interactionMode !== InteractionMode.BTC_MINER && (
             <LiveSimulation 
                mode={mode} 
                topic={prompt} 
                interactionMode={interactionMode} 
                architecture={ModelArchitecture.MODULAR}
                paradigm={paradigm}
                isTraining={false}
             />
          )}

          {/* Code Viewer (Always visible in idle/complete for non-chat/miner modes) */}
          {interactionMode !== InteractionMode.AGI_CHAT && interactionMode !== InteractionMode.BTC_MINER && (
             <div className="flex-1 min-h-[400px] hidden md:block">
                <CodeViewer />
             </div>
          )}
        </div>

        {/* Right Panel: Results */}
        <div className="w-full lg:w-2/3 flex flex-col">
           <MainContent />
        </div>
      </main>
    </div>
  );
}

