import React, { useEffect, useState, useRef } from 'react';
import { Layers, Zap, Dna, Terminal, CheckCircle2, MessageSquare, Grid, Database, Brain, Trophy, Sprout, Cpu, ShieldCheck, Languages, HeartHandshake, Scale, ArrowRight, Binary, GitMerge, UserCog, RefreshCw, Atom, Lock, Microscope, Share2, Sparkles } from 'lucide-react';
import { Point, SimulationMode, InteractionMode, ModelArchitecture, ModelParadigm } from '../types';

interface LiveSimulationProps {
  mode: SimulationMode;
  topic: string;
  interactionMode?: InteractionMode;
  architecture?: ModelArchitecture;
  paradigm?: ModelParadigm;
  isTraining?: boolean;
}

const AGENT_STAGES = [
    { id: 'TEXT', label: '1. TEXT VEC', icon: Languages },
    { id: 'DIFF', label: '2. DIFFUSION', icon: RefreshCw },
    { id: 'QUBIT', label: '3. QUBIT ENT', icon: Atom },
    { id: 'RGF', label: '4. RGF FLTR', icon: Layers },
    { id: 'DATA', label: '5. DATA SYNTH', icon: Database },
    { id: 'LOCK', label: '6. AGI LOCK', icon: Lock }
];

const NANO_STAGES = [
    { id: 'P-OPT', label: '1. PROMPT OPT', icon: Sparkles }, // New
    { id: 'D-GEN', label: '2. DIFF-GEN', icon: Database },
    { id: 'NANO', label: '3. NANO-LLM', icon: Cpu },
    { id: 'GATE', label: '4. LOGIC GATE', icon: ShieldCheck },
    { id: 'OPT', label: '5. RECURSIVE', icon: RefreshCw },
    { id: 'DEPLOY', label: '6. LOCAL RUN', icon: Zap }
];

export const LiveSimulation: React.FC<LiveSimulationProps> = ({ mode, topic, interactionMode, architecture, paradigm, isTraining }) => {
  const [particles, setParticles] = useState<Point[]>([]);
  const [logs, setLogs] = useState<string[]>([]);
  const [stage, setStage] = useState(0);

  const STAGES = interactionMode === InteractionMode.NANO_GRID ? NANO_STAGES : AGENT_STAGES;

  useEffect(() => {
      const initialPoints = Array.from({ length: 60 }).map((_, i) => ({
          x: Math.random() * 100,
          y: Math.random() * 100,
          id: `p-${i}`,
          vx: (Math.random() - 0.5) * 0.8,
          vy: (Math.random() - 0.5) * 0.8
      }));
      setParticles(initialPoints);
      setStage(0);
  }, [topic, interactionMode]);

  useEffect(() => {
      const interval = setInterval(() => {
          setStage(prev => (prev + 1) % STAGES.length);
          const currentStage = STAGES[stage];

          let logMsg = `[KERNEL] ${currentStage.id} :: ${currentStage.label}`;
          if (interactionMode === InteractionMode.NANO_GRID) {
             if (currentStage.id === 'P-OPT') logMsg = `[PROMPT] Synthesizing optimal system instruction...`;
             if (currentStage.id === 'D-GEN') logMsg = `[DIFFUSION] Generating verified dataset with SHA-256 grounding...`;
             if (currentStage.id === 'GATE') logMsg = `[LOGIC] Verifying results via Science-Based Entropy Check...`;
             if (currentStage.id === 'OPT') logMsg = `[RECURSIVE] Updating Nano-Weights based on Logic reward...`;
          }

          setLogs(prev => [logMsg, ...prev].slice(0, 5));

          setParticles(prev => prev.map(p => ({
              ...p,
              x: Math.max(0, Math.min(100, p.x + (Math.random()-0.5)*3)),
              y: Math.max(0, Math.min(100, p.y + (Math.random()-0.5)*3))
          })));

      }, 450); 
      return () => clearInterval(interval);
  }, [stage, topic, interactionMode]);

  return (
    <div className="h-64 md:h-96 w-full bg-[#0d1117] rounded-xl overflow-hidden relative border border-slate-800 shadow-inner flex flex-col">
       <div className="absolute top-0 left-0 w-full p-4 z-10 flex justify-between items-start pointer-events-none">
           <div>
               <div className="flex items-center space-x-2">
                   <Terminal size={16} className="text-emerald-400" />
                   <span className="text-xs font-mono font-bold text-slate-200 uppercase tracking-widest">
                       {interactionMode === InteractionMode.NANO_GRID ? 'NANO-BOT FORGE v1.2' : 'GENESIS-PRIME v16.0'}
                   </span>
               </div>
               <div className="mt-1 text-[10px] text-slate-500 font-mono">
                   ARCH: {architecture} | RECURSIVE: ENABLED
               </div>
           </div>

           <div className={`bg-slate-800/80 px-2 py-1 rounded text-[10px] font-mono border flex items-center gap-2 ${
               STAGES[stage]?.id === 'DEPLOY' ? 'text-emerald-300 border-emerald-500/50 bg-emerald-900/20' : 
               STAGES[stage]?.id === 'GATE' ? 'text-amber-400 border-amber-500/30' :
               STAGES[stage]?.id === 'P-OPT' ? 'text-purple-400 border-purple-500/30' :
               'text-slate-300 border-slate-600/30'
           }`}>
               <span className={`w-1.5 h-1.5 rounded-full animate-pulse ${
                   STAGES[stage]?.id === 'DEPLOY' ? 'bg-emerald-400' : 'bg-slate-400'
               }`}></span>
               {STAGES[stage]?.label}
           </div>
       </div>

       <div className="flex-1 relative opacity-50">
