         <p className="text-slate-400 font-bold text-lg font-mono uppercase tracking-widest">
             {interactionMode === InteractionMode.NANO_GRID ? 'AGI-NANO FORGE ACTIVE' : 'AGENT.SYS READY'}
         </p>
         <p className="text-[10px] text-slate-600 mt-2">Awaiting dataset generation parameters...</p>
      </div>
    );
  };

  return (
