export const streamChatWithAgi = async (message: string, history: ChatMessage[], systemPrompt: string, onChunk: (text: string) => void) => {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    if (!activeChatSession) {
        activeChatSession = ai.chats.create({
            model: 'gemini-3-pro-preview',
            config: {
                systemInstruction: `${systemPrompt}\n\nCORE PROTOCOL: You are an ASI-Aligned Neuro-Symbolic Reasoning Engine. 
                1. SEARCH OVER PREDICTION: Do not predict tokens; search for proofs.
                2. HYPOTHESIZE: Start with a logical hypothesis.
