const DenoisingToken: React.FC<{ content: string; isLast: boolean; isLoading: boolean }> = ({ content, isLast, isLoading }) => {
    const [isStabilized, setIsStabilized] = useState(!isLast);

    useEffect(() => {
        if (isLast && isLoading) {
            const timer = setTimeout(() => setIsStabilized(true), 150);
            return () => clearTimeout(timer);
        }
    }, [content, isLast, isLoading]);

    return (
        <span className={`${!isStabilized ? 'animate-pulse blur-[1px] text-blue-400 brightness-150' : 'transition-all duration-300'}`}>
            {content}
        </span>
    );
};

