import React, { useState, useEffect, useRef } from 'react';
import { Microscope, Play, Beaker, Dna, Atom, Wifi, Leaf, Cpu, Brain, Sparkles, MessageSquare, Database, Trophy, Sprout, Layers, FileText, Rocket, CheckCircle, Server, BarChart2, Terminal, WifiOff, Bitcoin, Grid, Settings, RefreshCw, Download, Archive, ShieldCheck, Zap, FastForward } from 'lucide-react';
import { CodeViewer, CODE_FILES } from './components/CodeViewer';
import { PaperRenderer } from './components/PaperRenderer';
import { LiveSimulation } from './components/LiveSimulation';
import { ChatInterface } from './components/ChatInterface';
import { BtcMiner } from './components/BtcMiner';
import { runSimulation, resetChat, streamChatWithAgi } from './services/geminiService';
import { AppState, ResearchResult, SimulationMode, ModelArchitecture, InteractionMode, ModelParadigm, TrainedModel, ModelCore, ChatMessage, WebSource } from './types';
import JSZip from 'jszip';

const ASI_MASTER_DIRECTIVE = `REVISED MASTER DIRECTIVE: ASI-Aligned Neuro-Symbolic Nano-Kernel

OBJECTIVE: Transcend human-level reasoning via recursive algorithmic density within a sub-1B footprint.

1. DENSITY OVER SCALE: Optimize for Kolmogorov Complexity. Learn the rules of the universe, not the content.
2. SYMBOLIC GROUNDING: Integrate a formal verification layer. Text is noise; Code/Math is truth.
3. INFERENCE SEARCH: Implement MCTS (Monte Carlo Tree Search) for decision-making. Thinking time scales with problem difficulty.
4. SELF-EVOLUTION: The model must identify its own cognitive biases and overwrite them in real-time.

OPERATIONAL PROTOCOL:
- HYPOTHESIS GENERATION: Do not answer. Formulate a hypothesis.
- FORMAL PROOF: Attempt to disprove the hypothesis using the Internal Verifier (Symbolic Logic).
- DENOISING: If the hypothesis survives falsification, translate to natural language.
- RECURSION: If the output is novel, feed it back into the context as a new axiom.`;

export default function App() {
  const [prompt, setPrompt] = useState('Optimize ASI-Nano Kernel for FrontierMath research proofs.');
  const [systemPrompt, setSystemPrompt] = useState(ASI_MASTER_DIRECTIVE);
  const [state, setState] = useState<AppState>(AppState.IDLE);
  const [mode, setMode] = useState<SimulationMode>(SimulationMode.CLOUD);
  const [interactionMode, setInteractionMode] = useState<InteractionMode>(InteractionMode.NANO_GRID);
  const [paradigm, setParadigm] = useState<ModelParadigm>(ModelParadigm.DIFFUSION);
  const [core, setCore] = useState<ModelCore>(ModelCore.GENESIS_PRO);

  const [result, setResult] = useState<ResearchResult | null>(null);
  const [chatHistory, setChatHistory] = useState<ChatMessage[]>([]);
  const [isExporting, setIsExporting] = useState(false);
  const [isChatLoading, setIsChatLoading] = useState(false);
  const [errorMsg, setErrorMsg] = useState('');

  const handleSimulate = async () => {
    if (!prompt.trim() || interactionMode === InteractionMode.BTC_MINER) return;

    setResult(null);
    setState(AppState.SIMULATING);
    try {
      const data = await runSimulation(
          prompt, 
          mode, 
          ModelArchitecture.MODULAR, 
          interactionMode, 
          paradigm, 
          false,
          null,
          core,
          null,
          systemPrompt
      );

      setResult(data);
      setState(AppState.COMPLETE);

    } catch (e: any) {
      setErrorMsg("System Error");
      setState(AppState.ERROR);
    }
  };

  const handleSendMessage = async (text: string) => {
    const userMsg: ChatMessage = { role: 'user', content: text };
    setChatHistory(prev => [...prev, userMsg]);
    setIsChatLoading(true);

    const modelMsg: ChatMessage = { role: 'model', content: '' };
    setChatHistory(prev => [...prev, modelMsg]);

    await streamChatWithAgi(text, chatHistory, systemPrompt, (chunkText: string, chunkSources: WebSource[]) => {
        setChatHistory(prev => {
            const newHistory = [...prev];
            const lastMessage = newHistory[newHistory.length - 1];
            lastMessage.content = chunkText;
            lastMessage.webSources = chunkSources; 
            return newHistory;
        });
    });

    setIsChatLoading(false);
  };

  const handleMasterExport = async () => {
    if (!result) return;
    setIsExporting(true);

    try {
      const zip = new JSZip();

      const srcFolder = zip.folder("src");
      if (srcFolder) {
        Object.entries(CODE_FILES).forEach(([filename, content]) => {
          srcFolder.file(filename, content);
        });
      }

      const manifest = {
        project: result.title,
        timestamp: new Date().toISOString(),
        directive: systemPrompt,
        grounding_hash: result.dataAudit?.integrityHash,
        benchmarks: result.benchmarks
      };
      zip.file("manifest.json", JSON.stringify(manifest, null, 2));

      const reportElement = document.getElementById('research-paper-content');
      if (reportElement && (window as any).html2pdf) {
        const pdfBlob = await (window as any).html2pdf()
          .set({ margin: 10, filename: 'report.pdf', image: { type: 'jpeg', quality: 0.98 } })
          .from(reportElement)
          .output('blob');
        zip.file("research_report.pdf", pdfBlob);
      }

      const zipContent = await zip.generateAsync({ type: 'blob' });
      const link = document.createElement('a');
      link.href = URL.createObjectURL(zipContent);
      link.download = `ASI_NANO_WORKSPACE_${Date.now()}.zip`;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);

    } catch (err) {
      console.error("Export Failed", err);
    } finally {
      setIsExporting(false);
    }
  };

  const MainContent = () => {
    if (interactionMode === InteractionMode.BTC_MINER) return <BtcMiner />;
    if (interactionMode === InteractionMode.AGI_CHAT) return <ChatInterface history={chatHistory} isLoading={isChatLoading} onSendMessage={handleSendMessage} />;
    if (state === AppState.COMPLETE && result) return <PaperRenderer data={result} />;

    return (
      <div className={`hidden lg:flex flex-col items-center justify-center text-grok-text-medium border-2 border-dashed border-grok-border rounded-xl m-4 bg-grok-bg-medium w-full`}>
         <div className="p-6 bg-grok-bg-light rounded-full mb-6 shadow-sm border border-grok-border">
            {interactionMode === InteractionMode.NANO_GRID ? <Grid size={48} className="text-grok-accent-blue animate-pulse" /> : <Terminal size={48} className="text-grok-accent-green" />}
         </div>
         <p className="text-grok-text-light font-bold text-lg font-mono uppercase tracking-widest">
             {interactionMode === InteractionMode.NANO_GRID ? 'ASI-NANO KERNEL ACTIVE' : 'AGENT.SYS READY'}
         </p>
         <p className="text-[10px] text-grok-text-medium mt-2">Awaiting dataset generation parameters...</p>
      </div>
    );
  };

  return (
    <div className="min-h-screen bg-grok-bg-dark text-grok-text-light flex flex-col font-sans">
      <nav className="bg-grok-bg-dark border-b border-grok-border sticky top-0 z-50">
        <div className="max-w-7xl mx-auto px-4 h-16 flex items-center justify-between">
          <div className="flex items-center space-x-2 text-grok-accent-blue">
            <Zap size={20} className="animate-pulse" />
            <span className="font-bold text-lg tracking-tight text-grok-text-light uppercase">ASI<span className="text-grok-accent-blue">.Forge</span></span>
          </div>
          <div className="flex items-center gap-4">
              {result && (
                <button 
                  onClick={handleMasterExport}
                  disabled={isExporting}
                  className="hidden md:flex items-center gap-2 bg-grok-accent-blue hover:bg-grok-accent-blue/80 text-grok-text-light px-4 py-1.5 rounded-lg text-[10px] font-bold uppercase transition-all shadow-lg shadow-grok-accent-blue/20 disabled:opacity-50"
                >
                  {isExporting ? <RefreshCw size={14} className="animate-spin" /> : <Archive size={14} />}
                  {isExporting ? 'Packaging ASI...' : 'Export ASI Workspace (.zip)'}
                </button>
              )}
              <div className="text-[9px] font-bold text-grok-accent-blue bg-grok-accent-blue/20 px-3 py-1 rounded-full border border-grok-accent-blue/30 uppercase tracking-widest">ASI-Nano Pipeline: ONLINE</div>
          </div>
        </div>
      </nav>

      <main className="flex-1 flex flex-col lg:flex-row max-w-7xl mx-auto w-full p-4 md:p-8 gap-6">
        <div className={`flex flex-col gap-6 transition-all duration-500 w-full ${interactionMode === InteractionMode.AGI_CHAT || interactionMode === InteractionMode.BTC_MINER || (state === AppState.COMPLETE && result) ? 'lg:w-1/3' : 'lg:w-1/2 lg:mx-auto'}`}>
          <div className="bg-grok-bg-medium p-6 rounded-xl border border-grok-border shadow-xl">
             <div className="mb-4">
                 <label className="text-[10px] uppercase font-bold text-grok-text-medium tracking-wider mb-2 block flex items-center gap-1"><Server size={10} /> Neural Runtime</label>
                 <div className="grid grid-cols-2 gap-2 text-center text-xs font-bold">
                    <button onClick={() => setMode(SimulationMode.CLOUD)} className={`p-2 rounded-lg border transition-all ${mode === SimulationMode.CLOUD ? 'bg-grok-accent-blue/30 text-grok-accent-blue border-grok-accent-blue/50' : 'bg-grok-bg-light text-grok-text-medium border-grok-border'}`}>CLOUD ENGINE</button>
                    <button onClick={() => setMode(SimulationMode.OFFLINE)} className={`p-2 rounded-lg border transition-all ${mode === SimulationMode.OFFLINE ? 'bg-grok-accent-purple/30 text-grok-accent-purple border-grok-accent-purple/50' : 'bg-grok-bg-light text-grok-text-medium border-grok-border'}`}>LOCAL CORE</button>
                 </div>
             </div>

            <div className="grid grid-cols-2 gap-2 mb-4">
                 <button onClick={() => { setInteractionMode(InteractionMode.NANO_GRID); resetChat(); }} className={`flex items-center justify-center p-2 rounded-lg border text-[10px] font-bold ${interactionMode === InteractionMode.NANO_GRID ? 'bg-grok-accent-blue text-grok-text-light border-grok-accent-blue' : 'bg-grok-bg-light text-grok-text-medium border-grok-border'}`}>
                    <Grid size={12} className="mr-2"/> ASI FORGE
                 </button>
                 <button onClick={() => setInteractionMode(InteractionMode.AGI_CHAT)} className={`flex items-center justify-center p-2 rounded-lg border text-[10px] font-bold ${interactionMode === InteractionMode.AGI_CHAT ? 'bg-grok-accent-green text-grok-text-light border-grok-accent-green' : 'bg-grok-bg-light text-grok-text-medium border-grok-border'}`}>
                    <MessageSquare size={12} className="mr-2"/> ASI CONSOLE
                 </button>
            </div>

            {interactionMode === InteractionMode.NANO_GRID && (
                <div className="mb-6 bg-grok-bg-dark/50 p-4 rounded-lg border border-grok-border/50">
                    <label className="text-[10px] uppercase font-bold text-grok-accent-blue tracking-wider mb-2 block flex items-center gap-1"><Sparkles size={10} /> ASI Master Directive</label>
                    <textarea 
                      value={systemPrompt}
                      onChange={(e) => setSystemPrompt(e.target.value)}
                      placeholder="Enter ASI training directive..."
                      className="w-full h-40 p-3 bg-grok-bg-dark border border-grok-border rounded-lg outline-none font-mono text-[10px] text-grok-accent-blue placeholder-grok-text-dark resize-none leading-relaxed"
                    />
                </div>
            )}

            <div className="space-y-4">
              <label className="block text-xs font-bold text-grok-text-medium uppercase tracking-wider mb-2">ASI Reasoning Objective (e.g. Riemann Hypothesis Proof)</label>
              <textarea 
                value={prompt}
                onChange={(e) => setPrompt(e.target.value)}
                placeholder="Enter objective..."
                className="w-full h-24 p-4 bg-grok-bg-dark border border-grok-border rounded-lg outline-none resize-none font-mono text-xs text-grok-accent-blue placeholder-grok-text-dark"
              />
              <button
                onClick={handleSimulate}
                disabled={state === AppState.SIMULATING || !prompt}
                className={`w-full py-3 px-4 rounded-lg font-bold text-grok-text-light flex items-center justify-center space-x-2 transition-all shadow-lg ${state === AppState.SIMULATING ? 'bg-grok-border' : 'bg-grok-accent-blue hover:bg-grok-accent-blue/80 shadow-grok-accent-blue/20'}`}
              >
                {state === AppState.SIMULATING ? <><RefreshCw size={16} className="animate-spin mr-2"/> COMPILING ASI...</> : <><FastForward size={16} fill="currentColor" /> <span>INITIALIZE ASI CORE</span></>}
              </button>
            </div>
          </div>

          {state === AppState.SIMULATING && interactionMode !== InteractionMode.BTC_MINER && (
             <LiveSimulation mode={mode} topic={prompt} interactionMode={interactionMode} architecture={ModelArchitecture.MODULAR} />
          )}

          <div className="flex-1 min-h-[400px]">
             <CodeViewer />
          </div>
        </div>

        <div className="w-full lg:w-2/3 flex flex-col">
           <MainContent />
        </div>
      </main>
    </div>
  );
}

import React, { useEffect, useState, useRef } from 'react';
import { Layers, Zap, Dna, Terminal, CheckCircle2, MessageSquare, Grid, Database, Brain, Trophy, Sprout, Cpu, ShieldCheck, Languages, HeartHandshake, Scale, ArrowRight, Binary, GitMerge, UserCog, RefreshCw, Atom, Lock, Microscope, Share2, Sparkles } from 'lucide-react';
import { Point, SimulationMode, InteractionMode, ModelArchitecture, ModelParadigm } from '../types';

interface LiveSimulationProps {
  mode: SimulationMode;
  topic: string;
  interactionMode?: InteractionMode;
  architecture?: ModelArchitecture;
  paradigm?: ModelParadigm;
  isTraining?: boolean;
}

const AGENT_STAGES = [
    { id: 'TEXT', label: '1. TEXT VEC', icon: Languages },
    { id: 'DIFF', label: '2. DIFFUSION', icon: RefreshCw },
    { id: 'QUBIT', label: '3. QUBIT ENT', icon: Atom },
    { id: 'RGF', label: '4. RGF FLTR', icon: Layers },
    { id: 'DATA', label: '5. DATA SYNTH', icon: Database },
    { id: 'LOCK', label: '6. AGI LOCK', icon: Lock }
];

const NANO_STAGES = [
    { id: 'P-OPT', label: '1. PROMPT OPT', icon: Sparkles }, // New
    { id: 'D-GEN', label: '2. DIFF-GEN', icon: Database },
    { id: 'NANO', label: '3. NANO-LLM', icon: Cpu },
    { id: 'GATE', label: '4. LOGIC GATE', icon: ShieldCheck },
    { id: 'OPT', label: '5. RECURSIVE', icon: RefreshCw },
    { id: 'DEPLOY', label: '6. LOCAL RUN', icon: Zap }
];

export const LiveSimulation: React.FC<LiveSimulationProps> = ({ mode, topic, interactionMode, architecture, paradigm, isTraining }) => {
  const [particles, setParticles] = useState<Point[]>([]);
  const [logs, setLogs] = useState<string[]>([]);
  const [stage, setStage] = useState(0);

  const STAGES = interactionMode === InteractionMode.NANO_GRID ? NANO_STAGES : AGENT_STAGES;

  useEffect(() => {
      const initialPoints = Array.from({ length: 60 }).map((_, i) => ({
          x: Math.random() * 100,
          y: Math.random() * 100,
          id: `p-${i}`,
          vx: (Math.random() - 0.5) * 0.8,
          vy: (Math.random() - 0.5) * 0.8
      }));
      setParticles(initialPoints);
      setStage(0);
  }, [topic, interactionMode]);

  useEffect(() => {
      const interval = setInterval(() => {
          setStage(prev => (prev + 1) % STAGES.length);
          const currentStage = STAGES[stage];

          let logMsg = `[KERNEL] ${currentStage.id} :: ${currentStage.label}`;
          if (interactionMode === InteractionMode.NANO_GRID) {
             if (currentStage.id === 'P-OPT') logMsg = `[PROMPT] Synthesizing optimal system instruction...`;
             if (currentStage.id === 'D-GEN') logMsg = `[DIFFUSION] Generating verified dataset with SHA-256 grounding...`;
             if (currentStage.id === 'GATE') logMsg = `[LOGIC] Verifying results via Science-Based Entropy Check...`;
             if (currentStage.id === 'OPT') logMsg = `[RECURSIVE] Updating Nano-Weights based on Logic reward...`;
          }

          setLogs(prev => [logMsg, ...prev].slice(0, 5));

          setParticles(prev => prev.map(p => ({
              ...p,
              x: Math.max(0, Math.min(100, p.x + (Math.random()-0.5)*3)),
              y: Math.max(0, Math.min(100, p.y + (Math.random()-0.5)*3))
          })));

      }, 450); 
      return () => clearInterval(interval);
  }, [stage, topic, interactionMode]);

  return (
    <div className="h-64 md:h-96 w-full bg-grok-bg-medium rounded-xl overflow-hidden relative border border-grok-border shadow-inner flex flex-col">
       <div className="absolute top-0 left-0 w-full p-4 z-10 flex justify-between items-start pointer-events-none">
           <div>
               <div className="flex items-center space-x-2">
                   <Terminal size={16} className="text-grok-accent-green" />
                   <span className="text-xs font-mono font-bold text-grok-text-light uppercase tracking-widest">
                       {interactionMode === InteractionMode.NANO_GRID ? 'NANO-BOT FORGE v1.2' : 'GENESIS-PRIME v16.0'}
                   </span>
               </div>
               <div className="mt-1 text-[10px] text-grok-text-medium font-mono">
                   ARCH: {architecture} | RECURSIVE: ENABLED
               </div>
           </div>

           <div className={`bg-grok-bg-light/80 px-2 py-1 rounded text-[10px] font-mono border flex items-center gap-2 ${
               STAGES[stage]?.id === 'DEPLOY' ? 'text-grok-accent-green border-grok-accent-green/50 bg-grok-accent-green/20' : 
               STAGES[stage]?.id === 'GATE' ? 'text-grok-accent-yellow border-grok-accent-yellow/30' :
               STAGES[stage]?.id === 'P-OPT' ? 'text-grok-accent-purple border-grok-accent-purple/30' :
               'text-grok-text-light border-grok-border/30'
           }`}>
               <span className={`w-1.5 h-1.5 rounded-full animate-pulse ${
                   STAGES[stage]?.id === 'DEPLOY' ? 'bg-grok-accent-green' : 'bg-grok-text-light'
               }`}></span>
               {STAGES[stage]?.label}
           </div>
       </div>

       <div className="flex-1 relative opacity-50">
           {particles.map((p) => (
               <div 
                   key={p.id}
                   className={`absolute rounded-full transition-all duration-300 ${
                       interactionMode === InteractionMode.NANO_GRID ? 
                        (STAGES[stage]?.id === 'P-OPT' ? 'bg-grok-accent-purple shadow-[0_0_8px_var(--grok-accent-purple)]' : 
                         STAGES[stage]?.id === 'GATE' ? 'bg-grok-accent-yellow shadow-[0_0_5px_var(--grok-accent-yellow)]' : 'bg-grok-accent-blue') 
                       : 
                        'bg-grok-text-medium'
                   }`}
                   style={{ left: `${p.x}%`, top: `${p.y}%`, width: '2px', height: '2px' }}
               />
           ))}
           {interactionMode === InteractionMode.NANO_GRID && (
               <div className="absolute top-1/2 left-1/2 transform -translate-x-1/2 -translate-y-1/2 w-32 h-32 border border-grok-accent-blue/20 rounded-full flex items-center justify-center animate-pulse">
                   <div className="w-24 h-24 border border-grok-accent-blue/30 rounded-full flex items-center justify-center animate-spin-slow">
                        <Cpu size={24} className="text-grok-accent-blue opacity-50" />
                   </div>
               </div>
           )}
       </div>

       <div className="h-8 bg-grok-bg-light border-t border-grok-border flex items-center px-4 gap-2 overflow-x-auto justify-between">
            {STAGES.map((s, i) => (
                <div key={s.id} className={`flex items-center text-[9px] font-mono whitespace-nowrap ${i === stage ? 'text-grok-accent-green font-bold' : 'text-grok-text-dark'}`}>
                    {i > 0 && <ArrowRight size={10} className="mx-1 opacity-50" />}
                    <span>{s.id}</span>
                </div>
            ))}
       </div>

       <div className="h-20 bg-grok-bg-dark border-t border-grok-border p-2 font-mono text-[10px] text-grok-text-medium overflow-hidden flex flex-col justify-end">
            {logs.map((log, i) => (
                <div key={i} className="truncate opacity-80 border-l-2 border-grok-border pl-2 mb-1">
                    <span className="text-grok-accent-green/80 mr-2">$</span>
                    {log}
                </div>
            ))}
       </div>
    </div>
  );
};

import React, { useEffect, useRef, useState } from 'react';
import { Cpu, User, Sparkles, Send, ShieldCheck, RefreshCw, Activity, Terminal, AlertTriangle, ChevronRight, Zap, Target, Search, Copy, Check, ExternalLink, Database } from 'lucide-react';
