  isLoading: boolean;
  onSendMessage: (text: string) => void;
}

const DenoisingToken: React.FC<{ content: string; isLast: boolean; isLoading: boolean }> = ({ content, isLast, isLoading }) => {
    const [isStabilized, setIsStabilized] = useState(!isLast);

    useEffect(() => {
        if (isLast && isLoading) {
            const timer = setTimeout(() => setIsStabilized(true), 150);
            return () => clearTimeout(timer);
        }
    }, [content, isLast, isLoading]);

    return (
        <span className={`${!isStabilized ? 'animate-pulse blur-[1px] text-grok-accent-blue brightness-150' : 'transition-all duration-300'}`}>
            {content}
        </span>
    );
};

export const ChatInterface: React.FC<ChatInterfaceProps> = ({ history, isLoading, onSendMessage }) => {
    const [input, setInput] = useState('');
    const [denoisingScore, setDenoisingScore] = useState(1.0);
    const [mctsNodes, setMctsNodes] = useState(0);
    const [showBacktrack, setShowBacktrack] = useState(false);
    const [copiedIndex, setCopiedIndex] = useState<number | null>(null);
    const endOfMessagesRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        endOfMessagesRef.current?.scrollIntoView({ behavior: 'smooth' });
    }, [history, isLoading]);

    // Simulate ASI Search Depth
    useEffect(() => {
        let interval: number;
        if (isLoading) {
            interval = window.setInterval(() => {
                setDenoisingScore(0.998 + Math.random() * 0.002);
                setMctsNodes(prev => prev + Math.floor(Math.random() * 5));
                if (Math.random() > 0.95) {
                    setShowBacktrack(true);
                    setTimeout(() => setShowBacktrack(false), 800);
                }
            }, 300);
        } else {
            setDenoisingScore(1.0);
            setMctsNodes(0);
        }
        return () => clearInterval(interval);
    }, [isLoading]);

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        if (input.trim() && !isLoading) {
            onSendMessage(input);
            setInput('');
        }
    };

    const handleCopy = (text: string, index: number) => {
        navigator.clipboard.writeText(text).then(() => {
            setCopiedIndex(index);
            setTimeout(() => setCopiedIndex(null), 2000);
        });
    };

    return (
        <div className="flex flex-col h-full bg-grok-bg-medium rounded-xl border border-grok-border shadow-2xl overflow-hidden font-sans text-grok-text-light w-full animate-in fade-in">
