                    <div className={`flex items-center gap-2 text-[10px] font-bold px-3 py-1 rounded border transition-all ${isLoading ? 'text-grok-accent-blue bg-grok-accent-blue/20 border-grok-accent-blue/30 animate-pulse' : 'text-grok-text-medium bg-grok-bg-light/20 border-grok-border'}`}>
                        <Target size={12} />
