import React, { useState, useEffect, useRef } from 'react';
import { Bitcoin, Zap, Hash, CheckCircle, Terminal, Play, Square, Wallet, Send, Cpu } from 'lucide-react';

const generateHash = () => (Math.random().toString(36).substring(2, 15) + Math.random().toString(36).substring(2, 15)).padEnd(64, '0').substring(0, 64);

interface HashEntry {
    id: number;
    value: string;
    valid: boolean;
}

export const BtcMiner: React.FC = () => {
    const [isRunning, setIsRunning] = useState(false);
    const [hashRate, setHashRate] = useState(0);
    const [blocksFound, setBlocksFound] = useState(0);
    const [balance, setBalance] = useState(0);
    const [hashes, setHashes] = useState<HashEntry[]>([]);
    const [logs, setLogs] = useState<string[]>([]);

    const hashCounterRef = useRef(0);
    const simulationIntervalRef = useRef<number | null>(null);
    const hashDisplayIntervalRef = useRef<number | null>(null);

    const startMining = () => {
        setIsRunning(true);
        setLogs(prev => [`[${new Date().toLocaleTimeString()}] AGI Mining Core engaged. Starting hash diffusion...`, ...prev].slice(0, 10));
    };

    const stopMining = () => {
        setIsRunning(false);
        setLogs(prev => [`[${new Date().toLocaleTimeString()}] Mining paused. Diffusion nodes are idle.`, ...prev].slice(0, 10));
    };

    useEffect(() => {
        if (isRunning) {
            // Main simulation loop
            simulationIntervalRef.current = window.setInterval(() => {
                setHashRate(180 + (Math.random() - 0.5) * 25); // Simulate fluctuating hash rate around 180 TH/s

                // Chance to find a block
                if (Math.random() < 0.05) { // ~ every 10 seconds on average
                    setBlocksFound(prev => prev + 1);
                    const reward = 0.000125;
                    setBalance(prev => prev + reward);
                    const newBlockId = 785000 + blocksFound + 1;
                    setLogs(prev => [`[${new Date().toLocaleTimeString()}] SUCCESS! Block #${newBlockId} found. Reward: ${reward.toFixed(6)} BTC`, ...prev].slice(0, 10));
                    // Add a valid hash to the display
                     const newHash: HashEntry = { id: hashCounterRef.current++, value: '00000000' + generateHash().substring(8), valid: true };
                     setHashes(prev => [newHash, ...prev.slice(0, 49)]);
                }
            }, 500);

            // Hash display loop
            hashDisplayIntervalRef.current = window.setInterval(() => {
                 const newHash: HashEntry = { id: hashCounterRef.current++, value: generateHash(), valid: false };
                 setHashes(prev => [newHash, ...prev.slice(0, 49)]);
            }, 100);

        } else {
            setHashRate(0);
            if (simulationIntervalRef.current) clearInterval(simulationIntervalRef.current);
            if (hashDisplayIntervalRef.current) clearInterval(hashDisplayIntervalRef.current);
        }

        return () => {
            if (simulationIntervalRef.current) clearInterval(simulationIntervalRef.current);
            if (hashDisplayIntervalRef.current) clearInterval(hashDisplayIntervalRef.current);
        };
    }, [isRunning, blocksFound]);

    return (
        <div className="flex flex-col h-full bg-grok-bg-medium rounded-xl border border-grok-border shadow-2xl overflow-hidden font-sans text-grok-text-light w-full animate-in fade-in">
            {/* Header */}
            <div className="flex items-center p-4 border-b border-grok-border bg-grok-bg-light">
                <Cpu size={18} className="text-grok-accent-yellow" />
                <h2 className="ml-3 font-bold text-sm text-grok-text-light tracking-wider uppercase">
                    AGI MINING CONSOLE (SIMULATION)
                </h2>
            </div>

            <div className="flex flex-col md:flex-row flex-1 p-4 gap-4 overflow-hidden">
                {/* Left Panel: Stats & Controls */}
                <div className="w-full md:w-1/3 flex flex-col gap-4">
                    {/* Stats */}
                    <div className="grid grid-cols-2 gap-4">
                        <div className="bg-grok-bg-light p-4 rounded-lg border border-grok-border">
                            <div className="flex items-center text-grok-accent-yellow text-xs uppercase font-bold tracking-wider"><Zap size={12} className="mr-2" /> Hash Rate</div>
                            <div className="text-2xl font-bold mt-2">{hashRate.toFixed(2)} <span className="text-base text-grok-text-medium">TH/s</span></div>
                        </div>
                        <div className="bg-grok-bg-light p-4 rounded-lg border border-grok-border">
                            <div className="flex items-center text-grok-accent-green text-xs uppercase font-bold tracking-wider"><CheckCircle size={12} className="mr-2" /> Blocks Found</div>
                            <div className="text-2xl font-bold mt-2">{blocksFound}</div>
                        </div>
                    </div>
                    <div className="bg-grok-bg-light p-4 rounded-lg border border-grok-border">
                        <div className="text-xs uppercase font-bold tracking-wider text-grok-text-medium">Network Difficulty</div>
                        <div className="text-lg font-bold mt-1">4.89 E13</div>
                    </div>

                    {/* Wallet */}
                    <div className="bg-grok-bg-light p-4 rounded-lg border border-grok-border flex-1 flex flex-col">
                         <div className="flex items-center text-grok-text-light text-xs uppercase font-bold tracking-wider"><Wallet size={12} className="mr-2" /> Wallet</div>
                         <div className="mt-4">
                            <div className="text-[10px] text-grok-text-medium">Balance</div>
                            <div className="text-2xl font-bold text-grok-accent-yellow flex items-center">
                               <Bitcoin size={20} className="mr-2" /> {balance.toFixed(6)}
                            </div>
                         </div>
                         <div className="mt-4">
                            <div className="text-[10px] text-grok-text-medium">Address</div>
                            <div className="text-xs text-grok-text-medium break-all">bc1q-genesis-prime-v16-agisim</div>
                         </div>
                         <div className="flex-1"></div>
                         <button disabled className="w-full mt-4 p-2 bg-grok-border text-grok-text-dark rounded-lg text-sm font-bold flex items-center justify-center gap-2 cursor-not-allowed">
                            <Send size={14} /> Send (Disabled)
                         </button>
                    </div>

                    {/* Controls */}
                    {!isRunning ? (
                         <button onClick={startMining} className="w-full p-3 bg-grok-accent-green hover:bg-grok-accent-green/80 text-grok-text-light rounded-lg font-bold flex items-center justify-center gap-2 transition-colors">
                            <Play size={16} /> START MINING
                         </button>
                    ) : (
                         <button onClick={stopMining} className="w-full p-3 bg-grok-accent-red hover:bg-grok-accent-red/80 text-grok-text-light rounded-lg font-bold flex items-center justify-center gap-2 transition-colors">
                            <Square size={16} /> STOP MINING
                         </button>
                    )}
                </div>

                {/* Right Panel: Hash Feed & Logs */}
                <div className="w-full md:w-2/3 flex flex-col gap-4 h-full overflow-hidden">
                     {/* Hashes */}
                    <div className="bg-grok-bg-dark p-4 rounded-lg border border-grok-border flex-1 flex flex-col overflow-hidden">
                        <div className="flex items-center text-grok-text-medium text-xs uppercase font-bold tracking-wider mb-2"><Hash size={12} className="mr-2" /> SHA-256 Diffusion Feed</div>
                        <div className="flex-1 overflow-y-auto font-mono text-xs">
                            {hashes.map(entry => (
                                <div key={entry.id} className={`${entry.valid ? 'text-grok-accent-green' : 'text-grok-text-medium'}`}>
                                    {entry.value}
                                </div>
                            ))}
                        </div>
                    </div>
                     {/* Logs */}
                    <div className="bg-grok-bg-dark p-4 rounded-lg border border-grok-border flex-grow-0 flex-shrink-0 max-h-[150px] overflow-y-auto">
                        <div className="flex items-center text-grok-text-medium text-xs uppercase font-bold tracking-wider mb-2"><Terminal size={12} className="mr-2" /> Mining Logs</div>
                        <div className="font-mono text-[10px] text-grok-text-medium">
                            {logs.map((log, index) => (
                                <div key={index}>{log}</div>
                            ))}
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
};

