import React, { useEffect, useState, useRef } from 'react';
import { Layers, Zap, Dna, Terminal, CheckCircle2, MessageSquare, Grid, Database, Brain, Trophy, Sprout, Cpu, ShieldCheck, Languages, HeartHandshake, Scale, ArrowRight, Binary, GitMerge, UserCog, RefreshCw, Atom, Lock, Microscope, Share2, Sparkles } from 'lucide-react';
import { Point, SimulationMode, InteractionMode, ModelArchitecture, ModelParadigm } from '../types';

interface LiveSimulationProps {
  mode: SimulationMode;
  topic: string;
  interactionMode?: InteractionMode;
  architecture?: ModelArchitecture;
  paradigm?: ModelParadigm;
  isTraining?: boolean;
}

const AGENT_STAGES = [
    { id: 'TEXT', label: '1. TEXT VEC', icon: Languages },
    { id: 'DIFF', label: '2. DIFFUSION', icon: RefreshCw },
    { id: 'QUBIT', label: '3. QUBIT ENT', icon: Atom },
    { id: 'RGF', label: '4. RGF FLTR', icon: Layers },
    { id: 'DATA', label: '5. DATA SYNTH', icon: Database },
    { id: 'LOCK', label: '6. AGI LOCK', icon: Lock }
];

const NANO_STAGES = [
    { id: 'P-OPT', label: '1. PROMPT OPT', icon: Sparkles }, // New
    { id: 'D-GEN', label: '2. DIFF-GEN', icon: Database },
    { id: 'NANO', label: '3. NANO-LLM', icon: Cpu },
    { id: 'GATE', label: '4. LOGIC GATE', icon: ShieldCheck },
    { id: 'OPT', label: '5. RECURSIVE', icon: RefreshCw },
    { id: 'DEPLOY', label: '6. LOCAL RUN', icon: Zap }
];

export const LiveSimulation: React.FC<LiveSimulationProps> = ({ mode, topic, interactionMode, architecture, paradigm, isTraining }) => {
  const [particles, setParticles] = useState<Point[]>([]);
  const [logs, setLogs] = useState<string[]>([]);
  const [stage, setStage] = useState(0);

  const STAGES = interactionMode === InteractionMode.NANO_GRID ? NANO_STAGES : AGENT_STAGES;

  useEffect(() => {
      const initialPoints = Array.from({ length: 60 }).map((_, i) => ({
          x: Math.random() * 100,
          y: Math.random() * 100,
          id: `p-${i}`,
          vx: (Math.random() - 0.5) * 0.8,
          vy: (Math.random() - 0.5) * 0.8
      }));
      setParticles(initialPoints);
      setStage(0);
  }, [topic, interactionMode]);

  useEffect(() => {
      const interval = setInterval(() => {
          setStage(prev => (prev + 1) % STAGES.length);
          const currentStage = STAGES[stage];

          let logMsg = `[KERNEL] ${currentStage.id} :: ${currentStage.label}`;
          if (interactionMode === InteractionMode.NANO_GRID) {
             if (currentStage.id === 'P-OPT') logMsg = `[PROMPT] Synthesizing optimal system instruction...`;
             if (currentStage.id === 'D-GEN') logMsg = `[DIFFUSION] Generating verified dataset with SHA-256 grounding...`;
             if (currentStage.id === 'GATE') logMsg = `[LOGIC] Verifying results via Science-Based Entropy Check...`;
             if (currentStage.id === 'OPT') logMsg = `[RECURSIVE] Updating Nano-Weights based on Logic reward...`;
          }

          setLogs(prev => [logMsg, ...prev].slice(0, 5));

          setParticles(prev => prev.map(p => ({
              ...p,
              x: Math.max(0, Math.min(100, p.x + (Math.random()-0.5)*3)),
              y: Math.max(0, Math.min(100, p.y + (Math.random()-0.5)*3))
          })));

      }, 450); 
      return () => clearInterval(interval);
  }, [stage, topic, interactionMode]);

  return (
    <div className="h-64 md:h-96 w-full bg-grok-bg-medium rounded-xl overflow-hidden relative border border-grok-border-primary shadow-inner flex flex-col">
       <div className="absolute top-0 left-0 w-full p-4 z-10 flex justify-between items-start pointer-events-none">
           <div>
               <div className="flex items-center space-x-2">
                   <Terminal size={16} className="text-grok-accent-status" />
                   <span className="text-xs font-mono font-bold text-grok-text-light uppercase tracking-widest">
                       {interactionMode === InteractionMode.NANO_GRID ? 'NANO-BOT FORGE v1.2' : 'GENESIS-PRIME v16.0'}
                   </span>
               </div>
               <div className="mt-1 text-[10px] text-grok-text-medium font-mono">
                   ARCH: {architecture} | RECURSIVE: ENABLED
               </div>
           </div>

           <div className={`bg-grok-bg-light/80 px-2 py-1 rounded text-[10px] font-mono border flex items-center gap-2 ${
               STAGES[stage]?.id === 'DEPLOY' ? 'text-grok-accent-status border-grok-accent-status/50 bg-grok-accent-status/20' : 
               STAGES[stage]?.id === 'GATE' ? 'text-grok-accent-warning border-grok-accent-warning/30' :
               STAGES[stage]?.id === 'P-OPT' ? 'text-grok-accent-highlight border-grok-accent-highlight/30' :
               'text-grok-text-light border-grok-border-primary/30'
           }`}>
               <span className={`w-1.5 h-1.5 rounded-full animate-pulse ${
                   STAGES[stage]?.id === 'DEPLOY' ? 'bg-grok-accent-status' : 'bg-grok-text-light'
               }`}></span>
               {STAGES[stage]?.label}
           </div>
       </div>

       <div className="flex-1 relative opacity-50">
           {particles.map((p) => (
               <div 
                   key={p.id}
                   className={`absolute rounded-full transition-all duration-300 ${
                       interactionMode === InteractionMode.NANO_GRID ? 
                        (STAGES[stage]?.id === 'P-OPT' ? 'bg-grok-accent-highlight shadow-[0_0_8px_var(--grok-accent-highlight)]' : 
                         STAGES[stage]?.id === 'GATE' ? 'bg-grok-accent-warning shadow-[0_0_5px_var(--grok-accent-warning)]' : 'bg-grok-accent-primary') 
                       : 
                        'bg-grok-text-medium'
                   }`}
                   style={{ left: `${p.x}%`, top: `${p.y}%`, width: '2px', height: '2px' }}
               />
           ))}
           {interactionMode === InteractionMode.NANO_GRID && (
               <div className="absolute top-1/2 left-1/2 transform -translate-x-1/2 -translate-y-1/2 w-32 h-32 border border-grok-accent-primary/20 rounded-full flex items-center justify-center animate-pulse">
                   <div className="w-24 h-24 border border-grok-accent-primary/30 rounded-full flex items-center justify-center animate-spin-slow">
                        <Cpu size={24} className="text-grok-accent-primary opacity-50" />
                   </div>
               </div>
           )}
       </div>

       <div className="h-8 bg-grok-bg-light border-t border-grok-border-primary flex items-center px-4 gap-2 overflow-x-auto justify-between">
            {STAGES.map((s, i) => (
                <div key={s.id} className={`flex items-center text-[9px] font-mono whitespace-nowrap ${i === stage ? 'text-grok-accent-status font-bold' : 'text-grok-text-dark'}`}>
                    {i > 0 && <ArrowRight size={10} className="mx-1 opacity-50" />}
                    <span>{s.id}</span>
                </div>
            ))}
       </div>

       <div className="h-20 bg-grok-bg-dark border-t border-grok-border-primary p-2 font-mono text-[10px] text-grok-text-medium overflow-hidden flex flex-col justify-end">
            {logs.map((log, i) => (
                <div key={i} className="truncate opacity-80 border-l-2 border-grok-border-primary pl-2 mb-1">
                    <span className="text-grok-accent-status/80 mr-2">$</span>
                    {log}
                </div>
            ))}
       </div>
    </div>
  );
};

import React, { useEffect, useRef, useState } from 'react';
import { Cpu, User, Sparkles, Send, ShieldCheck, RefreshCw, Activity, Terminal, AlertTriangle, ChevronRight, Zap, Target, Search, Copy, Check, ExternalLink, Database } from 'lucide-react';
import ReactMarkdown from 'react-markdown';
import { ChatMessage, WebSource } from '../types';

interface ChatInterfaceProps {
  history: ChatMessage[];
  isLoading: boolean;
  onSendMessage: (text: string) => void;
}

const DenoisingToken: React.FC<{ content: string; isLast: boolean; isLoading: boolean }> = ({ content, isLast, isLoading }) => {
    const [isStabilized, setIsStabilized] = useState(!isLast);

    useEffect(() => {
        if (isLast && isLoading) {
            const timer = setTimeout(() => setIsStabilized(true), 150);
            return () => clearTimeout(timer);
        }
    }, [content, isLast, isLoading]);

    return (
        <span className={`${!isStabilized ? 'animate-pulse blur-[1px] text-grok-accent-primary brightness-150' : 'transition-all duration-300'}`}>
            {content}
        </span>
    );
};

export const ChatInterface: React.FC<ChatInterfaceProps> = ({ history, isLoading, onSendMessage }) => {
    const [input, setInput] = useState('');
    const [denoisingScore, setDenoisingScore] = useState(1.0);
    const [mctsNodes, setMctsNodes] = useState(0);
    const [showBacktrack, setShowBacktrack] = useState(false);
    const [copiedIndex, setCopiedIndex] = useState<number | null>(null);
    const endOfMessagesRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        endOfMessagesRef.current?.scrollIntoView({ behavior: 'smooth' });
    }, [history, isLoading]);

    // Simulate ASI Search Depth
    useEffect(() => {
        let interval: number;
        if (isLoading) {
            interval = window.setInterval(() => {
                setDenoisingScore(0.998 + Math.random() * 0.002);
                setMctsNodes(prev => prev + Math.floor(Math.random() * 5));
                if (Math.random() > 0.95) {
                    setShowBacktrack(true);
                    setTimeout(() => setShowBacktrack(false), 800);
                }
            }, 300);
        } else {
            setDenoisingScore(1.0);
            setMctsNodes(0);
        }
        return () => clearInterval(interval);
    }, [isLoading]);

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        if (input.trim() && !isLoading) {
            onSendMessage(input);
            setInput('');
        }
    };

    const handleCopy = (text: string, index: number) => {
        navigator.clipboard.writeText(text).then(() => {
            setCopiedIndex(index);
            setTimeout(() => setCopiedIndex(null), 2000);
        });
    };

    return (
        <div className="flex flex-col h-full bg-grok-bg-medium rounded-xl border border-grok-border-primary shadow-2xl overflow-hidden font-sans text-grok-text-light w-full animate-in fade-in">
            {/* Header */}
            <div className="flex items-center justify-between p-4 border-b border-grok-border-primary bg-grok-bg-light">
                <div className="flex items-center">
                    <Terminal size={18} className="text-grok-accent-primary" />
                    <h2 className="ml-3 font-bold text-sm text-grok-text-light tracking-wider uppercase">
                        ASI GROUNDING CONSOLE v5.0 <span className="text-[10px] text-grok-accent-primary/50 ml-2 opacity-80">OMEGA_READY</span>
                    </h2>
                </div>
                <div className="flex items-center gap-3">
                    {isLoading && (
                        <div className="flex items-center gap-2 text-[9px] font-bold text-grok-accent-primary bg-grok-accent-primary/20 px-2 py-1 rounded border border-grok-accent-primary/30">
                            <Search size={10} /> MCTS_SEARCH: {mctsNodes} NODES
                        </div>
                    )}
                    {showBacktrack && (
                        <div className="flex items-center gap-1 text-[9px] font-bold text-grok-accent-error bg-grok-accent-error-bg px-2 py-1 rounded border border-grok-border-primary animate-bounce">
                            <AlertTriangle size={10} /> LOGIC_PRUNE
                        </div>
                    )}
                    <div className={`flex items-center gap-2 text-[10px] font-bold px-3 py-1 rounded border transition-all ${isLoading ? 'text-grok-accent-primary bg-grok-accent-primary/20 border-grok-accent-primary/30 animate-pulse' : 'text-grok-text-medium bg-grok-bg-light/20 border-grok-border-primary'}`}>
                        <Target size={12} />
                        SNR: {isLoading ? (47 + Math.random()).toFixed(2) : "48.00"} dB
                    </div>
                </div>
            </div>

            {/* Messages */}
            <div className="flex-1 overflow-y-auto p-4 md:p-6 space-y-8 scroll-smooth relative">
                {history.length === 0 && (
                    <div className="flex flex-col items-center justify-center h-full text-grok-text-medium opacity-50 space-y-4">
                        <div className="relative">
                            <Zap size={48} className="text-grok-accent-primary animate-pulse" />
                            <Target size={20} className="absolute -top-2 -right-2 text-grok-accent-primary/80" />
                        </div>
                        <div className="text-center">
                            <p className="text-xs uppercase tracking-[0.3em] font-bold text-grok-accent-primary">ASI Search Loop ACTIVE</p>
                            <p className="text-[9px] mt-2 italic">Awaiting high-entropy reasoning task...</p>
                        </div>
                    </div>
                )}
                {history.map((message, index) => (
                    <div key={index} className={`flex items-start gap-4 ${message.role === 'user' ? 'justify-end' : 'justify-start'} group/message`}>
                       {message.role === 'model' && (
                           <div className="w-9 h-9 flex-shrink-0 rounded-lg bg-grok-bg-light flex items-center justify-center border border-grok-border-primary shadow-lg relative">
                               <Sparkles size={18} className="text-grok-accent-primary" />
                               <div className="absolute -top-1 -right-1 w-3 h-3 bg-grok-accent-primary rounded-full border-2 border-grok-bg-medium" />
                           </div>
                       )}

                        <div className={`flex flex-col gap-2 max-w-[90%] lg:max-w-[80%]`}>
                            <div className={`p-4 rounded-2xl prose prose-invert prose-sm leading-7 shadow-xl relative ${
                                message.role === 'user' 
                                ? 'bg-grok-user-chat-bg text-grok-text-light border border-grok-user-chat-bg/30 rounded-tr-none' 
                                : `bg-grok-model-chat-bg border border-grok-border-primary rounded-tl-none`
                            }`}>
                                <ReactMarkdown 
                                    components={{ 
                                        p: ({node, children, ...props}) => (
                                            <p className="m-0" {...props}>
                                                {React.Children.map(children, (child, i) => (
                                                    <DenoisingToken 
                                                        key={i} 
                                                        content={typeof child === 'string' ? child : ''} 
                                                        isLast={index === history.length - 1} 
                                                        isLoading={isLoading} 
                                                    />
                                                ))}
                                            </p>
                                        )
                                    }}
                                >
                                    {message.content}
                                </ReactMarkdown>
                                {message.role === 'model' && isLoading && index === history.length - 1 && (
                                    <span className="inline-block w-1.5 h-4 bg-grok-accent-primary ml-1 animate-pulse" />
                                )}

                                {/* Floating Copy Button */}
                                <button
                                    onClick={() => handleCopy(message.content, index)}
                                    className={`absolute top-2 right-2 p-1.5 rounded-lg transition-all opacity-0 group-hover/message:opacity-100 backdrop-blur-sm ${
                                        message.role === 'user' 
                                        ? 'bg-grok-user-chat-bg/30 hover:bg-grok-user-chat-bg/50 text-grok-text-light' 
                                        : 'bg-grok-bg-dark/50 hover:bg-grok-bg-light/50 text-grok-text-medium hover:text-grok-text-light'
                                    }`}
                                    title="Copy to clipboard"
                                >
                                    {copiedIndex === index ? <Check size={14} className="text-grok-accent-status" /> : <Copy size={14} />}
                                </button>
