interface LiveSimulationProps {
  mode: SimulationMode;
  topic: string;
  interactionMode?: InteractionMode;
  architecture?: ModelArchitecture;
  paradigm?: ModelParadigm;
  isTraining?: boolean;
}

const AGENT_STAGES = [
    { id: 'TEXT', label: '1. TEXT VEC', icon: Languages },
    { id: 'DIFF', label: '2. DIFFUSION', icon: RefreshCw },
    { id: 'QUBIT', label: '3. QUBIT ENT', icon: Atom },
    { id: 'RGF', label: '4. RGF FLTR', icon: Layers },
    { id: 'DATA', label: '5. DATA SYNTH', icon: Database },
    { id: 'LOCK', label: '6. AGI LOCK', icon: Lock }
];

const NANO_STAGES = [
    { id: 'P-OPT', label: '1. PROMPT OPT', icon: Sparkles }, // New
    { id: 'D-GEN', label: '2. DIFF-GEN', icon: Database },
    { id: 'NANO', label: '3. NANO-LLM', icon: Cpu },
    { id: 'GATE', label: '4. LOGIC GATE', icon: ShieldCheck },
    { id: 'OPT', label: '5. RECURSIVE', icon: RefreshCw },
    { id: 'DEPLOY', label: '6. LOCAL RUN', icon: Zap }
];

export const LiveSimulation: React.FC<LiveSimulationProps> = ({ mode, topic, interactionMode, architecture, paradigm, isTraining }) => {
  const [particles, setParticles] = useState<Point[]>([]);
  const [logs, setLogs] = useState<string[]>([]);
  const [stage, setStage] = useState(0);

  const STAGES = interactionMode === InteractionMode.NANO_GRID ? NANO_STAGES : AGENT_STAGES;

  useEffect(() => {
      const initialPoints = Array.from({ length: 60 }).map((_, i) => ({
          x: Math.random() * 100,
          y: Math.random() * 100,
          id: `p-${i}`,
          vx: (Math.random() - 0.5) * 0.8,
          vy: (Math.random() - 0.5) * 0.8
      }));
      setParticles(initialPoints);
      setStage(0);
  }, [topic, interactionMode]);

  useEffect(() => {
      const interval = setInterval(() => {
          setStage(prev => (prev + 1) % STAGES.length);
          const currentStage = STAGES[stage];

          let logMsg = `[KERNEL] ${currentStage.id} :: ${currentStage.label}`;
          if (interactionMode === InteractionMode.NANO_GRID) {
             if (currentStage.id === 'P-OPT') logMsg = `[PROMPT] Synthesizing optimal system instruction...`;
             if (currentStage.id === 'D-GEN') logMsg = `[DIFFUSION] Generating verified dataset with SHA-256 grounding...`;
             if (currentStage.id === 'GATE') logMsg = `[LOGIC] Verifying results via Science-Based Entropy Check...`;
             if (currentStage.id === 'OPT') logMsg = `[RECURSIVE] Updating Nano-Weights based on Logic reward...`;
          }

          setLogs(prev => [logMsg, ...prev].slice(0, 5));

          setParticles(prev => prev.map(p => ({
              ...p,
              x: Math.max(0, Math.min(100, p.x + (Math.random()-0.5)*3)),
              y: Math.max(0, Math.min(100, p.y + (Math.random()-0.5)*3))
          })));

      }, 450); 
      return () => clearInterval(interval);
  }, [stage, topic, interactionMode]);

  return (
    <div className="h-64 md:h-96 w-full bg-grok-bg-dark rounded-xl overflow-hidden relative border border-grok-border-primary shadow-inner flex flex-col">
       <div className="absolute top-0 left-0 w-full p-4 z-10 flex justify-between items-start pointer-events-none">
           <div>
               <div className="flex items-center space-x-2">
                   <Terminal size={16} className="text-grok-accent-status" />
                   <span className="text-xs font-mono font-bold text-grok-text-light uppercase tracking-widest">
                       {interactionMode === InteractionMode.NANO_GRID ? 'NANO-BOT FORGE v1.2' : 'GENESIS-PRIME v16.0'}
                   </span>
               </div>
               <div className="mt-1 text-[10px] text-grok-text-medium font-mono">
                   ARCH: {architecture} | RECURSIVE: ENABLED
               </div>
           </div>

           <div className={`bg-grok-bg-medium/80 px-2 py-1 rounded text-[10px] font-mono border flex items-center gap-2 ${
               STAGES[stage]?.id === 'DEPLOY' ? 'text-grok-accent-primary border-grok-border-secondary/50 bg-grok-bg-medium/30' : 
               STAGES[stage]?.id === 'GATE' ? 'text-grok-accent-warning border-grok-border-secondary/30 bg-grok-bg-medium/30' :
               STAGES[stage]?.id === 'P-OPT' ? 'text-grok-accent-highlight border-grok-border-secondary/30 bg-grok-bg-medium/30' :
               'text-grok-text-light border-grok-border-secondary/30 bg-grok-bg-medium/30'
           }`}>
               <span className={`w-1.5 h-1.5 rounded-full animate-pulse ${
                   STAGES[stage]?.id === 'DEPLOY' ? 'bg-grok-accent-status' : 'bg-grok-text-light'
               }`}></span>
               {STAGES[stage]?.label}
           </div>
       </div>

       <div className="flex-1 relative opacity-50">
           {particles.map((p) => (
               <div 
                   key={p.id}
                   className={`absolute rounded-full transition-all duration-300 ${
                       interactionMode === InteractionMode.NANO_GRID ? 
                        (STAGES[stage]?.id === 'P-OPT' ? 'bg-grok-accent-highlight shadow-[0_0_8px_#E0E0E0]' : // Hardcoded white shadow
                         STAGES[stage]?.id === 'GATE' ? 'bg-grok-accent-warning shadow-[0_0_5px_#A0A0A0]' : // Hardcoded light gray shadow
                         'bg-grok-accent-primary shadow-[0_0_8px_#FFFFFF]') // Hardcoded white shadow
                       : 
                        'bg-grok-text-medium'
                   }`}
                   style={{ left: `${p.x}%`, top: `${p.y}%`, width: '2px', height: '2px' }}
               />
           ))}
           {interactionMode === InteractionMode.NANO_GRID && (
               <div className="absolute top-1/2 left-1/2 transform -translate-x-1/2 -translate-y-1/2 w-32 h-32 border border-grok-accent-primary/20 rounded-full flex items-center justify-center animate-pulse">
                   <div className="w-24 h-24 border border-grok-accent-primary/30 rounded-full flex items-center justify-center animate-spin-slow">
                        <Cpu size={24} className="text-grok-accent-primary opacity-50" />
                   </div>
               </div>
           )}
       </div>

       <div className="h-8 bg-grok-bg-dark border-t border-grok-border-primary flex items-center px-4 gap-2 overflow-x-auto justify-between">
            {STAGES.map((s, i) => (
                <div key={s.id} className={`flex items-center text-[9px] font-mono whitespace-nowrap ${i === stage ? 'text-grok-accent-primary font-bold' : 'text-grok-text-dark'}`}>
                    {i > 0 && <ArrowRight size={10} className="mx-1 opacity-50" />}
                    <span>{s.id}</span>
                </div>
            ))}
       </div>

       <div className="h-20 bg-grok-bg-dark border-t border-grok-border-primary p-2 font-mono text-[10px] text-grok-text-medium overflow-hidden flex flex-col justify-end">
            {logs.map((log, i) => (
                <div key={i} className="truncate opacity-80 border-l-2 border-grok-border-secondary pl-2 mb-1">
                    <span className="text-grok-accent-primary/80 mr-2">$</span>
                    {log}
                </div>
            ))}
       </div>
    </div>
  );
};

