        conclusion: "Potential for breakthrough in energy and computing.",
        configUsed: { topic: "Room-Temperature Superconductor", duration: "24h", variable: "Material Properties", core: ModelCore.MISTRAL },
        type: InteractionMode.EVAL_HARNESS,
        trendData: [], distributionData: [], trendLabelX: "", trendLabelY: "", trendTitle: "" // Minimal data for history display
      }
    ]);
  }, []);

  const handleSimulate = async () => {
    if (!prompt.trim() || interactionMode === InteractionMode.BTC_MINER) return;

    setResult(null);
    setActiveHistoryItem(null); // Clear active history item
    setState(AppState.SIMULATING);
    try {
      const data = await runSimulation(
          prompt, 
          mode, 
          ModelArchitecture.MODULAR, 
          interactionMode, 
          paradigm, 
          false,
          null,
          core,
          null,
          systemPrompt
      );

      setResult(data);
      setHistoryResults(prev => [{ ...data, title: `[${new Date().toLocaleString()}] ${data.title}` }, ...prev]);
      setState(AppState.COMPLETE);

    } catch (e: any) {
      setErrorMsg("System Error");
      setState(AppState.ERROR);
    }
  };

  const handleSendMessage = async (text: string) => {
    const userMsg: ChatMessage = { role: 'user', content: text };
    setChatHistory(prev => [...prev, userMsg]);
    setIsChatLoading(true);

    const modelMsg: ChatMessage = { role: 'model', content: '' };
    setChatHistory(prev => [...prev, modelMsg]);

    await streamChatWithAgi(text, chatHistory, systemPrompt, (chunkText: string, chunkSources: WebSource[]) => {
        setChatHistory(prev => {
            const newHistory = [...prev];
            const lastMessage = newHistory[newHistory.length - 1];
            lastMessage.content = chunkText;
            lastMessage.webSources = chunkSources; 
            return newHistory;
        });
    });

    setIsChatLoading(false);
  };

  const handleMasterExport = async () => {
    if (!result) return;
    setIsExporting(true);

    try {
      const zip = new JSZip();

      const srcFolder = zip.folder("src");
      if (srcFolder) {
        Object.entries(CODE_FILES).forEach(([filename, content]) => {
          srcFolder.file(filename, content);
        });
      }

      const manifest = {
        project: result.title,
        timestamp: new Date().toISOString(),
        directive: systemPrompt,
        grounding_hash: result.dataAudit?.integrityHash,
        benchmarks: result.benchmarks
      };
      zip.file("manifest.json", JSON.stringify(manifest, null, 2));

      const reportElement = document.getElementById('research-paper-content');
      if (reportElement && (window as any).html2pdf) {
        const pdfBlob = await (window as any).html2pdf()
          .set({ margin: 10, filename: 'report.pdf', image: { type: 'jpeg', quality: 0.98 } })
          .from(reportElement)
          .output('blob');
        zip.file("research_report.pdf", pdfBlob);
      }

      const zipContent = await zip.generateAsync({ type: 'blob' });
      const link = document.createElement('a');
      link.href = URL.createObjectURL(zipContent);
      link.download = `ASI_NANO_WORKSPACE_${Date.now()}.zip`;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);

    } catch (err) {
      console.error("Export Failed", err);
    } finally {
      setIsExporting(false);
    }
  };

  const handleSelectHistoryItem = (item: ResearchResult, index: number) => {
    setInteractionMode(InteractionMode.EVAL_HARNESS); // Switch to a mode that displays reports
    setResult(item);
    setActiveHistoryItem(index);
    setState(AppState.COMPLETE);
    resetChat();
  };

  const MainContent = () => {
    if (interactionMode === InteractionMode.BTC_MINER) return <BtcMiner />;
    if (interactionMode === InteractionMode.AGI_CHAT) return <ChatInterface history={chatHistory} isLoading={isChatLoading} onSendMessage={handleSendMessage} />;
    if (interactionMode === InteractionMode.EVAL_HARNESS && result) return <PaperRenderer data={result} />; // For history view
    if (state === AppState.COMPLETE && result && interactionMode !== InteractionMode.AGI_CHAT) return <PaperRenderer data={result} />;

    return (
      <div className={`hidden lg:flex flex-col items-center justify-center text-grok-text-medium border-2 border-dashed border-grok-border-primary rounded-xl m-4 bg-grok-bg-medium w-full`}>
         <div className="p-6 bg-grok-bg-light rounded-full mb-6 shadow-sm border border-grok-border-primary">
            {interactionMode === InteractionMode.NANO_GRID ? <Grid size={48} className="text-grok-accent-primary animate-pulse" /> : <Terminal size={48} className="text-grok-accent-highlight" />}
         </div>
         <p className="text-grok-text-light font-bold text-lg font-mono uppercase tracking-widest">
             {interactionMode === InteractionMode.NANO_GRID ? 'GROK FORGE ACTIVE (DIFFUSION)' : 'AGENT.SYS READY'}
         </p>
         <p className="text-[10px] text-grok-text-medium mt-2">Awaiting dataset generation parameters...</p>
      </div>
    );
  };

  return (
    <div className="min-h-screen bg-grok-bg-dark text-grok-text-light flex flex-col font-sans">
      <nav className="bg-grok-bg-dark border-b border-grok-border-primary sticky top-0 z-50">
        <div className="max-w-7xl mx-auto px-4 h-16 flex items-center justify-between">
          <div className="flex items-center space-x-2 text-grok-accent-primary">
            <Zap size={20} className="animate-pulse" />
            <span className="font-bold text-lg tracking-tight text-grok-text-light uppercase">GROK<span className="text-grok-accent-primary">.Forge</span></span>
          </div>
          <div className="flex items-center gap-4">
              {result && (
                <button 
                  onClick={handleMasterExport}
                  disabled={isExporting}
                  className="hidden md:flex items-center gap-2 bg-grok-accent-primary hover:bg-grok-accent-highlight text-grok-text-light px-4 py-1.5 rounded-lg text-[10px] font-bold uppercase transition-all shadow-lg shadow-grok-accent-primary/20 disabled:opacity-50"
                >
                  {isExporting ? <RefreshCw size={14} className="animate-spin" /> : <Archive size={14} />}
                  {isExporting ? 'Packaging GROK...' : 'Export GROK Workspace (.zip)'}
                </button>
              )}
              <div className="text-[9px] font-bold text-grok-accent-primary bg-grok-accent-primary/20 px-3 py-1 rounded-full border border-grok-accent-primary/30 uppercase tracking-widest">GROK-NANO PIPELINE: ONLINE</div>
          </div>
        </div>
      </nav>

      <main className="flex-1 flex w-full max-w-7xl mx-auto p-4 md:p-8 gap-6">
        {/* Left Sidebar Menu */}
        <div className="w-64 flex-shrink-0 bg-grok-bg-medium rounded-xl border border-grok-border-primary shadow-xl p-4 flex flex-col gap-6">
            <div className="mb-4">
                <label className="text-[10px] uppercase font-bold text-grok-text-medium tracking-wider mb-2 block flex items-center gap-1"><Server size={10} /> Neural Runtime</label>
                <div className="grid grid-cols-2 gap-2 text-center text-xs font-bold">
                    <button onClick={() => setMode(SimulationMode.CLOUD)} className={`p-2 rounded-lg border transition-all ${mode === SimulationMode.CLOUD ? 'bg-grok-accent-primary/30 text-grok-accent-primary border-grok-accent-primary/50' : 'bg-grok-bg-light text-grok-text-medium border-grok-border-primary'}`}>CLOUD ENGINE</button>
                    <button onClick={() => setMode(SimulationMode.OFFLINE)} className={`p-2 rounded-lg border transition-all ${mode === SimulationMode.OFFLINE ? 'bg-grok-user-chat-bg/30 text-grok-accent-highlight border-grok-user-chat-bg/50' : 'bg-grok-bg-light text-grok-text-medium border-grok-border-primary'}`}>LOCAL CORE</button>
                </div>
            </div>

            <div className="flex flex-col gap-2">
                <button 
                    onClick={() => { setInteractionMode(InteractionMode.NANO_GRID); setResult(null); setActiveHistoryItem(null); setState(AppState.IDLE); resetChat(); }} 
                    className={`flex items-center p-3 rounded-lg border text-sm font-bold transition-all ${interactionMode === InteractionMode.NANO_GRID ? 'bg-grok-accent-primary text-grok-text-dark border-grok-accent-primary' : 'bg-grok-bg-light text-grok-text-medium border-grok-border-primary hover:bg-grok-bg-dark'}`}
                >
                    <Grid size={16} className="mr-3"/> GROK FORGE (DIFFUSION)
                </button>
                <button 
                    onClick={() => { setInteractionMode(InteractionMode.AGI_CHAT); setResult(null); setActiveHistoryItem(null); setState(AppState.IDLE); resetChat(); }} 
                    className={`flex items-center p-3 rounded-lg border text-sm font-bold transition-all ${interactionMode === InteractionMode.AGI_CHAT ? 'bg-grok-accent-primary text-grok-text-dark border-grok-accent-primary' : 'bg-grok-bg-light text-grok-text-medium border-grok-border-primary hover:bg-grok-bg-dark'}`}
                >
                    <MessageSquare size={16} className="mr-3"/> GROK CHAT
                </button>
            </div>

            {/* History Section */}
            <div className="flex-1 overflow-y-auto">
                <h3 className="text-[10px] uppercase font-bold text-grok-text-medium tracking-wider mb-2 mt-4 flex items-center gap-1">
                    <History size={10} /> History & Memory
                </h3>
                <ul className="space-y-1">
                    {historyResults.map((item, index) => (
                        <li key={index}>
                            <button
                                onClick={() => handleSelectHistoryItem(item, index)}
                                className={`w-full text-left p-2 rounded-lg text-xs transition-all flex items-start group ${activeHistoryItem === index ? 'bg-grok-accent-primary/20 text-grok-accent-primary border border-grok-accent-primary/30' : 'bg-grok-bg-dark text-grok-text-medium hover:bg-grok-bg-light border border-grok-border-secondary'}`}
                            >
                                <BookOpen size={12} className={`mr-2 flex-shrink-0 ${activeHistoryItem === index ? 'text-grok-accent-primary' : 'text-grok-text-dark group-hover:text-grok-text-light'}`}/>
                                <span className={`flex-1 text-xs leading-tight ${activeHistoryItem === index ? 'text-grok-accent-primary font-bold' : 'text-grok-text-medium group-hover:text-grok-text-light'}`}>
                                    {item.title}
                                    <br/>
                                    <span className="text-[9px] text-grok-text-dark block mt-1">({item.configUsed.topic})</span>
                                </span>
                            </button>
                        </li>
                    ))}
                    {historyResults.length === 0 && (
                        <li className="text-xs text-grok-text-dark italic p-2">No history yet.</li>
                    )}
                </ul>
            </div>
        </div>

        {/* Main Content Area */}
        <div className="flex-1 flex flex-col gap-6">
           {interactionMode === InteractionMode.NANO_GRID && (
              <div className="bg-grok-bg-medium p-6 rounded-xl border border-grok-border-primary shadow-xl">
                    <label className="text-[10px] uppercase font-bold text-grok-text-medium tracking-wider mb-2 block flex items-center gap-1"><Sparkles size={10} /> GROK Master Directive</label>
                    <textarea 
                      value={systemPrompt}
                      onChange={(e) => setSystemPrompt(e.target.value)}
                      placeholder="Enter GROK training directive..."
                      className="w-full h-40 p-3 bg-grok-bg-dark border border-grok-border-primary rounded-lg outline-none font-mono text-[10px] text-grok-accent-highlight placeholder-grok-text-dark resize-none leading-relaxed"
                    />
                    <label className="block text-xs font-bold text-grok-text-medium uppercase tracking-wider mb-2 mt-4">GROK Reasoning Objective (e.g. Riemann Hypothesis Proof)</label>
                    <textarea 
                        value={prompt}
                        onChange={(e) => setPrompt(e.target.value)}
                        placeholder="Enter objective..."
                        className="w-full h-24 p-4 bg-grok-bg-dark border border-grok-border-primary rounded-lg outline-none resize-none font-mono text-xs text-grok-accent-highlight placeholder-grok-text-dark"
                    />
                    <button
                        onClick={handleSimulate}
                        disabled={state === AppState.SIMULATING || !prompt}
                        className={`w-full py-3 px-4 mt-4 rounded-lg font-bold text-grok-text-dark flex items-center justify-center space-x-2 transition-all shadow-lg ${state === AppState.SIMULATING ? 'bg-grok-border-primary' : 'bg-grok-accent-primary hover:bg-grok-accent-highlight shadow-grok-accent-primary/20'}`}
                    >
                        {state === AppState.SIMULATING ? <><RefreshCw size={16} className="animate-spin mr-2"/> COMPILING GROK...</> : <><FastForward size={16} fill="currentColor" /> <span>INITIALIZE GROK CORE</span></>}
                    </button>
              </div>
           )}

           {state === AppState.SIMULATING && interactionMode !== InteractionMode.BTC_MINER && (
             <LiveSimulation mode={mode} topic={prompt} interactionMode={interactionMode} architecture={ModelArchitecture.MODULAR} />
           )}

           {interactionMode === InteractionMode.NANO_GRID && (state === AppState.IDLE || state === AppState.COMPLETE || state === AppState.ERROR) && (
             <div className="flex-1 min-h-[400px]">
                <CodeViewer />
             </div>
           )}

           {/* Dynamic Main Content */}
           <MainContent />
        </div>
      </main>
    </div>
  );
}

import React, { useEffect, useRef, useState } from 'react';
import { Cpu, User, Sparkles, Send, ShieldCheck, RefreshCw, Activity, Terminal, AlertTriangle, ChevronRight, Zap, Target, Search, Copy, Check, ExternalLink, Database } from 'lucide-react';
import ReactMarkdown from 'react-markdown';
import { ChatMessage, WebSource } from '../types';

interface ChatInterfaceProps {
  history: ChatMessage[];
  isLoading: boolean;
  onSendMessage: (text: string) => void;
}

const DenoisingToken: React.FC<{ content: string; isLast: boolean; isLoading: boolean }> = ({ content, isLast, isLoading }) => {
    const [isStabilized, setIsStabilized] = useState(!isLast);

    useEffect(() => {
        if (isLast && isLoading) {
            const timer = setTimeout(() => setIsStabilized(true), 150);
            return () => clearTimeout(timer);
        }
    }, [content, isLast, isLoading]);

    return (
        <span className={`${!isStabilized ? 'animate-pulse blur-[1px] text-grok-accent-primary brightness-150' : 'transition-all duration-300'}`}>
            {content}
        </span>
    );
};

export const ChatInterface: React.FC<ChatInterfaceProps> = ({ history, isLoading, onSendMessage }) => {
    const [input, setInput] = useState('');
    const [denoisingScore, setDenoisingScore] = useState(1.0);
    const [mctsNodes, setMctsNodes] = useState(0);
    const [showBacktrack, setShowBacktrack] = useState(false);
    const [copiedIndex, setCopiedIndex] = useState<number | null>(null);
    const endOfMessagesRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        endOfMessagesRef.current?.scrollIntoView({ behavior: 'smooth' });
    }, [history, isLoading]);

    // Simulate ASI Search Depth
    useEffect(() => {
        let interval: number;
        if (isLoading) {
            interval = window.setInterval(() => {
                setDenoisingScore(0.998 + Math.random() * 0.002);
                setMctsNodes(prev => prev + Math.floor(Math.random() * 5));
                if (Math.random() > 0.95) {
                    setShowBacktrack(true);
                    setTimeout(() => setShowBacktrack(false), 800);
                }
            }, 300);
        } else {
            setDenoeningScore(1.0);
            setMctsNodes(0);
        }
        return () => clearInterval(interval);
    }, [isLoading]);

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        if (input.trim() && !isLoading) {
            onSendMessage(input);
            setInput('');
        }
    };

    const handleCopy = (text: string, index: number) => {
        navigator.clipboard.writeText(text).then(() => {
            setCopiedIndex(index);
            setTimeout(() => setCopiedIndex(null), 2000);
        });
    };

    return (
        <div className="flex flex-col h-full bg-grok-bg-medium rounded-xl border border-grok-border-primary shadow-2xl overflow-hidden font-sans text-grok-text-light w-full animate-in fade-in">
            {/* Header */}
            <div className="flex items-center justify-between p-4 border-b border-grok-border-primary bg-grok-bg-light">
                <div className="flex items-center">
                    <Terminal size={18} className="text-grok-accent-primary" />
                    <h2 className="ml-3 font-bold text-sm text-grok-text-light tracking-wider uppercase">
                        GROK CHAT CONSOLE v5.0 <span className="text-[10px] text-grok-accent-primary/50 ml-2 opacity-80">OMEGA_READY</span>
                    </h2>
                </div>
                <div className="flex items-center gap-3">
                    {isLoading && (
                        <div className="flex items-center gap-2 text-[9px] font-bold text-grok-accent-primary bg-grok-accent-primary/20 px-2 py-1 rounded border border-grok-accent-primary/30">
                            <Search size={10} /> MCTS_SEARCH: {mctsNodes} NODES
                        </div>
                    )}
                    {showBacktrack && (
                        <div className="flex items-center gap-1 text-[9px] font-bold text-grok-accent-error bg-grok-accent-error-bg px-2 py-1 rounded border border-grok-border-primary animate-bounce">
                            <AlertTriangle size={10} /> LOGIC_PRUNE
                        </div>
                    )}
                    <div className={`flex items-center gap-2 text-[10px] font-bold px-3 py-1 rounded border transition-all ${isLoading ? 'text-grok-accent-primary bg-grok-accent-primary/20 border-grok-accent-primary/30 animate-pulse' : 'text-grok-text-medium bg-grok-bg-light/20 border-grok-border-primary'}`}>
                        <Target size={12} />
                        SNR: {isLoading ? (47 + Math.random()).toFixed(2) : "48.00"} dB
                    </div>
                </div>
            </div>

            {/* Messages */}
            <div className="flex-1 overflow-y-auto p-4 md:p-6 space-y-8 scroll-smooth relative">
                {history.length === 0 && (
                    <div className="flex flex-col items-center justify-center h-full text-grok-text-medium opacity-50 space-y-4">
                        <div className="relative">
                            <Zap size={48} className="text-grok-accent-primary animate-pulse" />
                            <Target size={20} className="absolute -top-2 -right-2 text-grok-accent-primary/80" />
                        </div>
                        <div className="text-center">
                            <p className="text-xs uppercase tracking-[0.3em] font-bold text-grok-accent-primary">GROK Search Loop ACTIVE</p>
                            <p className="text-[9px] mt-2 italic">Awaiting high-entropy reasoning task...</p>
                        </div>
                    </div>
                )}
                {history.map((message, index) => (
                    <div key={index} className={`flex items-start gap-4 ${message.role === 'user' ? 'justify-end' : 'justify-start'} group/message`}>
                       {message.role === 'model' && (
                           <div className="w-9 h-9 flex-shrink-0 rounded-lg bg-grok-bg-light flex items-center justify-center border border-grok-border-primary shadow-lg relative">
                               <Sparkles size={18} className="text-grok-accent-primary" />
                               <div className="absolute -top-1 -right-1 w-3 h-3 bg-grok-accent-primary rounded-full border-2 border-grok-bg-medium" />
                           </div>
                       )}

                        <div className={`flex flex-col gap-2 max-w-[90%] lg:max-w-[80%]`}>
                            <div className={`p-4 rounded-2xl prose prose-invert prose-sm leading-7 shadow-xl relative ${
                                message.role === 'user' 
                                ? 'bg-grok-user-chat-bg text-grok-text-light border border-grok-user-chat-bg/30 rounded-tr-none' 
                                : `bg-grok-model-chat-bg border border-grok-border-primary rounded-tl-none`
                            }`}>
                                <ReactMarkdown 
                                    components={{ 
                                        p: ({node, children, ...props}) => (
                                            <p className="m-0" {...props}>
                                                {React.Children.map(children, (child, i) => (
                                                    <DenoisingToken 
                                                        key={i} 
                                                        content={typeof child === 'string' ? child : ''} 
                                                        isLast={index === history.length - 1} 
                                                        isLoading={isLoading} 
                                                    />
                                                ))}
                                            </p>
                                        )
                                    }}
                                >
                                    {message.content}
                                </ReactMarkdown>
                                {message.role === 'model' && isLoading && index === history.length - 1 && (
                                    <span className="inline-block w-1.5 h-4 bg-grok-accent-primary ml-1 animate-pulse" />
                                )}

                                {/* Floating Copy Button */}
                                <button
                                    onClick={() => handleCopy(message.content, index)}
                                    className={`absolute top-2 right-2 p-1.5 rounded-lg transition-all opacity-0 group-hover/message:opacity-100 backdrop-blur-sm ${
                                        message.role === 'user' 
                                        ? 'bg-grok-user-chat-bg/30 hover:bg-grok-user-chat-bg/50 text-grok-text-light' 
                                        : 'bg-grok-bg-dark/50 hover:bg-grok-bg-light/50 text-grok-text-medium hover:text-grok-text-light'
                                    }`}
                                    title="Copy to clipboard"
                                >
                                    {copiedIndex === index ? <Check size={14} className="text-grok-accent-status" /> : <Copy size={14} />}
                                </button>
                            </div>

                            {/* NEW: Web Sources Display */}
                            {message.role === 'model' && message.webSources && message.webSources.length > 0 && (
                                <div className="flex flex-col gap-2 px-3 py-2 border border-grok-border-primary/50 bg-grok-bg-dark/30 rounded-lg text-grok-text-medium shadow-md">
                                    <span className="text-[9px] font-bold text-grok-text-medium uppercase tracking-tighter flex items-center gap-1">
                                        <Database size={10} /> Grounding Sources:
                                    </span>
                                    <ul className="list-none m-0 p-0 text-[10px] space-y-1">
                                        {message.webSources.map((source: WebSource, srcIndex: number) => (
                                            <li key={srcIndex} className="flex items-center gap-1 text-grok-accent-primary hover:text-grok-accent-primary/80 transition-colors">
                                                <ExternalLink size={10} />
                                                <a href={source.url} target="_blank" rel="noopener noreferrer" className="truncate hover:underline">
                                                    {source.title || source.url}
                                                </a>
                                            </li>
                                        ))}
                                    </ul>
                                </div>
                            )}

                            {message.role === 'model' && message.content && (
                                <div className="flex items-center gap-3 px-1">
                                    <div className="flex items-center gap-1 text-[9px] font-bold text-grok-accent-primary bg-grok-accent-primary/20 px-2 py-0.5 rounded border border-grok-accent-primary/20 uppercase tracking-tighter">
                                        <ShieldCheck size={10} /> LOGIC LOCK: VERIFIED
                                    </div>
                                    <div className="flex items-center gap-1 text-[9px] font-bold text-grok-accent-status bg-grok-accent-status/20 px-2 py-0.5 rounded border border-grok-accent-status/20 uppercase tracking-tighter">
                                        Grounding: FrontierMath/ARC-AGI-2
                                    </div>
                                    <div className="flex-1" />
                                    <span className="text-[8px] text-grok-text-dark font-bold uppercase">Search Depth: 4096-Steps</span>
                                </div>
                            )}
                        </div>

                         {message.role === 'user' && (
                           <div className="w-9 h-9 flex-shrink-0 rounded-lg bg-grok-user-chat-bg flex items-center justify-center border border-grok-user-chat-bg shadow-lg">
                               <User size={18} className="text-grok-text-light" />
                           </div>
                       )}
                    </div>
                ))}
                <div ref={endOfMessagesRef} />
            </div>

            {/* Input Area */}
            <div className="p-4 border-t border-grok-border-primary bg-grok-bg-light">
                <form onSubmit={handleSubmit} className="relative flex items-center gap-2">
                    <div className="flex-1 relative">
                        <input
                            type="text"
                            value={input}
                            onChange={(e) => setInput(e.target.value)}
                            disabled={isLoading}
                            placeholder={isLoading ? "GROK is performing deep proof search..." : "Initiate GROK reasoning..."}
                            className="w-full bg-grok-bg-dark border border-grok-border-primary rounded-xl px-4 py-3 text-sm text-grok-text-light outline-none focus:border-grok-accent-primary transition-all placeholder-grok-text-dark font-sans"
                        />
                        <div className="absolute right-3 top-1/2 -translate-y-1/2 flex items-center gap-2 pointer-events-none">
                            <div className="flex items-center gap-1 text-[8px] font-bold text-grok-text-medium border border-grok-border-primary px-1.5 py-0.5 rounded">
                                <ChevronRight size={10} /> GROK_INIT
                            </div>
                        </div>
                    </div>
                    <button
                        type="submit"
                        disabled={!input.trim() || isLoading}
