           <div className={`bg-grok-bg-medium/80 px-2 py-1 rounded text-[10px] font-mono border flex items-center gap-2 ${
               currentStages[currentStageIndex]?.id === 'DEPLOY' ? 'text-grok-accent-primary border-grok-border-secondary/50 bg-grok-bg-medium/30' : 
