// Helper to determine if a model is a cloud model
const isCloudModel = (core: ModelCore, mode: SimulationMode) => {
    return mode === SimulationMode.CLOUD || core === ModelCore.GENESIS_PRO || core === ModelCore.LLAMA_3 || core === ModelCore.MISTRAL;
}

export const runSimulation = async (topic: string, mode: SimulationMode, architecture: ModelArchitecture, interactionMode: InteractionMode, paradigm: ModelParadigm, isTraining: boolean, trainedModel: TrainedModel | null = null, core: ModelCore = ModelCore.GENESIS_PRO, history: ChatMessage[] | null = null, systemPrompt?: string): Promise<ResearchResult> => {
    if (mode === SimulationMode.OFFLINE || !isCloudModel(core, mode)) {
        const system = new RealAgentSystem(topic, interactionMode, core, systemPrompt);
        return new Promise(resolve => setTimeout(() => resolve(system.run()), 1200));
    }

    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const modelName = core === ModelCore.GENESIS_PRO ? 'gemini-3-pro-preview' : 'gemini-3-flash-preview'; // Use appropriate Gemini model

    try {
        const response = await ai.models.generateContent({
            model: modelName,
            contents: `TASK: Based on the GR0K Master Directive and objective "${topic}", generate a comprehensive ResearchResult JSON.
                       Your response MUST strictly adhere to the GR0K protocol: HYPOTHESIS -> FORMAL PROOF -> DENOISING & OUTPUT.
                       Crucially, utilize 'googleSearch' when information beyond your training data is required (e.g., current technologies, market analysis, novel materials).
                       For any information sourced via 'googleSearch', extract 'title' and 'uri' from the grounding metadata (groundingChunks) and include them as 'WebSource' objects in the 'webSources' array within the ResearchResult JSON.
                       Ensure 'benchmarks' reflect superintelligent SNR (>45dB) and that all sections (abstract, methodology, resultsAnalysis, conclusion) are scientifically rigorous and aligned with GR0K principles (Kolmogorov Complexity, Neuro-Symbolic, MCTS).`,
            config: { 
                responseMimeType: "application/json",
                temperature: 0.1,
                tools: [{googleSearch: {}}], // Added for runSimulation
            }
        });

        const json = JSON.parse(response.text);
        const runner = new RealAgentSystem(topic, interactionMode, core, systemPrompt); // For fallback data
        const ref = runner.run();

        // Also extract grounding chunks for the main simulation result if available
        const webSources: WebSource[] = [];
        if (response.candidates?.[0]?.groundingMetadata?.groundingChunks) {
            for (const gc of response.candidates[0].groundingMetadata.groundingChunks) {
                if (gc.web && gc.web.uri && gc.web.title) {
                    webSources.push({ title: gc.web.title, url: gc.web.uri });
                }
            }
        }

        return {
            ...json,
            benchmarks: json.benchmarks || ref.benchmarks,
            dataAudit: json.dataAudit || ref.dataAudit,
            configUsed: { topic, duration: 'GR0K Cloud Core', variable: 'Logic SNR', core, systemPrompt },
            webSources: json.webSources || webSources, // Merge or use extracted web sources
        };
    } catch (e: any) {
        console.error("Gemini API simulation failed:", e);
        if (e.status === 429 || e.error?.code === 429) {
            throw {
                isQuotaError: true,
                message: e.error?.message || "You exceeded your current quota. Please check your plan and billing details.",
            };
        }
        // Fallback to offline simulation for other errors
        const system = new RealAgentSystem(topic, interactionMode, core, systemPrompt);
        return system.run();
    }
};

