import React, { useEffect, useRef, useState } from 'react';
import { Cpu, User, Sparkles, Send, ShieldCheck, RefreshCw, Activity, Terminal, AlertTriangle, ChevronRight, Zap, Target, Search, Copy, Check, ExternalLink, Database } from 'lucide-react';
import ReactMarkdown from 'react-markdown';
import { ChatMessage, WebSource } from '../types';

interface ChatInterfaceProps {
  history: ChatMessage[];
  isLoading: boolean;
  onSendMessage: (text: string) => void;
}

const DenoisingToken: React.FC<{ content: string; isLast: boolean; isLoading: boolean }> = ({ content, isLast, isLoading }) => {
    const [isStabilized, setIsStabilized] = useState(!isLast);

    useEffect(() => {
        // Trigger stabilization after a short delay for the last chunk when loading is active
        if (isLast && isLoading) {
            const timer = setTimeout(() => setIsStabilized(true), 150); // Small delay to show initial "blur"
            return () => clearTimeout(timer);
        } else if (!isLoading) {
             setIsStabilized(true); // Ensure all previous tokens are stabilized when loading stops
        }
    }, [content, isLast, isLoading]);

    return (
        <span className={`${!isStabilized ? 'blur-[1px] text-grok-accent-primary brightness-150' : 'transition-all duration-300'}`}>
            {content}
        </span>
    );
};

export const ChatInterface: React.FC<ChatInterfaceProps> = ({ history, isLoading, onSendMessage }) => {
    const [input, setInput] = useState('');
    const [denoisingScore, setDenoisingScore] = useState(1.0);
    const [mctsNodes, setMctsNodes] = useState(0);
    const [showBacktrack, setShowBacktrack] = useState(false);
    const [copiedIndex, setCopiedIndex] = useState<number | null>(null);
    const endOfMessagesRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        endOfMessagesRef.current?.scrollIntoView({ behavior: 'smooth' });
    }, [history, isLoading]);

    // Simulate GR0K Search Depth
    useEffect(() => {
        let interval: number;
        if (isLoading) {
            interval = window.setInterval(() => {
                setDenoisingScore(0.998 + Math.random() * 0.002);
                setMctsNodes(prev => prev + Math.floor(Math.random() * 5));
                if (Math.random() > 0.95) {
                    setShowBacktrack(true);
                    setTimeout(() => setShowBacktrack(false), 800);
                }
            }, 300);
        } else {
            setDenoisingScore(1.0);
            setMctsNodes(0);
        }
        return () => clearInterval(interval);
    }, [isLoading]);

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        if (input.trim() && !isLoading) {
            onSendMessage(input);
            setInput('');
        }
    };

    const handleCopy = (text: string, index: number) => {
        navigator.clipboard.writeText(text).then(() => {
            setCopiedIndex(index);
            setTimeout(() => setCopiedIndex(null), 2000);
        });
    };

    return (
        <div className="flex flex-col h-full bg-grok-bg-medium rounded-xl border border-grok-border-primary shadow-2xl overflow-hidden font-sans text-grok-text-light w-full animate-in fade-in">
            {/* Header */}
            <div className="flex items-center justify-between p-4 border-b border-grok-border-primary bg-grok-bg-light">
                <div className="flex items-center">
                    <Terminal size={18} className="text-grok-accent-primary" />
                    <h2 className="ml-3 font-bold text-sm text-grok-text-light tracking-wider uppercase">
                        GROK CHAT CONSOLE v5.0 <span className="text-[10px] text-grok-accent-primary/50 ml-2 opacity-80">OMEGA_READY</span>
                    </h2>
                </div>
                <div className="flex items-center gap-3">
                    {isLoading && (
                        <div className="flex items-center gap-2 text-[9px] font-bold text-grok-accent-primary bg-grok-accent-primary/20 px-2 py-1 rounded border border-grok-accent-primary/30">
                            <Search size={10} /> MCTS_SEARCH: {mctsNodes} NODES
                        </div>
                    )}
                    {showBacktrack && (
                        <div className="flex items-center gap-1 text-[9px] font-bold text-grok-accent-error bg-grok-accent-error-bg px-2 py-1 rounded border border-grok-border-primary animate-bounce">
                            <AlertTriangle size={10} /> LOGIC_PRUNE
                        </div>
                    )}
                    <div className={`flex items-center gap-2 text-[10px] font-bold px-3 py-1 rounded border transition-all ${isLoading ? 'text-grok-accent-primary bg-grok-accent-primary/20 border-grok-accent-primary/30 animate-pulse' : 'text-grok-text-medium bg-grok-bg-light/20 border-grok-border-primary'}`}>
                        <Target size={12} />
                        SNR: {isLoading ? (47 + Math.random()).toFixed(2) : "48.00"} dB
                    </div>
                </div>
            </div>

            {/* Messages */}
            <div className="flex-1 overflow-y-auto p-4 md:p-6 space-y-8 scroll-smooth relative">
                {history.length === 0 && (
                    <div className="flex flex-col items-center justify-center h-full text-grok-text-medium opacity-50 space-y-4">
                        <div className="relative">
                            <Zap size={48} className="text-grok-accent-primary animate-pulse" />
                            <Target size={20} className="absolute -top-2 -right-2 text-grok-accent-primary/80" />
                        </div>
                        <div className="text-center">
                            <p className="text-xs uppercase tracking-[0.3em] font-bold text-grok-accent-primary">GROK Search Loop ACTIVE</p>
                            <p className="text-[9px] mt-2 italic">Awaiting high-entropy reasoning task...</p>
                        </div>
                    </div>
                )}
                {history.map((message, index) => (
                    <div key={index} className={`flex items-start gap-4 ${message.role === 'user' ? 'justify-end' : 'justify-start'} group/message`}>
                       {message.role === 'model' && (
                           <div className="w-9 h-9 flex-shrink-0 rounded-lg bg-grok-bg-light flex items-center justify-center border border-grok-border-primary shadow-lg relative">
                               <Sparkles size={18} className="text-grok-accent-primary" />
                               <div className="absolute -top-1 -right-1 w-3 h-3 bg-grok-accent-primary rounded-full border-2 border-grok-bg-medium" />
                           </div>
                       )}

                        <div className={`flex flex-col gap-2 max-w-[90%] lg:max-w-[80%]`}>
                            <div className={`p-4 rounded-2xl prose prose-invert prose-sm leading-7 shadow-xl relative ${
                                message.role === 'user' 
                                ? 'bg-grok-user-chat-bg text-grok-text-light border border-grok-user-chat-bg/30 rounded-tr-none' 
                                : `bg-grok-model-chat-bg border border-grok-border-primary rounded-tl-none`
                            }`}>
                                <ReactMarkdown 
                                    components={{ 
                                        p: ({node, children, ...props}) => (
                                            <p className="m-0" {...props}>
                                                {React.Children.map(children, (child, i) => (
                                                    <DenoisingToken 
                                                        key={i} 
                                                        content={typeof child === 'string' ? child : ''} 
                                                        isLast={index === history.length - 1} 
                                                        isLoading={isLoading} 
                                                    />
                                                ))}
                                            </p>
                                        )
                                    }}
                                >
                                    {message.content}
                                </ReactMarkdown>
                                {message.role === 'model' && isLoading && index === history.length - 1 && (
                                    <span className="inline-block w-1.5 h-4 bg-grok-accent-primary ml-1 animate-pulse" />
                                )}

                                {/* Floating Copy Button */}
                                <button
