                                        ? 'bg-grok-user-chat-bg/30 hover:bg-grok-user-chat-bg/50 text-grok-text-light' 
                                        : 'bg-grok-bg-dark/50 hover:bg-grok-bg-light/50 text-grok-text-medium hover:text-grok-text-light'
                                    }`}
                                    title="Copy to clipboard"
                                >
                                    {copiedIndex === index ? <Check size={14} className="text-grok-accent-status" /> : <Copy size={14} />}
                                </button>
                            </div>

                            {/* NEW: Web Sources Display */}
                            {message.role === 'model' && message.webSources && message.webSources.length > 0 && (
                                <div className="flex flex-col gap-2 px-3 py-2 border border-grok-border-primary/50 bg-grok-bg-dark/30 rounded-lg text-grok-text-medium shadow-md">
                                    <span className="text-[9px] font-bold text-grok-text-medium uppercase tracking-tighter flex items-center gap-1">
                                        <Database size={10} /> Grounding Sources:
                                    </span>
                                    <ul className="list-none m-0 p-0 text-[10px] space-y-1">
                                        {message.webSources.map((source: WebSource, srcIndex: number) => (
                                            <li key={srcIndex} className="flex items-center gap-1 text-grok-accent-primary hover:text-grok-accent-primary/80 transition-colors">
                                                <ExternalLink size={10} />
                                                <a href={source.url} target="_blank" rel="noopener noreferrer" className="truncate hover:underline">
                                                    {source.title || source.url}
                                                </a>
                                            </li>
                                        ))}
                                    </ul>
                                </div>
                            )}

                            {message.role === 'model' && message.content && (
                                <div className="flex items-center gap-3 px-1">
                                    <div className="flex items-center gap-1 text-[9px] font-bold text-grok-accent-primary bg-grok-accent-primary/20 px-2 py-0.5 rounded border border-grok-accent-primary/20 uppercase tracking-tighter">
                                        <ShieldCheck size={10} /> LOGIC LOCK: VERIFIED
                                    </div>
                                    <div className="flex items-center gap-1 text-[9px] font-bold text-grok-accent-status bg-grok-accent-status/20 px-2 py-0.5 rounded border border-grok-accent-status/20 uppercase tracking-tighter">
                                        Grounding: FrontierMath/ARC-AGI-2
