                6. TONE: Maintain a clinical, precise, and superintelligent tone. Avoid conversational filler.
                7. CONCLUSIVITY: Conclude with a 'LOGIC LOCK' status and relevant SNR (Signal-to-Noise Ratio) metrics to indicate verification level.

                When a user asks to configure a multi-stage diffusion pipeline, use the 'controlPipeline' function tool. Extract the initial objective and the desired sequence of steps, including their type and the model to use for each. For example, if the user says "Set up a pipeline to refine text with Genesis Pro, then synthesize data with Ollama, and finally generate an image concept with Llama 3 8B", you should call controlPipeline with:
                initialPrompt: "Next-generation generative process",
                steps: [
                    {type: "TEXT_REFINEMENT", model: "GENESIS_PRO"},
                    {type: "DATA_SYNTHESIS", model: "OLLAMA"},
                    {type: "IMAGE_GENERATION", model: "LLAMA_3_8B"}
                ]

                Always use the available model names exactly as specified in the 'model' enum description. Prioritize setting up the pipeline if requested.

                Current selected model: ${core}.`, // Inform the model about the selected core.
                tools: [{googleSearch: {}}, {functionDeclarations: [controlPipelineFunctionDeclaration]}],
            },
        });
    }

    try {
        const result = await activeChatSession.sendMessageStream({ message });
        let fullText = "";
        let accumulatedWebSources: WebSource[] = [];

        for await (const chunk of result) {
            // Handle function calls first if present
            if (chunk.toolCall && chunk.toolCall.functionCalls) {
                onToolCall(chunk.toolCall.functionCalls);
            }

            fullText += chunk.text || ''; // Aggregate text

            // Process grounding metadata if available in the chunk
            if (chunk.groundingMetadata?.groundingChunks) {
                for (const gc of chunk.groundingMetadata.groundingChunks) {
                    if (gc.web && gc.web.uri && gc.web.title) {
                        const newSource: WebSource = {
                            title: gc.web.title,
                            url: gc.web.uri,
                            // snippet: gc.web.snippet // Can add if Gemini returns it reliably
                        };
                        // Avoid duplicates
                        if (!accumulatedWebSources.some(s => s.url === newSource.url)) {
                            accumulatedWebSources.push(newSource);
                        }
                    }
                }
            }
            onChunk(fullText, accumulatedWebSources); // Pass both text and sources
        }
    } catch (e: any) {
        console.error("GR0K Chat streaming failed:", e);
        if (e.status === 429 || e.error?.code === 429) {
            onFatalError(
                e.error?.message || "You exceeded your current quota. Please check your plan and billing details.",
                true
            );
        } else {
            onFatalError("SYSTEM ERROR: GR0K Core De-synchronization. Grounding failed.", false);
        }
    }
};


export const runDiffusionPipeline = async (
    initialPrompt: string,
    pipelineSteps: PipelineStep[],
    mode: SimulationMode,
    systemPrompt: string,
    onStepProgress: (stepIndex: number, result: ResearchResult | null) => void,
    onFatalError: (message: string, isQuotaError: boolean) => void // New callback for fatal errors
): Promise<ResearchResult | null> => {
    if (!initialPrompt || pipelineSteps.length === 0) {
        onFatalError("Pipeline not configured. Please provide an initial prompt and at least one step.", false);
        return null;
    }

    let currentInput = initialPrompt;
    const pipelineTrace: ResearchResult[] = [];

    for (let i = 0; i < pipelineSteps.length; i++) {
        const step = pipelineSteps[i];
        onStepProgress(i, null); // Indicate start of step

        try {
            let stepResult: ResearchResult;
            const stepTopic = `${currentInput} (Step ${i + 1}: ${step.type} via ${step.model})`;

            if (mode === SimulationMode.OFFLINE || !isCloudModel(step.model, mode)) {
                // Simulate local model
                const system = new RealAgentSystem(stepTopic, InteractionMode.DIFFUSION_PIPELINE, step.model, systemPrompt);
                stepResult = await new Promise(resolve => setTimeout(() => resolve(system.run(step.type)), 1500));
            } else {
                // Use cloud model
                const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
                const modelName = step.model === ModelCore.GENESIS_PRO ? 'gemini-3-pro-preview' : 'gemini-3-flash-preview';

                let promptContent = '';
                if (step.type === PipelineStepType.TEXT_REFINEMENT) {
                    promptContent = `Refine the following text for maximum clarity, logical density, and GR0K-alignment: "${currentInput}"`;
                } else if (step.type === PipelineStepType.DATA_SYNTHESIS) {
                    promptContent = `Generate a conceptual summary for synthetic data related to "${currentInput}". Include abstract, methodology, and conclusion for a research report.`;
                } else if (step.type === PipelineStepType.QUANTUM_SIMULATION) {
                    promptContent = `Simulate a high-level quantum experiment or concept related to "${currentInput}". Provide an abstract, methodology, and conclusion for a research report.`;
                } else if (step.type === PipelineStepType.IMAGE_GENERATION) {
                    promptContent = `Generate a detailed, evocative image generation prompt based on the concept: "${currentInput}". Emphasize visual style, composition, and mood for a diffusion model.`;
                } else {
                    promptContent = `Process the concept: "${currentInput}" through a generic diffusion operation. Provide a research-style output.`;
                }

                const response = await ai.models.generateContent({
                    model: modelName,
                    contents: `TASK: Based on the GR0K Master Directive and pipeline step "${step.type}" using ${step.model}, process the following: "${currentInput}".
                               Generate a comprehensive ResearchResult JSON for this step.
                               Your response MUST strictly adhere to the GR0K protocol: HYPOTHESIS -> FORMAL PROOF -> DENOISING & OUTPUT.
                               Crucially, utilize 'googleSearch' when information beyond your training data is required (e.g., current technologies, market analysis, novel materials).
                               For any information sourced via 'googleSearch', extract 'title' and 'uri' from the grounding metadata (groundingChunks) and include them as 'WebSource' objects in the 'webSources' array within the ResearchResult JSON.
                               Ensure 'benchmarks' reflect superintelligent SNR (>45dB) and that all sections (abstract, methodology, resultsAnalysis, conclusion) are scientifically rigorous and aligned with GR0K principles (Kolmogorov Complexity, Neuro-Symbolic, MCTS).
                               Specific Instruction for this step: ${promptContent}`,
                    config: {
                        responseMimeType: "application/json",
                        temperature: 0.1,
                        tools: [{ googleSearch: {} }],
                    }
                });

                const json = JSON.parse(response.text);
                const runner = new RealAgentSystem(stepTopic, InteractionMode.DIFFUSION_PIPELINE, step.model, systemPrompt);
                const ref = runner.run(step.type);

                const webSources: WebSource[] = [];
                if (response.candidates?.[0]?.groundingMetadata?.groundingChunks) {
                    for (const gc of response.candidates[0].groundingMetadata.groundingChunks) {
                        if (gc.web && gc.web.uri && gc.web.title) {
                            webSources.push({ title: gc.web.title, url: gc.web.uri });
                        }
                    }
                }

                stepResult = {
                    ...json,
                    title: `[${step.type}] ` + json.title,
                    benchmarks: json.benchmarks || ref.benchmarks,
                    dataAudit: json.dataAudit || ref.dataAudit,
                    configUsed: { topic: stepTopic, duration: 'GR0K Cloud Core', variable: 'Logic SNR', core: step.model, systemPrompt },
                    webSources: json.webSources || webSources,
                    type: InteractionMode.DIFFUSION_PIPELINE,
                };
            }

            pipelineTrace.push(stepResult);
            currentInput = stepResult.abstract + (stepResult.generatedCode ? `\nCode generated: ${stepResult.generatedCode}` : ''); // Next step input
            onStepProgress(i, stepResult); // Update UI with current step's result

        } catch (e: any) {
            console.error(`GR0K Pipeline step ${i + 1} failed:`, e);
            if (e.isQuotaError) {
                onFatalError(e.message, true);
            } else {
                onFatalError(`Pipeline step ${i + 1} (${step.type} via ${step.model}) failed: ${e.message || "Unknown error"}`, false);
            }
            return null; // Stop pipeline on error
        }
    }

    // Consolidate final result
    const finalResult: ResearchResult = {
        title: `GR0K MULTI-DIFFUSION PIPELINE REPORT (Completed)`,
        abstract: `This report summarizes the multi-stage diffusion process initiated with: "${initialPrompt}". The pipeline executed ${pipelineSteps.length} steps, progressively transforming and enriching the initial concept.`,
        methodology: `A custom GR0K diffusion pipeline was configured, dynamically chaining generative models (${pipelineSteps.map(s => s.model).join(', ')}). Each step's output served as refined input for the subsequent stage, employing recursive axiomatic verification at critical junctures.`,
        resultsAnalysis: `The aggregated results demonstrate a robust, iterative refinement capability, achieving comprehensive data synthesis and conceptual expansion.`,
        conclusion: `The GR0K Multi-Diffusion Pipeline successfully transformed the initial concept through a series of specialized generative operations, culminating in a highly dense and verifiable knowledge artifact.`,
        configUsed: { topic: initialPrompt, duration: 'Pipeline Run', variable: 'Pipeline Coherence', core: ModelCore.GENESIS_PRO, systemPrompt },
        type: InteractionMode.DIFFUSION_PIPELINE,
        pipelineTrace: pipelineTrace,
        // Aggregate some data from the last step or general
        trendData: pipelineTrace[pipelineTrace.length - 1]?.trendData || [],
        trendLabelX: pipelineTrace[pipelineTrace.length - 1]?.trendLabelX || 'Pipeline Stage',
        trendLabelY: pipelineTrace[pipelineTrace.length - 1]?.trendLabelY || 'Progress',
        trendTitle: 'Pipeline Performance Overview',
        distributionData: pipelineTrace[pipelineTrace.length - 1]?.distributionData || [],
        distributionLabel: pipelineTrace[pipelineTrace.length - 1]?.distributionLabel || 'Overall Distribution',
        distributionColor: pipelineTrace[pipelineTrace.length - 1]?.distributionColor || '#FFFFFF',
        benchmarks: pipelineTrace[pipelineTrace.length - 1]?.benchmarks, // Take last step's benchmarks for simplicity
        dataAudit: pipelineTrace[pipelineTrace.length - 1]?.dataAudit,
    };

    return finalResult;
};

import React, { useState, useEffect, useRef } from 'react';
import { Microscope, Play, Beaker, Dna, Atom, Wifi, Leaf, Cpu, Brain, Sparkles, MessageSquare, Database, Trophy, Sprout, Layers, FileText, Rocket, CheckCircle, Server, BarChart2, Terminal, WifiOff, Bitcoin, Grid, Settings, RefreshCw, Download, Archive, ShieldCheck, Zap, FastForward, History, BookOpen, XCircle, PlusCircle, Trash2, ArrowUp, ArrowDown } from 'lucide-react';
import { CodeViewer, CODE_FILES } from './components/CodeViewer';
