                                </div>
                            </div>
                        ))}
                    </div>

                    <button onClick={addPipelineStep} disabled={isPipelineRunning} className="w-full mt-4 py-2 px-4 rounded-lg font-bold text-grok-text-dark flex items-center justify-center space-x-2 bg-grok-accent-status hover:bg-grok-accent-status/80 transition-all shadow-lg shadow-grok-accent-status/20 disabled:opacity-50">
