class SeededRandom {
    private seed: number;
    constructor(seedStr: string) {
        let h = 0x811c9dc5;
        for (let i = 0; i < seedStr.length; i++) {
            h ^= seedStr.charCodeAt(i);
            h = Math.imul(h, 0x01000193);
        }
        this.seed = h >>> 0;
    }

    next(): number {
        this.seed = (this.seed * 9301 + 49297) % 233280;
        return this.seed / 233280;
    }

    range(min: number, max: number): number {
        return Math.floor(this.next() * (max - min + 1)) + min;
    }
}

const generateAgentTrace = (topic: string, rng: SeededRandom, core: ModelCore, mode: InteractionMode): AgentLog[] => {
    const trace: AgentLog[] = [];
    let t = 0;
    const ts = () => { t += rng.range(20, 150); return `+${t}ms`; };

    if (mode === InteractionMode.NANO_GRID) {
        trace.push({ step: 1, phase: 'PROMPT_OPT', content: `Injecting GR0K-Prime Master Directive (Algorithmic Priority)...`, timestamp: ts() });
        trace.push({ step: 2, phase: 'DIFFUSION', content: `Synthesizing Kolmogorov-Complex training tokens (The Stack V2 + GSM8K).`, timestamp: ts() });
        trace.push({ step: 3, phase: 'VERIFY', content: `Grounding Check: MCTS Search across proof space active.`, timestamp: ts() });
        trace.push({ step: 4, phase: 'NANO_TRAIN', content: `Neuro-Symbolic alignment: Training Differentiable Interpreters.`, timestamp: ts() });
        trace.push({ step: 5, phase: 'LOGIC_GATE', content: `Epistemic Guard: Pruning stochastic hallucinations via Symbolic Verifier.`, timestamp: ts() });
        trace.push({ step: 6, phase: 'LOGIC_GATE', content: `Logic Locked. SNR: 48.00 dB (Superintelligent Threshold).`, timestamp: ts() });
        trace.push({ step: 7, phase: 'AGI_LOCK', content: `GR0K-Nano Core Ready. Self-Evolution Loop: ACTIVE.`, timestamp: ts() });
    } else {
        trace.push({ step: 1, phase: 'INIT', content: `Initializing GR0K-FORGE Kernel...`, timestamp: ts() });
        trace.push({ step: 2, phase: 'TEXT', content: `Parsing Objective: "${topic}"...`, timestamp: ts() });
        trace.push({ step: 4, phase: 'AGI_LOCK', content: `GR0K Operation Verified. Maximum Output State.`, timestamp: ts() });
    }

    return trace;
};

