    private generateMetrics(): BenchmarkData {
        const computeEfficiency: DataPoint[] = [];
        for (let i = 0; i < 15; i++) {
            computeEfficiency.push({ label: `Cycle ${i}`, value: 92 + (8 * Math.log(i + 1)) });
        }

        let agiMetrics = {
            balancedSNR: 48.00,
            qubitUtilization: 65536,
            latencyReduction: 99.99,
            temporalCoherence: 1.0,
            arcProxyScore: 98.5,
            diffusionTokenConsumption: 12,
            vramUtilization: 95.0, // Default for cloud/high VRAM
        };

        // Adjust metrics based on VRAM allocation and core type
        if (this.core === ModelCore.OLLAMA || this.core === ModelCore.LLAMA_3_8B) {
            // Base values for local models
            let baseSNR = this.rng.range(2500, 3500) / 100;
            let baseQubit = this.rng.range(1024, 4096);
            let baseLatency = this.rng.range(50, 70);
            let baseTemporal = this.rng.range(70, 90) / 100;
            let baseArc = this.rng.range(70, 85);
            let baseDiffusionTokens = this.rng.range(50, 100);
            let baseVramUtilization = this.rng.range(6000, 8000) / 100; // 60-80%

            // Apply VRAM scaling (conceptual)
            const vramFactor = Math.log2(this.vramAllocation / 4); // Logarithmic scaling from 4GB base

            agiMetrics = {
                balancedSNR: baseSNR + (vramFactor * 2), // Improve SNR with more VRAM
                qubitUtilization: baseQubit + (vramFactor * 1024), // More qubits with more VRAM
                latencyReduction: baseLatency + (vramFactor * 5), // Better latency with more VRAM
                temporalCoherence: Math.min(1.0, baseTemporal + (vramFactor * 0.05)),
                arcProxyScore: Math.min(95, baseArc + (vramFactor * 3)),
                diffusionTokenConsumption: Math.max(10, baseDiffusionTokens - (vramFactor * 10)), // Less token consumption
                vramUtilization: Math.min(99.9, baseVramUtilization + (vramFactor * 2)), // Higher efficiency
            };
        } else {
            // Cloud models: VRAM is optimized, so utilization is high by default
            agiMetrics.vramUtilization = 95.0 + this.rng.next() * 3; // Slight variation
        }

        return {
            mmluScore: this.rng.range(800, 950) / 10,
            gsm8kScore: this.rng.range(900, 990) / 10,
            humanEval: this.rng.range(850, 980) / 10,
            coherenceScore: agiMetrics.balancedSNR,
            agiMetrics: agiMetrics,
            capabilities: [
                { subject: 'Hypothesis Proof', A: this.rng.range(70, 90), B: 10, fullMark: 100 },
                { subject: 'Symbolic Logic', A: this.rng.range(60, 85), B: 20, fullMark: 100 },
                { subject: 'Kolmogorov Comp', A: this.rng.range(65, 88), B: 30, fullMark: 100 },
                { subject: 'MCTS Depth', A: this.rng.range(75, 95), B: 5, fullMark: 100 }
            ],
            logs: generateAgentTrace(this.topic, this.rng, this.core, this.interactionMode),
            verificationHash: "0xGR0K_Simulated_" + Math.random().toString(16).substring(2, 10),
            computeEfficiency
        };
    }

