                    <label className="text-[10px] uppercase font-bold text-grok-text-medium tracking-wider mb-2 block flex items-center gap-1"><Sparkles size={10} /> GR0K Pipeline Initial Prompt</label>
                    <textarea 
                      value={pipelinePrompt}
                      onChange={(e) => setPipelinePrompt(e.target.value)}
                      placeholder="Enter the initial concept for the pipeline (e.g., 'A novel fusion energy schematic')..."
