    public async streamChatResponse(
        message: string,
        onChunk: (text: string, webSources: WebSource[]) => void,
        onFatalError: (message: string, isQuotaError: boolean) => void
    ): Promise<void> {
        const simulatedDelay = 100; // ms per chunk
        let currentContent = "";

        const respond = (chunk: string, isFinal: boolean = false) => {
            currentContent += chunk;
            const simulatedSources: WebSource[] = [];
            if (message.includes("latest news") || message.includes("current events")) {
                simulatedSources.push({ title: "Simulated News Source", url: "https://simulated.news.com" });
            }
            onChunk(currentContent, simulatedSources);
            if (isFinal) {
                let finalSNRMessage = "";
                if (this.core === ModelCore.LLAMA_3_8B) {
                    finalSNRMessage = "\n\nLOGIC LOCK: VERIFIED (Nano-Core) | SNR: 32.50 dB";
                } else if (this.core === ModelCore.OLLAMA) {
                    finalSNRMessage = "\n\nLOGIC LOCK: VERIFIED (Ollama-Core) | SNR: 28.15 dB";
                } else if (this.core === ModelCore.DEEPSEEK_NANO) {
                    finalSNRMessage = "\n\nLOGIC LOCK: VERIFIED (DeepSeek-Nano-Core) | SNR: 34.00 dB";
                }
                setTimeout(() => onChunk(currentContent + finalSNRMessage, simulatedSources), simulatedDelay);
            }
        };

        const initialThought = `GR0K Offline Core (${this.core}) is processing your query: "${message}". Initiating local reasoning sequence...\n\n`;
        const parts = [
            initialThought,
            `HYPOTHESIS: Your request can be addressed through a combination of symbolic logic and simulated data retrieval.`,
            `\n\nVERIFICATION: Executing local MCTS search (depth ${this.rng.range(100, 500)}). Synthesizing response components.`,
            `\n\nRESPONSE: `,
        ];

        for (let i = 0; i < parts.length; i++) {
            await new Promise(resolve => setTimeout(resolve, simulatedDelay * (i + 1)));
            respond(parts[i]);
        }

        const finalAnswer = `As a simulated ${this.core} instance operating in an offline environment, I've processed your request for "${message}" through a conceptual diffusion of information. The core output indicates high internal coherence with a simulated verification score. If this were a multi-diffusion pipeline, the next step would involve further refinement or data synthesis.`;
        const finalAnswerChunks = finalAnswer.split(' ');
        for (let i = 0; i < finalAnswerChunks.length; i++) {
            await new Promise(resolve => setTimeout(resolve, simulatedDelay / 2));
            respond(finalAnswerChunks[i] + (i === finalAnswerChunks.length - 1 ? '' : ' '));
        }
        respond("", true); // Send final empty chunk to trigger stabilization and final message
    }
}

// Helper to determine if a model is a cloud model
const isCloudModel = (core: ModelCore, mode: SimulationMode) => {
    return mode === SimulationMode.CLOUD || core === ModelCore.GENESIS_PRO || core === ModelCore.LLAMA_3 || core === ModelCore.MISTRAL || core === ModelCore.DEEPSEEK_PRO;
}

export const runSimulation = async (topic: string, mode: SimulationMode, architecture: ModelArchitecture, interactionMode: InteractionMode, paradigm: ModelParadigm, isTraining: boolean, trainedModel: TrainedModel | null = null, core: ModelCore = ModelCore.GENESIS_PRO, history: ChatMessage[] | null = null, systemPrompt?: string, vramAllocation: number = 16): Promise<ResearchResult> => {
    if (mode === SimulationMode.OFFLINE || !isCloudModel(core, mode)) {
        const system = new RealAgentSystem(topic, interactionMode, core, systemPrompt, vramAllocation);
        return new Promise(resolve => setTimeout(() => resolve(system.run()), 1200));
    }

    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    let modelName: string;
    if (core === ModelCore.GENESIS_PRO || core === ModelCore.DEEPSEEK_PRO) { // Map DeepSeek Pro to Gemini Pro for cloud interaction
        modelName = 'gemini-3-pro-preview';
    } else {
        modelName = 'gemini-3-flash-preview'; // Other cloud models use flash
    }

    try {
        const response = await ai.models.generateContent({
            model: modelName,
            contents: `TASK: Based on the GR0K Master Directive and objective "${topic}", generate a comprehensive ResearchResult JSON.
                       Your response MUST strictly adhere to the GR0K protocol: HYPOTHESIS -> FORMAL PROOF -> DENOISING & OUTPUT.
                       Crucially, utilize 'googleSearch' when information beyond your training data is required (e.g., current technologies, market analysis, novel materials).
                       For any information sourced via 'googleSearch', extract 'title' and 'uri' from the grounding metadata (groundingChunks) and include them as 'WebSource' objects in the 'webSources' array within the ResearchResult JSON.
                       Ensure 'benchmarks' reflect superintelligent SNR (>45dB) and that all sections (abstract, methodology, resultsAnalysis, conclusion) are scientifically rigorous and aligned with GR0K principles (Kolmogorov Complexity, Neuro-Symbolic, MCTS).`,
            config: { 
                responseMimeType: "application/json",
                temperature: 0.1,
                tools: [{googleSearch: {}}], // Added for runSimulation
            }
        });

        const json = JSON.parse(response.text);
        const runner = new RealAgentSystem(topic, interactionMode, core, systemPrompt, vramAllocation); // For fallback data
        const ref = runner.run();

        // Also extract grounding chunks for the main simulation result if available
        const webSources: WebSource[] = [];
        if (response.candidates?.[0]?.groundingMetadata?.groundingChunks) {
            for (const gc of response.candidates[0].groundingMetadata.groundingChunks) {
                if (gc.web && gc.web.uri && gc.web.title) {
                    webSources.push({ title: gc.web.title, url: gc.web.uri });
                }
            }
        }

        return {
            ...json,
            benchmarks: json.benchmarks || ref.benchmarks,
            dataAudit: json.dataAudit || ref.dataAudit,
            configUsed: { topic, duration: 'GR0K Cloud Core', variable: 'Logic SNR', core, systemPrompt, vramAllocation },
            webSources: json.webSources || webSources, // Merge or use extracted web sources
        };
    } catch (e: any) {
        console.error("Gemini API simulation failed:", e);
        if (e.status === 429 || e.error?.code === 429) {
            throw {
                isQuotaError: true,
                message: e.error?.message || "You exceeded your current quota. Please check your plan and billing details.",
            };
        }
        // Fallback to offline simulation for other errors
        const system = new RealAgentSystem(topic, interactionMode, core, systemPrompt, vramAllocation);
        return system.run();
    }
};

