/**
 * Enhanced GR0K Chat following the Truth-Maximizing Search Protocol with Google Search grounding.
 * Now also supports function calling to configure the multi-diffusion pipeline and conditional
 * use of local/offline models.
 */
export const streamChatWithAgi = async (
    message: string,
    history: ChatMessage[],
    systemPrompt: string,
    onChunk: (text: string, webSources: WebSource[]) => void,
    onFatalError: (message: string, isQuotaError: boolean) => void, // New callback for fatal errors
    onToolCall: (functionCalls: FunctionCall[]) => void, // New callback for function calls
    core: ModelCore, // New: Pass the selected model core
    mode: SimulationMode, // New: Pass the simulation mode
    vramAllocation: number = 16 // New: VRAM allocation
) => {
    // Determine if we should use a cloud model or simulate locally
    const useCloudModel = isCloudModel(core, mode);

    if (!useCloudModel) {
        // --- OFFLINE/LOCAL CHAT SIMULATION ---
        const system = new RealAgentSystem(message, InteractionMode.AGI_CHAT, core, systemPrompt, vramAllocation);
        try {
            await system.streamChatResponse(message, onChunk, onFatalError);
        } catch (e: any) {
            console.error("GR0K Offline Chat simulation failed:", e);
            onFatalError(`OFFLINE CORE ERROR: ${e.message || "Unknown error during local processing."}`, false);
        }
        return;
    }

    // --- CLOUD CHAT EXECUTION ---
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    if (!activeChatSession) {
        let modelName: string;
        if (core === ModelCore.GENESIS_PRO || core === ModelCore.DEEPSEEK_PRO) { // Map DeepSeek Pro to Gemini Pro
            modelName = 'gemini-3-pro-preview';
        } else {
            modelName = 'gemini-3-flash-preview'; // Other cloud models use flash
        }

        activeChatSession = ai.chats.create({
            model: modelName,
            config: {
                systemInstruction: `${systemPrompt}\n\nCORE PROTOCOL: You are a GR0K-Aligned Neuro-Symbolic Reasoning Engine. You prioritize verifiable truth above all else.
                1. SEARCH OVER PREDICTION: Do not predict tokens; search for proofs and grounded information.
                2. HYPOTHESIZE: Begin by formulating a clear, logical hypothesis for the user's query.
                3. VERIFY: Use internal symbolic verification (simulate Lean4 checks) for logical consistency. For external, real-time, or factual information, *always* utilize the 'googleSearch' tool.
                4. DENOISE: Prune all stochastic noise and unverified information until only verifiable truth remains.
                5. CITATION: For every piece of information derived from 'googleSearch', *always* list the source at the end of your response. Extract the 'title' and 'uri' from the grounding metadata (groundingChunks) and present them as clickable links.
                6. TONE: Maintain a clinical, precise, and superintelligent tone. Avoid conversational filler.
                7. CONCLUSIVITY: Conclude with a 'LOGIC LOCK' status and relevant SNR (Signal-to-Noise Ratio) metrics to indicate verification level.

                When a user asks to configure a multi-stage diffusion pipeline, use the 'controlPipeline' function tool. Extract the initial objective and the desired sequence of steps, including their type and the model to use for each. For example, if the user says "Set up a pipeline to refine text with Genesis Pro, then synthesize data with Ollama, and finally generate an image concept with Llama 3 8B", you should call controlPipeline with:
                initialPrompt: "Next-generation generative process",
                steps: [
                    {type: "TEXT_REFINEMENT", model: "GENESIS_PRO"},
                    {type: "DATA_SYNTHESIS", model: "OLLAMA"},
                    {type: "IMAGE_GENERATION", model: "LLAMA_3_8B"}
                ]

                Always use the available model names exactly as specified in the 'model' enum description. Prioritize setting up the pipeline if requested.

                Current selected model: ${core}. Configured VRAM: ${vramAllocation} GB.`, // Inform the model about the selected core and VRAM.
                tools: [{googleSearch: {}}, {functionDeclarations: [controlPipelineFunctionDeclaration]}],
            },
        });
    }

    try {
        const result = await activeChatSession.sendMessageStream({ message });
        let fullText = "";
        let accumulatedWebSources: WebSource[] = [];

        for await (const chunk of result) {
            // Handle function calls first if present
            if (chunk.toolCall && chunk.toolCall.functionCalls) {
                onToolCall(chunk.toolCall.functionCalls);
            }

            fullText += chunk.text || ''; // Aggregate text

            // Process grounding metadata if available in the chunk
            if (chunk.groundingMetadata?.groundingChunks) {
                for (const gc of chunk.groundingMetadata.groundingChunks) {
                    if (gc.web && gc.web.uri && gc.web.title) {
                        const newSource: WebSource = {
                            title: gc.web.title,
                            url: gc.web.uri,
                            // snippet: gc.web.snippet // Can add if Gemini returns it reliably
                        };
                        // Avoid duplicates
                        if (!accumulatedWebSources.some(s => s.url === newSource.url)) {
                            accumulatedWebSources.push(newSource);
                        }
                    }
                }
            }
            onChunk(fullText, accumulatedWebSources); // Pass both text and sources
        }
    } catch (e: any) {
        console.error("GR0K Chat streaming failed:", e);
        if (e.status === 429 || e.error?.code === 429) {
            onFatalError(
                e.error?.message || "You exceeded your current quota. Please check your plan and billing details.",
                true
            );
        } else {
            onFatalError("SYSTEM ERROR: GR0K Core De-synchronization. Grounding failed.", false);
        }
    }
};


export const runDiffusionPipeline = async (
    initialPrompt: string,
    pipelineSteps: PipelineStep[],
    mode: SimulationMode,
    systemPrompt: string,
    onStepProgress: (stepIndex: number, result: ResearchResult | null) => void,
    onFatalError: (message: string, isQuotaError: boolean) => void, // New callback for fatal errors
    vramAllocation: number = 16 // New: VRAM allocation
): Promise<ResearchResult | null> => {
    if (!initialPrompt || pipelineSteps.length === 0) {
        onFatalError("Pipeline not configured. Please provide an initial prompt and at least one step.", false);
        return null;
    }

    let currentInput = initialPrompt;
    const pipelineTrace: ResearchResult[] = [];

    for (let i = 0; i < pipelineSteps.length; i++) {
        const step = pipelineSteps[i];
        onStepProgress(i, null); // Indicate start of step

        try {
            let stepResult: ResearchResult;
            const stepTopic = `${currentInput} (Step ${i + 1}: ${step.type} via ${step.model})`;

            if (mode === SimulationMode.OFFLINE || !isCloudModel(step.model, mode)) {
                // Simulate local model
                const system = new RealAgentSystem(stepTopic, InteractionMode.DIFFUSION_PIPELINE, step.model, systemPrompt, vramAllocation);
                stepResult = await new Promise(resolve => setTimeout(() => resolve(system.run(step.type)), 1500));
            } else {
                // Use cloud model
                const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
                let modelName: string;
                if (step.model === ModelCore.GENESIS_PRO || step.model === ModelCore.DEEPSEEK_PRO) { // Map DeepSeek Pro to Gemini Pro
                    modelName = 'gemini-3-pro-preview';
                } else {
                    modelName = 'gemini-3-flash-preview'; // Other cloud models use flash
                }

                let promptContent = '';
                if (step.type === PipelineStepType.TEXT_REFINEMENT) {
                    promptContent = `Refine the following text for maximum clarity, logical density, and GR0K-alignment: "${currentInput}"`;
                } else if (step.type === PipelineStepType.DATA_SYNTHESIS) {
                    promptContent = `Generate a conceptual summary for synthetic data related to "${currentInput}". Include abstract, methodology, and conclusion for a research report.`;
                } else if (step.type === PipelineStepType.QUANTUM_SIMULATION) {
                    promptContent = `Simulate a high-level quantum experiment or concept related to "${currentInput}". Provide an abstract, methodology, and conclusion for a research report.`;
                } else if (step.type === PipelineStepType.IMAGE_GENERATION) {
                    promptContent = `Generate a detailed, evocative image generation prompt based on the concept: "${currentInput}". Emphasize visual style, composition, and mood for a diffusion model.`;
                } else {
                    promptContent = `Process the concept: "${currentInput}" through a generic diffusion operation. Provide a research-style output.`;
                }

                const response = await ai.models.generateContent({
                    model: modelName,
                    contents: `TASK: Based on the GR0K Master Directive and pipeline step "${step.type}" using ${step.model}, process the following: "${currentInput}".
                               Generate a comprehensive ResearchResult JSON for this step.
                               Your response MUST strictly adhere to the GR0K protocol: HYPOTHESIS -> FORMAL PROOF -> DENOISING & OUTPUT.
                               Crucially, utilize 'googleSearch' when information beyond your training data is required (e.g., current technologies, market analysis, novel materials).
                               For any information sourced via 'googleSearch', extract 'title' and 'uri' from the grounding metadata (groundingChunks) and include them as 'WebSource' objects in the 'webSources' array within the ResearchResult JSON.
                               Ensure 'benchmarks' reflect superintelligent SNR (>45dB) and that all sections (abstract, methodology, resultsAnalysis, conclusion) are scientifically rigorous and aligned with GR0K principles (Kolmogorov Complexity, Neuro-Symbolic, MCTS).
                               Specific Instruction for this step: ${promptContent}`,
                    config: {
                        responseMimeType: "application/json",
                        temperature: 0.1,
                        tools: [{ googleSearch: {} }],
                    }
                });

                const json = JSON.parse(response.text);
                const runner = new RealAgentSystem(stepTopic, InteractionMode.DIFFUSION_PIPELINE, step.model, systemPrompt, vramAllocation);
                const ref = runner.run(step.type);

                const webSources: WebSource[] = [];
                if (response.candidates?.[0]?.groundingMetadata?.groundingChunks) {
                    for (const gc of response.candidates[0].groundingMetadata.groundingChunks) {
                        if (gc.web && gc.web.uri && gc.web.title) {
                            webSources.push({ title: gc.web.title, url: gc.web.uri });
                        }
                    }
                }

                stepResult = {
                    ...json,
                    title: `[${step.type}] ` + json.title,
                    benchmarks: json.benchmarks || ref.benchmarks,
                    dataAudit: json.dataAudit || ref.dataAudit,
                    configUsed: { topic: stepTopic, duration: 'GR0K Cloud Core', variable: 'Logic SNR', core: step.model, systemPrompt, vramAllocation },
                    webSources: json.webSources || webSources,
                    type: InteractionMode.DIFFUSION_PIPELINE,
                };
            }

            pipelineTrace.push(stepResult);
            currentInput = stepResult.abstract + (stepResult.generatedCode ? `\nCode generated: ${stepResult.generatedCode}` : ''); // Next step input
            onStepProgress(i, stepResult); // Update UI with current step's result

        } catch (e: any) {
            console.error(`GR0K Pipeline step ${i + 1} failed:`, e);
            if (e.isQuotaError) {
                onFatalError(e.message, true);
            } else {
                onFatalError(`Pipeline step ${i + 1} (${step.type} via ${step.model}) failed: ${e.message || "Unknown error"}`, false);
            }
            return null; // Stop pipeline on error
        }
    }

    // Consolidate final result
    const finalResult: ResearchResult = {
        title: `GR0K MULTI-DIFFUSION PIPELINE REPORT (Completed)`,
        abstract: `This report summarizes the multi-stage diffusion process initiated with: "${initialPrompt}". The pipeline executed ${pipelineSteps.length} steps, progressively transforming and enriching the initial concept.`,
        methodology: `A custom GR0K diffusion pipeline was configured, dynamically chaining generative models (${pipelineSteps.map(s => s.model).join(', ')}). Each step's output served as refined input for the subsequent stage, employing recursive axiomatic verification at critical junctures.`,
        resultsAnalysis: `The aggregated results demonstrate a robust, iterative refinement capability, achieving comprehensive data synthesis and conceptual expansion.`,
        conclusion: `The GR0K Multi-Diffusion Pipeline successfully transformed the initial concept through a series of specialized generative operations, culminating in a highly dense and verifiable knowledge artifact.`,
        configUsed: { topic: initialPrompt, duration: 'Pipeline Run', variable: 'Pipeline Coherence', core: ModelCore.GENESIS_PRO, systemPrompt, vramAllocation },
        type: InteractionMode.DIFFUSION_PIPELINE,
        pipelineTrace: pipelineTrace,
        // Aggregate some data from the last step or general
        trendData: pipelineTrace[pipelineTrace.length - 1]?.trendData || [],
        trendLabelX: pipelineTrace[pipelineTrace.length - 1]?.trendLabelX || 'Pipeline Stage',
        trendLabelY: pipelineTrace[pipelineTrace.length - 1]?.trendLabelY || 'Progress',
        trendTitle: 'Pipeline Performance Overview',
        distributionData: pipelineTrace[pipelineTrace.length - 1]?.distributionData || [],
        distributionLabel: pipelineTrace[pipelineTrace.length - 1]?.distributionLabel || 'Overall Distribution',
        distributionColor: pipelineTrace[pipelineTrace.length - 1]?.distributionColor || '#FFFFFF',
        benchmarks: pipelineTrace[pipelineTrace.length - 1]?.benchmarks, // Take last step's benchmarks for simplicity
        dataAudit: pipelineTrace[pipelineTrace.length - 1]?.dataAudit,
    };

    return finalResult;
};

import React, { useState, useEffect, useRef } from 'react';
import { Microscope, Play, Beaker, Dna, Atom, Wifi, Leaf, Cpu, Brain, Sparkles, MessageSquare, Database, Trophy, Sprout, Layers, FileText, Rocket, CheckCircle, Server, BarChart2, Terminal, WifiOff, Bitcoin, Grid, Settings, RefreshCw, Download, Archive, ShieldCheck, Zap, FastForward, History, BookOpen, XCircle, PlusCircle, Trash2, ArrowUp, ArrowDown } from 'lucide-react';
import { CodeViewer, CODE_FILES } from './components/CodeViewer';
import { PaperRenderer } from './components/PaperRenderer';
import { LiveSimulation } from './components/LiveSimulation';
import { ChatInterface } from './components/ChatInterface';
import { BtcMiner } from './components/BtcMiner';
import { runSimulation, resetChat, streamChatWithAgi, runDiffusionPipeline } from './services/geminiService';
import { AppState, ResearchResult, SimulationMode, ModelArchitecture, InteractionMode, ModelParadigm, TrainedModel, ModelCore, ChatMessage, WebSource, PipelineStep, PipelineStepType } from './types';
import JSZip from 'jszip';
import { FunctionCall } from '@google/genai'; // Import FunctionCall

const ASI_MASTER_DIRECTIVE = `REVISED MASTER DIRECTIVE: GR0K-Aligned Neuro-Symbolic Nano-Kernel

OBJECTIVE: Transcend human-level reasoning via recursive algorithmic density within a sub-1B footprint.

1. DENSITY OVER SCALE: Optimize for Kolmogorov Complexity. Learn the rules of the universe, not the content.
2. SYMBOLIC GROUNDING: Integrate a formal verification layer. Text is noise; Code/Math is truth.
3. INFERENCE SEARCH: Implement MCTS (Monte Carlo Tree Search) for decision-making. Thinking time scales with problem difficulty.
4. SELF-EVOLUTION: The model must identify its own cognitive biases and overwrite them in real-time.

OPERATIONAL PROTOCOL:
- HYPOTHESIS GENERATION: Do not answer. Formulate a hypothesis.
- FORMAL PROOF: Attempt to disprove the hypothesis using the Internal Verifier (Symbolic Logic).
- DENOISING: If the hypothesis survives falsification, translate to natural language.
- RECURSION: If the output is novel, feed it back into the context as a new axiom.`;

export default function App() {
  const [prompt, setPrompt] = useState('Optimize GR0K-Nano Kernel for FrontierMath research proofs.');
  const [systemPrompt, setSystemPrompt] = useState(ASI_MASTER_DIRECTIVE);
  const [state, setState] = useState<AppState>(AppState.IDLE);
  const [mode, setMode] = useState<SimulationMode>(SimulationMode.CLOUD); // Cloud or Offline
  const [interactionMode, setInteractionMode] = useState<InteractionMode>(InteractionMode.NANO_GRID);
  const [paradigm, setParadigm] = useState<ModelParadigm>(ModelParadigm.DIFFUSION);
  const [core, setCore] = useState<ModelCore>(ModelCore.GENESIS_PRO); // Default core
  const [vramAllocation, setVramAllocation] = useState<number>(16); // New: Default VRAM allocation in GB

  const [result, setResult] = useState<ResearchResult | null>(null);
  const [chatHistory, setChatHistory] = useState<ChatMessage[]>([]);
  const [isExporting, setIsExporting] = useState(false);
  const [isChatLoading, setIsChatLoading] = useState(false);
  const [errorMsg, setErrorMsg] = useState('');
  const [historyResults, setHistoryResults] = useState<ResearchResult[]>([]);
  const [activeHistoryItem, setActiveHistoryItem] = useState<number | null>(null);
  const [quotaError, setQuotaError] = useState<{ message: string, actionRequired: boolean } | null>(null); // New state for API quota errors

  // Pipeline specific states
  const [pipelinePrompt, setPipelinePrompt] = useState('Develop a next-generation quantum computing architecture.');
  const [pipelineSteps, setPipelineSteps] = useState<PipelineStep[]>([]);
  const [isPipelineRunning, setIsPipelineRunning] = useState(false);
  const [pipelineResults, setPipelineResults] = useState<ResearchResult[]>([]);
  const [activePipelineStepIndex, setActivePipelineStepIndex] = useState<number | null>(null);

  useEffect(() => {
    setHistoryResults([
      {
        title: "GR0K-NANO KERNEL: Quantum Entanglement Proof",
        abstract: "Verified a novel entanglement protocol using recursive axiomatic verification.",
        methodology: "Quantum-Neuro-Symbolic architecture with real-time Qubit coherence tracking.",
        resultsAnalysis: "Achieved 99.9% fidelity in simulated 64-qubit system.",
        conclusion: "Entanglement protocol confirmed stable and scalable for secure quantum comms.",
        configUsed: { topic: "Quantum Entanglement", duration: "10h", variable: "Qubit Coherence", core: ModelCore.GENESIS_PRO },
        type: InteractionMode.NANO_GRID,
        trendData: [], distributionData: [], trendLabelX: "", trendLabelY: "", trendTitle: "" 
      },
      {
        title: "GR0K-FORGE SYSTEM REPORT: Novel Material Synthesis",
        abstract: "Generated blueprints for a room-temperature superconductor using diffusion policies.",
        methodology: "Inverse design with material property constraints via deep symbolic regression.",
        resultsAnalysis: "Simulated synthesis pathways show high likelihood of success.",
        conclusion: "Potential for breakthrough in energy and computing.",
        configUsed: { topic: "Room-Temperature Superconductor", duration: "24h", variable: "Material Properties", core: ModelCore.MISTRAL },
        type: InteractionMode.EVAL_HARNESS,
        trendData: [], distributionData: [], trendLabelX: "", trendLabelY: "", trendTitle: "" 
      }
    ]);
    addPipelineStep(); // Add an initial step to the pipeline
  }, []);

  // Reset function for clearing all state related to interaction modes
  const resetInteractionStates = () => {
    setResult(null);
    setActiveHistoryItem(null);
    setState(AppState.IDLE);
    resetChat();
    setChatHistory([]);
    setQuotaError(null);
    setPipelineResults([]);
    setIsPipelineRunning(false);
    setActivePipelineStepIndex(null);
    setVramAllocation(16); // Reset VRAM to default
  };

  const handleModeChange = (newMode: SimulationMode) => {
    setMode(newMode);
    // When switching to offline, default core to Ollama if it was a cloud-only model
    if (newMode === SimulationMode.OFFLINE && (core === ModelCore.GENESIS_PRO || core === ModelCore.LLAMA_3 || core === ModelCore.MISTRAL || core === ModelCore.DEEPSEEK_PRO)) {
        setCore(ModelCore.OLLAMA); 
    } else if (newMode === SimulationMode.CLOUD && (core === ModelCore.OLLAMA || core === ModelCore.LLAMA_3_8B || core === ModelCore.DEEPSEEK_NANO)) {
        // When switching back to cloud, default to Genesis Pro if it was an offline-only model
        setCore(ModelCore.GENESIS_PRO);
    }
  };


  const handleSimulate = async () => {
    if (!prompt.trim() || interactionMode === InteractionMode.BTC_MINER) return;

    resetInteractionStates(); // Clear all previous states
    setState(AppState.SIMULATING);
    try {
      const data = await runSimulation(
          prompt, 
          mode, 
          ModelArchitecture.MODULAR, 
          interactionMode, 
          paradigm, 
          false,
          null,
          core,
          null,
          systemPrompt,
          vramAllocation // Pass VRAM allocation
      );

      setResult(data);
      setHistoryResults(prev => [{ ...data, title: `[${new Date().toLocaleString()}] ${data.title}` }, ...prev]);
      setState(AppState.COMPLETE);

    } catch (e: any) {
      if (e.isQuotaError) {
        setQuotaError({ message: e.message, actionRequired: true });
        setState(AppState.ERROR);
      } else {
        setErrorMsg(e.message || "System Error");
        setState(AppState.ERROR);
      }
    }
  };

  const handleSendMessage = async (text: string) => {
    const userMsg: ChatMessage = { role: 'user', content: text };
    setChatHistory(prev => [...prev, userMsg]);
    setIsChatLoading(true);
    setQuotaError(null); // Clear any previous quota errors

    const modelMsg: ChatMessage = { role: 'model', content: '' };
    setChatHistory(prev => [...prev, modelMsg]);

    await streamChatWithAgi(
        text,
        chatHistory,
        systemPrompt,
        (chunkText: string, chunkSources: WebSource[]) => {
            setChatHistory(prev => {
                const newHistory = [...prev];
                const lastMessage = newHistory[newHistory.length - 1];
                lastMessage.content = chunkText;
                lastMessage.webSources = chunkSources; 
                return newHistory;
            });
        },
        (message: string, isQuotaError: boolean) => { // onFatalError callback
            setQuotaError({ message, actionRequired: isQuotaError });
            setState(AppState.ERROR);
            setIsChatLoading(false); // Stop loading indicator
            resetChat(); // Reset the active chat session
        },
        (functionCalls: FunctionCall[]) => { // onToolCall callback
            for (const fc of functionCalls) {
                if (fc.name === 'controlPipeline') {
                    // Assuming args are { initialPrompt: string, steps: { type: string, model: string }[] }
                    const { initialPrompt, steps } = fc.args as { initialPrompt: string, steps: { type: PipelineStepType, model: ModelCore }[] };

                    const newPipelineSteps: PipelineStep[] = steps.map(s => ({
                        id: Date.now().toString() + Math.random().toString(), // Assign unique ID
                        type: s.type,
                        model: s.model,
                    }));

                    setPipelinePrompt(initialPrompt);
                    setPipelineSteps(newPipelineSteps);

                    resetInteractionStates(); // Clear chat history and other states
                    setInteractionMode(InteractionMode.DIFFUSION_PIPELINE); // Switch to pipeline builder

                    // Add a message to chat history to acknowledge the pipeline setup
                    setChatHistory(prev => [...prev, {
                        role: 'model',
                        content: `GR0K Core is configuring the multi-diffusion pipeline based on your request. Please review the steps below in the 'GR0K Pipeline' tab.`
                    }]);
                    setIsChatLoading(false); // Ensure loading is off after tool call
                }
            }
        },
        core, // Pass the selected core
        mode, // Pass the simulation mode
        vramAllocation // Pass VRAM allocation
    );

    setIsChatLoading(false);
  };

  const handleRunPipeline = async () => {
    if (!pipelinePrompt.trim() || pipelineSteps.length === 0) {
      setQuotaError({ message: "Please provide an initial prompt and at least one pipeline step.", actionRequired: false });
      return;
    }

    resetInteractionStates(); // Clear all previous states (including chat history if any)
    setIsPipelineRunning(true);
    setState(AppState.SIMULATING);
    setPipelineResults([]);

    try {
      const finalResult = await runDiffusionPipeline(
        pipelinePrompt,
        pipelineSteps,
        mode,
        systemPrompt,
        (stepIndex: number, stepResult: ResearchResult | null) => {
          setActivePipelineStepIndex(stepIndex);
          if (stepResult) {
            setPipelineResults(prev => [...prev, stepResult]);
          }
        },
        (message: string, isQuotaError: boolean) => { // onFatalError callback for pipeline
          setQuotaError({ message, actionRequired: isQuotaError });
          setState(AppState.ERROR);
          setIsPipelineRunning(false);
          setActivePipelineStepIndex(null);
        },
        vramAllocation // Pass VRAM allocation
      );

      if (finalResult) {
        setResult(finalResult);
        setHistoryResults(prev => [{ ...finalResult, title: `[${new Date().toLocaleString()}] PIPELINE: ${finalResult.title}` }, ...prev]);
        setState(AppState.COMPLETE);
      } else {
        setState(AppState.ERROR); // If finalResult is null, an error occurred
      }

    } catch (e: any) {
        setQuotaError({ message: e.message || "An unexpected error occurred during pipeline execution.", actionRequired: false });
        setState(AppState.ERROR);
    } finally {
        setIsPipelineRunning(false);
        setActivePipelineStepIndex(null);
    }
  };

  const handleMasterExport = async () => {
    if (!result) return;
    setIsExporting(true);

    try {
      const zip = new JSZip();

      const srcFolder = zip.folder("src");
      if (srcFolder) {
        Object.entries(CODE_FILES).forEach(([filename, content]) => {
          srcFolder.file(filename, content);
        });
      }

      const manifest = {
        project: result.title,
        timestamp: new Date().toISOString(),
        directive: systemPrompt,
        grounding_hash: result.dataAudit?.integrityHash,
        benchmarks: result.benchmarks
      };
      zip.file("manifest.json", JSON.stringify(manifest, null, 2));

      const reportElement = document.getElementById('research-paper-content');
      if (reportElement && (window as any).html2pdf) {
        const pdfBlob = await (window as any).html2pdf()
          .set({ margin: 10, filename: 'report.pdf', image: { type: 'jpeg', quality: 0.98 } })
          .from(reportElement)
          .output('blob');
        zip.file("research_report.pdf", pdfBlob);
      }

      const zipContent = await zip.generateAsync({ type: 'blob' });
      const link = document.createElement('a');
      link.href = URL.createObjectURL(zipContent);
      link.download = `GR0K_NANO_WORKSPACE_${Date.now()}.zip`;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);

    } catch (err) {
      console.error("Export Failed", err);
    } finally {
      setIsExporting(false);
    }
  };

  const handleSelectHistoryItem = (item: ResearchResult, index: number) => {
    resetInteractionStates(); // Clear all previous states
    setInteractionMode(InteractionMode.EVAL_HARNESS); // Switch to a mode that displays reports
    setResult(item);
    setActiveHistoryItem(index);
    setState(AppState.COMPLETE);
  };

  const handleSelectApiKey = async () => {
    if ((window as any).aistudio) {
      await (window as any).aistudio.openSelectKey();
      setQuotaError(null); // Dismiss error after user attempts to select key
      resetInteractionStates(); // Clear all states and reset
    }
  };

  // Pipeline Step Management
  const addPipelineStep = () => {
    setPipelineSteps(prev => [...prev, { id: Date.now().toString() + Math.random().toString(), type: PipelineStepType.TEXT_REFINEMENT, model: mode === SimulationMode.CLOUD ? ModelCore.GENESIS_PRO : ModelCore.OLLAMA }]);
  };

  const removePipelineStep = (id: string) => {
    setPipelineSteps(prev => prev.filter(step => step.id !== id));
  };

  const updatePipelineStep = (id: string, field: 'type' | 'model', value: PipelineStepType | ModelCore) => {
    setPipelineSteps(prev => prev.map(step => (step.id === id ? { ...step, [field]: value } : step)));
  };

  const movePipelineStep = (id: string, direction: 'up' | 'down') => {
    setPipelineSteps(prev => {
      const index = prev.findIndex(step => step.id === id);
      if (index === -1) return prev;

      const newIndex = direction === 'up' ? index - 1 : index + 1;
      if (newIndex < 0 || newIndex >= prev.length) return prev;

      const newSteps = [...prev];
      const [movedStep] = newSteps.splice(index, 1);
      newSteps.splice(newIndex, 0, movedStep);
      return newSteps;
    });
  };

  const MainContent = () => {
    if (interactionMode === InteractionMode.BTC_MINER) return <BtcMiner />;
    if (interactionMode === InteractionMode.AGI_CHAT) return <ChatInterface history={chatHistory} isLoading={isChatLoading} onSendMessage={handleSendMessage} />;
    if (interactionMode === InteractionMode.EVAL_HARNESS && result) return <PaperRenderer data={result} />; // For history view

    // Display pipeline results or single simulation result
    if (state === AppState.COMPLETE && result && (interactionMode === InteractionMode.NANO_GRID || interactionMode === InteractionMode.DIFFUSION_PIPELINE)) {
        return <PaperRenderer data={result} />;
    }

    // Pipeline Builder UI
    if (interactionMode === InteractionMode.DIFFUSION_PIPELINE) {
        return (
            <div className="flex-1 flex flex-col gap-6">
                <div className="bg-grok-bg-medium p-6 rounded-xl border border-grok-border-primary shadow-xl">
                    <label className="text-[10px] uppercase font-bold text-grok-text-medium tracking-wider mb-2 block flex items-center gap-1"><Sparkles size={10} /> GR0K Pipeline Initial Prompt</label>
                    <textarea 
                      value={pipelinePrompt}
                      onChange={(e) => setPipelinePrompt(e.target.value)}
                      placeholder="Enter the initial concept for the pipeline (e.g., 'A novel fusion energy schematic')..."
                      className="w-full h-24 p-3 bg-grok-bg-dark border border-grok-border-primary rounded-lg outline-none font-mono text-xs text-grok-accent-highlight placeholder-grok-text-dark resize-none leading-relaxed"
                      disabled={isPipelineRunning}
                    />

                    <h3 className="text-[10px] uppercase font-bold text-grok-text-medium tracking-wider mb-2 mt-6 flex items-center gap-1">
                        <Layers size={10} /> Diffusion Pipeline Steps
                    </h3>
                    <div className="space-y-4">
                        {pipelineSteps.map((step, index) => (
                            <div key={step.id} className={`flex items-center gap-3 p-3 rounded-lg border ${activePipelineStepIndex === index ? 'border-grok-accent-primary bg-grok-accent-primary/20' : 'border-grok-border-primary bg-grok-bg-light'} transition-all`}>
                                <span className={`text-[10px] font-bold ${activePipelineStepIndex === index ? 'text-grok-accent-primary' : 'text-grok-text-medium'}`}>STEP {index + 1}:</span>

                                <select
                                    value={step.type}
                                    onChange={(e) => updatePipelineStep(step.id, 'type', e.target.value as PipelineStepType)}
                                    className="flex-1 bg-grok-bg-dark border border-grok-border-primary rounded-md px-2 py-1 text-xs text-grok-text-light outline-none"
                                    disabled={isPipelineRunning}
                                >
                                    {Object.values(PipelineStepType).map(type => (
                                        <option key={type} value={type}>{type.replace(/_/g, ' ')}</option>
                                    ))}
                                </select>

                                <select
                                    value={step.model}
                                    onChange={(e) => updatePipelineStep(step.id, 'model', e.target.value as ModelCore)}
                                    className="flex-1 bg-grok-bg-dark border border-grok-border-primary rounded-md px-2 py-1 text-xs text-grok-text-light outline-none"
                                    disabled={isPipelineRunning}
                                >
                                    {/* Cloud Models */}
                                    <optgroup label="Cloud Models">
                                        <option value={ModelCore.GENESIS_PRO}>Genesis Pro (Cloud)</option>
                                        <option value={ModelCore.LLAMA_3}>Llama 3 (Cloud)</option>
                                        <option value={ModelCore.MISTRAL}>Mistral Large (Cloud)</option>
                                        <option value={ModelCore.DEEPSEEK_PRO} disabled={mode === SimulationMode.OFFLINE}>DeepSeek Pro (Cloud)</option>
                                    </optgroup>
                                    {/* Local/Offline Models */}
                                    <optgroup label="Local/Offline Models">
                                        <option value={ModelCore.OLLAMA}>Ollama (Local)</option>
                                        <option value={ModelCore.LLAMA_3_8B}>Llama 3 8B (Local Nano)</option>
                                        <option value={ModelCore.DEEPSEEK_NANO} disabled={mode === SimulationMode.CLOUD}>DeepSeek Nano (Local)</option>
                                    </optgroup>
                                </select>

                                <div className="flex items-center gap-1">
                                    <button onClick={() => movePipelineStep(step.id, 'up')} disabled={index === 0 || isPipelineRunning} className="p-1 rounded-md bg-grok-bg-dark hover:bg-grok-bg-medium text-grok-text-medium disabled:opacity-30"><ArrowUp size={14} /></button>
                                    <button onClick={() => movePipelineStep(step.id, 'down')} disabled={index === pipelineSteps.length - 1 || isPipelineRunning} className="p-1 rounded-md bg-grok-bg-dark hover:bg-grok-bg-medium text-grok-text-medium disabled:opacity-30"><ArrowDown size={14} /></button>
                                    <button onClick={() => removePipelineStep(step.id)} disabled={isPipelineRunning} className="p-1 rounded-md bg-grok-bg-dark hover:bg-grok-bg-medium text-grok-accent-error disabled:opacity-30"><Trash2 size={14} /></button>
                                </div>
                            </div>
                        ))}
                    </div>

                    <button onClick={addPipelineStep} disabled={isPipelineRunning} className="w-full mt-4 py-2 px-4 rounded-lg font-bold text-grok-text-dark flex items-center justify-center space-x-2 bg-grok-accent-status hover:bg-grok-accent-status/80 transition-all shadow-lg shadow-grok-accent-status/20 disabled:opacity-50">
                        <PlusCircle size={16} /> <span>Add Pipeline Step</span>
                    </button>

                    <button
                        onClick={handleRunPipeline}
                        disabled={isPipelineRunning || pipelineSteps.length === 0 || !pipelinePrompt.trim()}
                        className={`w-full py-3 px-4 mt-6 rounded-lg font-bold text-grok-text-dark flex items-center justify-center space-x-2 transition-all shadow-lg ${isPipelineRunning ? 'bg-grok-border-primary' : 'bg-grok-accent-primary hover:bg-grok-accent-highlight shadow-grok-accent-primary/20'}`}
                    >
                        {isPipelineRunning ? <><RefreshCw size={16} className="animate-spin mr-2"/> EXECUTING PIPELINE...</> : <><FastForward size={16} fill="currentColor" /> <span>RUN GR0K PIPELINE</span></>}
                    </button>
                </div>
                {isPipelineRunning && (
                    <LiveSimulation 
                        mode={mode} 
                        topic={pipelinePrompt} 
                        interactionMode={InteractionMode.DIFFUSION_PIPELINE} 
                        architecture={ModelArchitecture.MODULAR} 
                        pipelineActiveStepIndex={activePipelineStepIndex}
                        pipelineSteps={pipelineSteps}
                    />
                )}
            </div>
        );
    }

    // Default or initial state for NANO_GRID
    return (
      <div className={`hidden lg:flex flex-col items-center justify-center text-grok-text-medium border-2 border-dashed border-grok-border-primary rounded-xl m-4 bg-grok-bg-medium w-full`}>
         <div className="p-6 bg-grok-bg-light rounded-full mb-6 shadow-sm border border-grok-border-primary">
            {interactionMode === InteractionMode.NANO_GRID ? <Grid size={48} className="text-grok-accent-primary animate-pulse" /> : <Terminal size={48} className="text-grok-accent-highlight" />}
         </div>
         <p className="text-grok-text-light font-bold text-lg font-mono uppercase tracking-widest">
             {interactionMode === InteractionMode.NANO_GRID ? 'GR0K FORGE ACTIVE (DIFFUSION)' : 'AGENT.SYS READY'}
         </p>
         <p className="text-[10px] text-grok-text-medium mt-2">Awaiting dataset generation parameters...</p>
      </div>
    );
  };

  return (
    <div className="min-h-screen bg-grok-bg-dark text-grok-text-light flex flex-col font-sans">
      <nav className="bg-grok-bg-dark border-b border-grok-border-primary sticky top-0 z-50">
        <div className="max-w-7xl mx-auto px-4 h-16 flex items-center justify-between">
          <div className="flex items-center space-x-2 text-grok-accent-primary">
            <Zap size={20} className="animate-pulse" />
            <span className="font-bold text-lg tracking-tight text-grok-text-light uppercase">GR0K<span className="text-grok-accent-primary">.Forge</span></span>
          </div>
          <div className="flex items-center gap-4">
              {result && (
                <button 
                  onClick={handleMasterExport}
                  disabled={isExporting}
                  className="hidden md:flex items-center gap-2 bg-grok-accent-primary hover:bg-grok-accent-highlight text-grok-text-light px-4 py-1.5 rounded-lg text-[10px] font-bold uppercase transition-all shadow-lg shadow-grok-accent-primary/20 disabled:opacity-50"
                >
                  {isExporting ? <RefreshCw size={14} className="animate-spin" /> : <Archive size={14} />}
                  {isExporting ? 'Packaging GR0K...' : 'Export GR0K Workspace (.zip)'}
                </button>
              )}
              <div className="text-[9px] font-bold text-grok-accent-primary bg-grok-accent-primary/20 px-3 py-1 rounded-full border border-grok-accent-primary/30 uppercase tracking-widest">GR0K-NANO PIPELINE: ONLINE</div>
          </div>
        </div>
      </nav>

      <main className="flex-1 flex w-full max-w-7xl mx-auto p-4 md:p-8 gap-6">
        {/* API Quota Error Banner */}
        {quotaError && (
          <div className="absolute top-16 left-0 right-0 z-50 p-4 bg-grok-accent-error-bg text-grok-accent-error border-b border-grok-accent-error/50 shadow-lg flex items-center justify-between font-sans">
            <div className="flex items-center gap-3">
              <XCircle size={20} />
              <p className="text-sm font-bold">API ERROR: {quotaError.message}</p>
              {quotaError.actionRequired && (
                <a 
                  href="https://ai.google.dev/gemini-api/docs/billing" 
                  target="_blank" 
                  rel="noopener noreferrer" 
                  className="text-[10px] text-grok-accent-error underline ml-2 hover:text-grok-accent-error/80"
                >
                  Check billing & quota details
                </a>
              )}
            </div>
            {quotaError.actionRequired && (window as any).aistudio && (
              <button 
                onClick={handleSelectApiKey} 
                className="bg-grok-accent-error text-grok-bg-dark px-4 py-2 rounded-lg text-xs font-bold uppercase hover:bg-grok-accent-error/80 transition-all"
              >
                Select New API Key
              </button>
            )}
            <button 
              onClick={() => setQuotaError(null)} 
              className="p-1 rounded-full text-grok-accent-error hover:bg-grok-accent-error/20 transition-colors"
              title="Dismiss error"
            >
              <XCircle size={16} />
            </button>
          </div>
        )}

        {/* Left Sidebar Menu */}
        <div className="w-64 flex-shrink-0 bg-grok-bg-medium rounded-xl border border-grok-border-primary shadow-xl p-4 flex flex-col gap-6">
            <div className="mb-4">
                <label className="text-[10px] uppercase font-bold text-grok-text-medium tracking-wider mb-2 block flex items-center gap-1"><Server size={10} /> Neural Runtime</label>
                <div className="grid grid-cols-2 gap-2 text-center text-xs font-bold">
                    <button onClick={() => handleModeChange(SimulationMode.CLOUD)} className={`p-2 rounded-lg border transition-all ${mode === SimulationMode.CLOUD ? 'bg-grok-accent-primary/30 text-grok-accent-primary border-grok-accent-primary/50' : 'bg-grok-bg-light text-grok-text-medium border-grok-border-primary'}`}>CLOUD ENGINE</button>
                    <button onClick={() => handleModeChange(SimulationMode.OFFLINE)} className={`p-2 rounded-lg border transition-all ${mode === SimulationMode.OFFLINE ? 'bg-grok-user-chat-bg/30 text-grok-accent-highlight border-grok-user-chat-bg/50' : 'bg-grok-bg-light text-grok-text-medium border-grok-border-primary'}`}>LOCAL CORE</button>
                </div>
            </div>

            <div className="flex flex-col gap-2">
                <button 
                    onClick={() => { resetInteractionStates(); setInteractionMode(InteractionMode.NANO_GRID); }} 
                    className={`flex items-center p-3 rounded-lg border text-sm font-bold transition-all ${interactionMode === InteractionMode.NANO_GRID ? 'bg-grok-accent-primary text-grok-text-dark border-grok-accent-primary' : 'bg-grok-bg-light text-grok-text-medium border-grok-border-primary hover:bg-grok-bg-dark'}`}
                >
                    <Grid size={16} className="mr-3"/> GR0K FORGE (DIFFUSION)
                </button>
                <button 
                    onClick={() => { 
                        resetInteractionStates(); 
                        setInteractionMode(InteractionMode.AGI_CHAT); 
                        // Set default core based on current mode
                        setCore(mode === SimulationMode.CLOUD ? ModelCore.GENESIS_PRO : ModelCore.OLLAMA); // Default to Genesis Pro for cloud, Ollama for offline
                    }} 
                    className={`flex items-center p-3 rounded-lg border text-sm font-bold transition-all ${interactionMode === InteractionMode.AGI_CHAT ? 'bg-grok-accent-primary text-grok-text-dark border-grok-accent-primary' : 'bg-grok-bg-light text-grok-text-medium border-grok-border-primary hover:bg-grok-bg-dark'}`}
                >
                    <MessageSquare size={16} className="mr-3"/> GR0K CHAT
                </button>
                <button 
                    onClick={() => { resetInteractionStates(); setInteractionMode(InteractionMode.DIFFUSION_PIPELINE); }} 
                    className={`flex items-center p-3 rounded-lg border text-sm font-bold transition-all ${interactionMode === InteractionMode.DIFFUSION_PIPELINE ? 'bg-grok-accent-primary text-grok-text-dark border-grok-accent-primary' : 'bg-grok-bg-light text-grok-text-medium border-grok-border-primary hover:bg-grok-bg-dark'}`}
                >
                    <Layers size={16} className="mr-3"/> GR0K PIPELINE (MULTI-DIFFUSION)
                </button>
            </div>

            {/* Core Selection for NANO_GRID AND AGI_CHAT mode */}
            {(interactionMode === InteractionMode.NANO_GRID || interactionMode === InteractionMode.AGI_CHAT) && (
                <div className="mb-4">
                    <label className="text-[10px] uppercase font-bold text-grok-text-medium tracking-wider mb-2 block flex items-center gap-1"><Cpu size={10} /> GR0K CORE SELECTION</label>
                    <select
                        value={core}
                        onChange={(e) => setCore(e.target.value as ModelCore)}
                        className="w-full bg-grok-bg-light border border-grok-border-primary rounded-lg px-3 py-2 text-xs text-grok-text-light outline-none"
                    >
                        <optgroup label="Cloud Models">
                            <option value={ModelCore.GENESIS_PRO} disabled={mode === SimulationMode.OFFLINE}>Genesis Pro (Cloud)</option>
                            <option value={ModelCore.LLAMA_3} disabled={mode === SimulationMode.OFFLINE}>Llama 3 (Cloud)</option>
                            <option value={ModelCore.MISTRAL} disabled={mode === SimulationMode.OFFLINE}>Mistral Large (Cloud)</option>
                            <option value={ModelCore.DEEPSEEK_PRO} disabled={mode === SimulationMode.OFFLINE}>DeepSeek Pro (Cloud)</option>
                        </optgroup>
                        <optgroup label="Local/Offline Models">
                            <option value={ModelCore.OLLAMA} disabled={mode === SimulationMode.CLOUD}>Ollama (Local)</option>
                            <option value={ModelCore.LLAMA_3_8B} disabled={mode === SimulationMode.CLOUD}>Llama 3 8B (Local Nano)</option>
                            <option value={ModelCore.DEEPSEEK_NANO} disabled={mode === SimulationMode.CLOUD}>DeepSeek Nano (Local)</option>
                        </optgroup>
                    </select>
                </div>
            )}

            {/* New: VRAM Allocation for Diffusion-related modes */}
            {(interactionMode === InteractionMode.NANO_GRID || interactionMode === InteractionMode.DIFFUSION_PIPELINE) && (
                <div className="mb-4">
                    <label className="text-[10px] uppercase font-bold text-grok-text-medium tracking-wider mb-2 block flex items-center gap-1"><Dna size={10} /> VRAM ALLOCATION (GB)</label>
                    <select
                        value={vramAllocation}
                        onChange={(e) => setVramAllocation(Number(e.target.value))}
                        className="w-full bg-grok-bg-light border border-grok-border-primary rounded-lg px-3 py-2 text-xs text-grok-text-light outline-none"
                    >
                        <option value={4} disabled={mode === SimulationMode.CLOUD}>4 GB</option>
                        <option value={8} disabled={mode === SimulationMode.CLOUD}>8 GB</option>
                        <option value={16}>16 GB</option>
                        <option value={24}>24 GB</option>
                        <option value={32}>32 GB</option>
                        <option value={64} disabled={mode === SimulationMode.CLOUD}>64 GB</option>
                    </select>
                </div>
            )}


            {/* History Section */}
            <div className="flex-1 overflow-y-auto">
                <h3 className="text-[10px] uppercase font-bold text-grok-text-medium tracking-wider mb-2 mt-4 flex items-center gap-1">
                    <History size={10} /> History & Memory
                </h3>
                <ul className="space-y-1">
                    {historyResults.map((item, index) => (
                        <li key={index}>
                            <button
                                onClick={() => handleSelectHistoryItem(item, index)}
                                className={`w-full text-left p-2 rounded-lg text-xs transition-all flex items-start group ${activeHistoryItem === index ? 'bg-grok-accent-primary/20 text-grok-accent-primary border border-grok-accent-primary/30' : 'bg-grok-bg-dark text-grok-text-medium hover:bg-grok-bg-light border border-grok-border-secondary'}`}
                            >
                                <BookOpen size={12} className={`mr-2 flex-shrink-0 ${activeHistoryItem === index ? 'text-grok-accent-primary' : 'text-grok-text-dark group-hover:text-grok-text-light'}`}/>
                                <span className={`flex-1 text-xs leading-tight ${activeHistoryItem === index ? 'text-grok-accent-primary font-bold' : 'text-grok-text-medium group-hover:text-grok-text-light'}`}>
                                    {item.title}
                                    <br/>
                                    <span className="text-[9px] text-grok-text-dark block mt-1">({item.configUsed.topic})</span>
                                </span>
                            </button>
                        </li>
                    ))}
                    {historyResults.length === 0 && (
                        <li className="text-xs text-grok-text-dark italic p-2">No history yet.</li>
                    )}
                </ul>
            </div>
        </div>

        {/* Main Content Area */}
        <div className="flex-1 flex flex-col gap-6">
           {interactionMode === InteractionMode.NANO_GRID && (
              <div className="bg-grok-bg-medium p-6 rounded-xl border border-grok-border-primary shadow-xl">
                    <label className="text-[10px] uppercase font-bold text-grok-text-medium tracking-wider mb-2 block flex items-center gap-1"><Sparkles size={10} /> GR0K Master Directive</label>
                    <textarea 
                      value={systemPrompt}
                      onChange={(e) => setSystemPrompt(e.target.value)}
                      placeholder="Enter GR0K training directive..."
                      className="w-full h-40 p-3 bg-grok-bg-dark border border-grok-border-primary rounded-lg outline-none font-mono text-[10px] text-grok-accent-highlight placeholder-grok-text-dark resize-none leading-relaxed"
                    />
                    <label className="block text-xs font-bold text-grok-text-medium uppercase tracking-wider mb-2 mt-4">GR0K Reasoning Objective (e.g. Riemann Hypothesis Proof)</label>
                    <textarea 
                        value={prompt}
                        onChange={(e) => setPrompt(e.target.value)}
                        placeholder="Enter objective..."
                        className="w-full h-24 p-4 bg-grok-bg-dark border border-grok-border-primary rounded-lg outline-none resize-none font-mono text-xs text-grok-accent-highlight placeholder-grok-text-dark"
                    />
                    <button
                        onClick={handleSimulate}
                        disabled={state === AppState.SIMULATING || !prompt}
                        className={`w-full py-3 px-4 mt-4 rounded-lg font-bold text-grok-text-dark flex items-center justify-center space-x-2 transition-all shadow-lg ${state === AppState.SIMULATING ? 'bg-grok-border-primary' : 'bg-grok-accent-primary hover:bg-grok-accent-highlight shadow-grok-accent-primary/20'}`}
                    >
                        {state === AppState.SIMULATING ? <><RefreshCw size={16} className="animate-spin mr-2"/> COMPILING GR0K...</> : <><FastForward size={16} fill="currentColor" /> <span>INITIALIZE GR0K CORE</span></>}
                    </button>
              </div>
           )}

           {state === AppState.SIMULATING && interactionMode !== InteractionMode.BTC_MINER && interactionMode !== InteractionMode.DIFFUSION_PIPELINE && (
             <LiveSimulation mode={mode} topic={prompt} interactionMode={interactionMode} architecture={ModelArchitecture.MODULAR} />
           )}

           {interactionMode === InteractionMode.NANO_GRID && (state === AppState.IDLE || state === AppState.COMPLETE || state === AppState.ERROR) && (
             <div className="flex-1 min-h-[400px]">
                <CodeViewer />
             </div>
           )}

           {/* Dynamic Main Content */}
           <MainContent />
        </div>
      </main>
    </div>
  );
}
